\emph{Projected dynamical systems }\cite{Cojocaru2003}:
Given an map $\mc{F}:\R^n\rightarrow \R^n$ and a closed convex set $S\subseteq \R^n$, we consider the projected dynamical system
\begin{align}\label{eq:projdyn} \dot{x}=\Pi_S(x,\mc{F}(x)), \qquad x(0)=x_0\in S.
\end{align}
In \eqref{eq:projdyn}, the projection operator is possibly discontinuous on the boundary of
$S$. If $\mc{F}$ is Lipschitz on $S$, the system \eqref{eq:projdyn} admits a unique global Carathéodory solution, i.e., there exists a unique absolutely continuous function $x:\R_{\geq 0}\rightarrow \R^n$ such that $x(0)=x_0$, $\dot{x}(t)=\Pi_S(x,g(x))$ for almost all $t$. Moreover, $x(t)\in S$ for all $t\geq 0$, as on the boundary of $S$ the projection operator
restricts the flow of $\mc{F}$ such that the solution of \eqref{eq:projdyn} remains in $S$ (while $\Pi_S(x,\mc{F}(x))=\mc{F}(x)$ if $x\in \rm{int}(S)$).


\emph{Monotone control systems} \cite{EncisoSontag_Global2006}: Let $\mathcal{K}\subset \R^n$ be an orthant, i.e., $\K = \{x \in \R^n \mid  (-1)^{\epsilon_i} x_i  \geq 0 , \forall i \in \{1,2,\dots,n\} \}$, for some binary vector $(\epsilon_1,\epsilon_2,\dots\epsilon_n)\in \{0,1\}^n$. Then, $\K$ induces
% \subset \R^n$ be a closed, convex,  pointed (i.e., $\mathcal{K} \cap (- \mc K) = \{ \0 \} $) cone, which has a nonempty interior  for brevity, we will say that $\mathcal{K}$ is ``admissible''. As an example, $\K$ can be any orthant, e.g., $\K = \R^n_{\geq 0}$. The cone $\mc K$ induces
the partial order ``$\succcurlyeq_{\mc K}$''  in $\R^n$, where 
 \begin{align}
    x \seq_{\mc K} y \iff x - y \in \mc K. \end{align}
For instance, the nonnegative orthant $\K = \R^n_{\geq 0}$ induces the standard (elementwise) ordering. 
Let us consider a dynamical system 
\begin{align}\label{eq:introsystem}
    \dot x = f (x,u), \quad y = g(x),
\end{align} with state space $X \subseteq \R^n$, input space $U \subseteq \R^m$, output space $Y \subseteq \R^p$. For a measurable, locally bounded input function $u:\R_{\geq 0}\rightarrow U$ and an initial condition $x_0 \in \R^n$, let $x(t,x_0,u) \in U$  be the corresponding solution of   \eqref{eq:introsystem} at time $t$ (assuming it is well defined; we always consider solutions in the Carath\'eodory sense in this paper). Consider the orders induced by  by three orthants $\K_X \subset \R^q$, $\K_U \subset \R^m$, $\K_Y \subset \R^p$. Then, the dynamical system is \emph{monotone} if: (1) for any two inputs $u,u'$ such that $u(t) \seq_{\K_U} u'(t)$ for almost all $t$, and for any two initial conditions $x_0 \seq_{\K_X} x_0'$, it holds that: (1) for all $t \geq 0$, 
\begin{align}
x(t,x_0,u) \seq_{K_X} x(t,x_0',u');
\end{align}
(2) the output map $g$ is nondecreasing, namely \begin{align}
    x \seq_{K_X} x'  \Rightarrow g(x) \seq_{\K_Y} g(x').
\end{align} 
There are several ways to check if a system is monotone without computing its solutions, e.g., see \cite[§2.1]{Angeli2004}. For instance, a smooth system is monotone with respect to the standard ordering ($\K_U =\R^m_{\geq 0}$ $, \K_X= \R^n_{\geq 0}$, $\K_Y =\R^p_{\geq 0}$) if and only if, for all $x\in X$, $u\in U$,
\begin{align}\label{eq:MonCondition}
\begin{aligned}\textstyle (\forall i\neq j) &  \textstyle  \qquad \frac{\partial f_i}{\partial x_j} (x,u) \geq 0  
\\
(\forall i,j,l) & \textstyle  \qquad  \frac{\partial f_i}{\partial u_j} (x,u) \geq 0, \quad \frac{\partial h_l}{\partial x_i}(x) \geq 0.
\end{aligned}
\end{align}
In particular, a linear system $\dot x = Ax+Bu$, $y = Cx$, is monotone if $A$ is Metzler and $B,C$ are nonnegative. 

We say that system \eqref{eq:introsystem} has a  steady-state map $k_x :U\rightarrow X$ if, for every constant input $\hat u(t) \equiv \bar u  \in U$ and independently of $x_0\in\R^n$, the solution $x(t,x_0,\bar u )$ converges to $k_x ( u)$ as $t\rightarrow \infty$. In this case, we define the  steady state output map as $k_y = g\circ k_x$. 


We will use the following result, which can be obtained as a special case of \cite[Th.~2]{EncisoSontag_Global2006} (see Appendix~\ref{app:proofofSGT}). 

\begin{lemma}[Small gain theorem]\label{lem:SGT}
    Let the following conditions hold:
    \begin{enumerate}
        \item $U = Y = \R^m$, and $X$ is a convex closed (possibly unbounded) box, i.e., $X$ is the  Cartesian product of closed intervals in $\R$;
        \item the system \eqref{eq:introsystem} is monotone with respect to some orthants $\K_U,\K_X,\K_Y$, and $\K_Y = -\K_U$ (i.e., the output is ordered by the opposite order of the input); 
        \item The system admits a continuous steady-state map $k_x$; furthermore, $g$ is continuous. 
        \item (\emph{small gain condition}) For any $u_0\in U$, the iteration
        \begin{align}
            u_{n+1} = k_y(u_n) = k_x(g(u_n)) 
        \end{align}
        converges to a unique $u^\star \in U$. 
    \end{enumerate}
    Then, all bounded solutions of the closed-loop system
    \begin{align*}
        \dot x = f(x,g(x))
    \end{align*}
    converge to $x^\star = k_x (u^\star) $.
\end{lemma}

