\section{Preliminaries}
\label{sec:prelim}

\subsection{Notation}
We let $\log$ denote the base-2 logarithm, and $\ln$ denote the base-$e$ logarithm. For a list of vectors $v_1,\dots, v_n$, we will denote the tuple $v_{\le i} \coloneqq (v_1, v_2, \dots, v_i)$ and $V_i = \Span(v_{\le i})$ (by convention, $V_0 = \{0\}$). We will use the convention $0^0=1$. Throughout this paper, we always have $\ell = \ell(n) \coloneqq \log n$ and $n$ a power of 2. $\F_2$ is the finite field over $\{0,1\}$. For a set $S$, we write $s\sim S$ to denote that $s$ is sampled uniformly at random from $S$.

\begin{definition}
\label{defn:maxload}
Let $h: A\to B$ and $S\subset A$ be a subset. We define the maximum load function \[M(S,h) \coloneqq  \max_{y\in B}|h^{-1}(y)\cap S|.\] 
\end{definition}
%If $A = B$, then we will define $h^{(m)} = h\circ h\circ\cdots \circ h$ to be $m$-fold composition of $h$ with itself (with $h^{(0)}$ being the identity function).

\subsection{Inequalities}
We will use the classic inequality $1+x\le e^x$ for all $x$, and the following not-so-classic variant.
\begin{fact}
\label{fact:expineq}
    For $x< 1$, we have $1-x\ge e^{-\frac{x}{1-x}}$.
\end{fact}
\begin{proof}
    Note $\frac{1}{1-x} = 1 + \frac{x}{1-x}\le e^{\frac{x}{1-x}}$. When $x<1$, both sides of the inequality are positive, and taking reciprocals gives the fact.
\end{proof}

We will also use Bernoulli's Inequality.
\begin{fact}
    \label{claim:silly}
    For an integer $n\ge 1$ and $1+x\ge 0$, $(1+x)^n\ge 1+nx$.
\end{fact}

Finally, for the two-sided bounds, we will use standard facts about martingales, such as the Doob martingale and an elementary version of Azuma's inequality \cite[Chapter 12]{mitzupfal}. 

\begin{fact}
\label{fact:azuma}
    Let $(X_i)_{i\ge 0}$ be a martingale such that for all $i$, $|X_{i+1}-X_i|\le 1$. Then for all positive integers $k$ and real number $\eps > 0$, we have \[\Pr[X_k-X_0\le -\eps]\le e^{-\eps^2/2k}.\]
\end{fact}

\subsection{Random Linear Maps}
If $h:\F_2^u\to\F_2^\ell$ is a linear map with kernel $V\leq \F_2^u$ and $y$ is in the image of $h$, then $h^{-1}(y) = x+V$ for some $x\in \F_2^u$. A random \emph{surjective} linear map $h: \F_2^u\to\F_2^\ell$ is equivalent to sampling a uniform $(u-\ell)$-dimensional subspace $V\leq \F_2^u$, and then sampling a uniform linear $h$ with kernel $V$. For any $u\ge t\ge \ell$ and surjective map $h_2:\F_2^t\to \F_2^\ell$, if $h_1:\F_2^u\to\F_2^t$ is a uniform random linear map, then $h_1\circ h_2: \F_2^u\to\F_2^\ell$ is a uniform random linear map.  



\section{Introducing the Potential Functions}
\label{sec:assocfuncpotential}
Consider $k$ vectors $v_{\le k}\in (\F_2^u)^k$ and a set of balls $S\subset \F_2^u$. Recall $V_i = \Span(v_{\le i})$. To $(v_{\le k}, S)$ we will associate functions $\{S_i: \F_2^u\to\N \}_{0\le i \le k}$, defined by \begin{equation}S_i(x) \coloneqq |(x+V_i)\cap S|.\end{equation} In particular, $S_i$ depends on $S$ and $v_{\le i}$. Intuitively, $S_0$ is (the indicator of) $S$, and $S_i(x)$ is the number of balls in the same bin as $x$ after hashing according to the kernel vectors $v_{\le i}$.

 %For a set of vectors $v_{\le k}\subset \F_2^u$ and a set $S\subset \F_2^u$, we will \emph{associate} functions $\{S_i\}_{0\le i \le k}$ mapping $\F_2^u\to \N$, defined as follows. \begin{align}S_{i}(x) \coloneqq \begin{cases} \mathbf{1}(x\in S) & i = 0 \\  S_{i-1}(x) + S_{i-1}(x+v_i) &  i\ge 1\end{cases}\label{eqn:assoc}\end{align} Intuitively, $S_0$ is simply (the indicator of) $S$, and in general $S_i(x)$ is the number of balls in the same bin as $x$ after hashing according to the kernel vectors $v_{\le i}$.

 % More formally, notice if $\{v_i\}_{i\in [k]}$ are linearly independent, we have the following, where $V_i \coloneqq \Span(v_{\le i})$.
%\begin{proposition}\label{clam:Sinduct} If $\{v_{\le i}\}$ are linearly independent vectors in $\F_2^u$, then \[S_i(x) = \sum_{v\in V_i} S_0(x + v) = |(x + V_i)\cap S|.\]\end{proposition}

%\begin{proof}
%    We apply induction on $i$. The base case is true because \[|(x+V_0)\cap S| = |\{x\}\cap S| = {\mathbf 1}(x\in S) = S_0(x).\] Assume the proposition holds true for $i$. We then have for $v_{i+1}\notin V_i$ that \[S_{i+1}(x) = S_i(x) + S_i(x+v_{i+1}) = |(x + V_i)\cap S| + |(x + v_{i+1} + V_i)\cap S| = |(x+V_{i+1}) \cap S|,\] where the last equality follows from the fact $V_i$ and $v_{i+1} + V_i$ partition $V_{i+1}$, since $v_{i+1}\notin V_i$.
%\end{proof}

Now for any real number $b \ge 0$, we can define a sequence of potential functions \begin{equation*}\Phi_i = \Phi_i(S;b; v_{\le i})\coloneqq \E_{x\sim \F_2^u}[b^{S_i(x)}].\end{equation*} The following claim shows that if $b\ge 1$, a heavy bin implies large potential.

\begin{lemma}


\label{clm:potential-load}
\label{clm:load-potential}
    Let $v_{\le i}$ be a fixed tuple of linearly independent vectors in $\F_2^u$, and let $b \ge 1$. If there exists $x\in \F_2^u$ such that $|(x+V_i)\cap S|\ge m$, then $\Phi_i \ge \frac{b^m}{2^{u-i}}$.
\end{lemma}

\begin{proof}
    If $v\in V_i$, then $v+V_i = V_i$. Hence, for all $v\in V_i$, $S_i(x+v) = S_i(x)\ge m$. Therefore, \[\Phi_i = \frac{1}{2^u}\sum_{x'\in \F_2^u} b^{S_i(x')}\ge \frac{1}{2^u}\sum_{x'\in x+V_i} b^{S_i(x')}\ge \frac{1}{2^u}  |V_i|b^m = \frac{b^m}{2^{u-i}},\]
    where we used the fact $b^x$ is increasing for $b\ge 1$.
\end{proof}

Interestingly, if we use a base $b\le 1$, we can detect by the same test if some bin is light as well. This will help us establish two-sided bounds on the bins later on.

\begin{lemma}
\label{clm:blanketing}
Let $v_{\le i}$ be a fixed tuple of linearly independent vectors in $\F_2^u$, and let $b \le 1$. If there exists $x\in \F_2^u$ with $|(x + V_i)\cap S| \le m$, then $\Phi_i \ge \frac{b^m}{2^{u-i}}$.
\end{lemma}

\begin{proof}
    The proof is essentially the same as \Cref{clm:load-potential}. We observe that for all $v\in V_i$, ${S_i(x+v) \le m.}$ Hence, \[\Phi_i = \frac{1}{2^u}\sum_{x'\in \F_2^u} b^{S_i(x')}\ge \frac{1}{2^u}\sum_{x'\in x+V_i} b^{S_i(x')}\ge \frac{1}{2^u}  |V_i|b^m = \frac{b^m}{2^{u-i}},\] where we used the fact $b^x$ is decreasing for $b\le 1$.
\end{proof}

The following claim relates $S_i$ to $S_{i+1}$.

\begin{claim}
\label{clm:induct-defn}
For any vectors $v_{\le (i+1)}$, we have
    \[S_i(x)+S_i(x+v_{i+1}) = \begin{cases}2S_i(x) & v_{i+1}\in V_i \\ S_{i+1}(x) & v_{i+1}\notin V_i\end{cases}.\]
\end{claim}

\begin{proof}
If $v_{i+1}\in V_i$, then $V_i = v_{i+1}+V_i$, and so \[S_i(x) + S_i(x+v_{i+1}) = S_i(x) + S_i(x) = 2S_i(x).\] If $v_{i+1}\notin V_i$, then $V_{i+1} = V_i\sqcup (v_{i+1}+V_i)$. Thus, $(x+V_i)\cap S$ and $(x+v_{i+1}+V_i)\cap S$ partition $(x+V_{i+1})\cap S$, implying that $S_i(x) + S_i(x+v_{i+1}) = S_{i+1}(x).$
\end{proof}
Using the above claim, we can prove the following crucial lemma which upper bounds the conditional expectations of our potentials. 

\begin{lemma}
\label{clm:expsquare}
    Let $v_{\le i}\in (\F_2^u)^i$, and let $v_{i+1}\sim \F_2^u\setminus V_i$. We have \[\E_{v_{i+1} }[\Phi_{i+1} ] \le \Phi_i^2.\]
\end{lemma}

\begin{proof}
    For $x,v_{i+1}\in \F_2^u$ picked uniformly and independently, $x$ and $x+v_{i+1}$ are uniform and independent as well. Hence \begin{equation}\E_{x,v_{i+1}}[b^{S_i(x) + S_i(x+v_{i+1})}] = \E_{x,v_{i+1}}[b^{S_i(x) + S_i(v_{i+1})}] = \E_x[b^{S_i(x)}]\cdot \E_{v_{i+1}}[b^{S_i(v_{i+1})}] = \Phi_i^2.\label{eqn:global-avg}\end{equation}  Now for any fixed $v_{i+1}\in V_i$, we have \begin{equation}\E_{x}[b^{S_i(x) + S_i(x+v_{i+1})}] = \E_x[b^{2S_i(x)}]\ge \E_x[b^{S_i(x)}]^2 = \Phi_i^2\label{eqn:above-avg}\end{equation} by \Cref{clm:induct-defn} and convexity. By an averaging argument, (\ref{eqn:global-avg}) and (\ref{eqn:above-avg}) imply \begin{align*}\Phi_i^2 & \ge \E_{x,v_{i+1}}[b^{S_i(x) + S_i(x+v_{i+1})}|v_{i+1}\notin V_i] \\ & = \E_{x,v_{i+1}}[b^{S_{i+1}(x)}|v_{i+1}\notin V_i] \\ &  = \E_{v_{i+1}}[\Phi_{i+1}|v_{i+1}\notin V_i],\end{align*} where the first equality follows from \Cref{clm:induct-defn}.
\end{proof}

%\begin{proposition}
%\label{clm:expsquare}
%    Let $v_{\le i}$ be linearly independent vectors in $\F_2^u$, and let $W$ be the uniform distribution over $ \F_2^u\setminus V_i$. Then we have \[\E_{v_{i+1} \sim W}[\Phi_{i+1}] \le \Phi_i^2.\]
%\end{proposition}

%\begin{proof}
%For any fixed linearly independent $v_{\le i}$, if $v_{i+1}$ is picked uniformly at random from \emph{all} of $\F_2^u$, \begin{align*}\E_{v_{i+1}}[\Phi_{i+1}]  = \E_{v_{i+1}}[\E_x[b^{S_{i+1}(x)}]]    = \E_{x,v_{i+1}}[b^{S_i(x) + S_i(x+v_{i+1})}]   = \E_x[b^{S_i(x)}]^2  &  = \Phi_i^2,\end{align*} where the penultimate inequality follows from the fact $x$ and $x+v_{i+1}$ are independent random variables. Whenever $v_{i+1}\in V_i$, it follows by \Cref{clam:Sinduct} that \[S_i(x+v_{i+1}) = |(x + v_{i+1} + V_i)\cap S| = |(x + V_i)\cap S|= S_i(x).\] Therefore by \Cref{eqn:assoc}, if $v_{i+1}\in V_i$, then \[\Phi_{i+1} = \E_x [b^{S_{i+1}(x)}] = \E_x [b^{2S_{i}(x)}] \ge \E_x [b^{S_i(x)}]^2 = \Phi_i^2 \] via Jensen's inequality. Consequently by an averaging argument, it must be the case \[\E_{v_{i+1}\sim W}[\Phi_{i+1}] \le \Phi_i^2.\]
%\end{proof}

At a high level, we will use \Cref{clm:expsquare} to upper bound the potential, from which \Cref{clm:potential-load} implies a small max-load.

While the above suffices to get decent tail bounds on the max-load, for technical reasons we will need the following lemma, which is essential to establishing optimal expected max-load and quantitatively stronger two-sided bounds.

\begin{lemma}
\label{prop:strides}
Let $v_{\le i}\in (\F_2^u)^i$, and $v_{i+1}\in \F_2^u\setminus V_i$. For any $b\ge 0$ we have $\Phi_{i+1}-1\ge 2(\Phi_i - 1)$. When $b\le 1$, we also have $\Phi_{i+1}\le \Phi_i$.
\end{lemma}

\begin{proof}

By \Cref{clm:induct-defn}, elementary manipulations, and linearity of expectation,
    \begin{align*}\Phi_{i+1}-1 &  = \E_x[b^{S_i(x) + S_i(x+v_{i+1})}-1] \\ &  = \E_x[b^{S_i(x)}-1]+\E_x[b^{ S_i(x+v_{i+1})}-1] +\E_x[ b^{S_i(x)+S_i(x+v_i)}-b^{S_i(x)} -b^{S_i(x+v_{i+1})} +  1] \\ & = 2\E_x[b^{S_i(x)}-1] + \E_x[( b^{S_i(x)}-1)(b^{S_i(x+v_{i+1})}-1)] \\ & \ge 2(\Phi_i-1),\end{align*}
 where the inequality follows from the fact for any $b,r,s\ge 0$,  $b^r-1$ and $b^s-1$ have the same sign. When $b\le 1$, \Cref{clm:induct-defn} and the fact $f(r) =b^r$ is decreasing tells us \[\Phi_{i+1} = \E_x[b^{S_i(x)+S_i(x+v_{i+1})}]\le \E_x[b^{S_i(x)}] = \Phi_i. \]

\end{proof}

\section{Warmup: Optimal Max-Load With .99 Probability}
\label{sec:whp}

In this section, we will use the potentials we constructed to show that a random linear map has maximum load $O\left(\frac{\log n}{\log\log n}\right)$ with probability $0.99$.

\subsection{The Existential Case}

 To give intuition on how the potential functions will be used, we first prove a preliminary result. We will show that for any choice of $n$ balls, there \emph{exists} a linear hash map that has a maximum load of $\frac{2\ln n}{\ln\ln n}$. To the best of our knowledge, even this existential result was not known prior to our work. Recall \Cref{defn:maxload}.
\begin{theorem}
\label{thm:hashingexistence}
    Let $u\ge \ell\ge 1$ be integers, $n\coloneqq 2^\ell$, and $S\subset\F_2^{u}$ be of cardinality $n$. There exists a linear map $h: \F_2^{u}\to\F_2^\ell$ such that \[M(S,h) < \frac{2\ln n}{\ln\ln n}.\] 
\end{theorem}

\begin{proof}
Define $k\coloneqq u-\ell$. We will carefully pick linearly independent kernel vectors $v_{\le k}$ from $\F_2^{u}$, and then argue that any linear  $h: \F_2^u\to\F_2^\ell$ with kernel $V\coloneqq \text{Span}(v_{\le k})$ will have small maximum load.

Using the vectors $v_{\le k}$ and set $S$, define $\{S_i(x)\coloneqq |(x+V_i)\cap S|\}_{0\le i\le k}$ and define potentials $\{\Phi_i \coloneqq \E_{x\sim \F_2^u}[b^{S_i(x)}]\}_{0\le i\le k}$ for $b = \ln n$. As $|S| = n$, we can compute \[\Phi_0 = \E_x[b^{S_0(x)}] = \frac{n}{2^u}\cdot b + \left(1-\frac{n}{2^u}\right)\cdot 1\le 1 + \frac{\ln n}{2^k}.\]

By \Cref{clm:expsquare}, for $i = 1,2,\dots, k$ we can iteratively pick $v_{i+1}\notin \text{Span}(v_{ \le i})$ such that $\Phi_{i+1}\le \Phi_i^2$. Upon picking these $k$ linearly independent vectors $v_{\le k}$ in this manner, we claim any $h$ with $\text{Span}(v_{\le k}) \eqqcolon V$ as the kernel will yield the desired result. To see this, first notice \[\Phi_k \le  \Phi_{k-1}^2 \le  \cdots \le \Phi_0^{2^k} \le \left(1+\frac{\ln n}{2^k}\right)^{2^k} < e^{\ln n} = n.\] Assume there was $y$ such that $|h^{-1}(y)\cap S| \ge \frac{2\ln n}{\ln\ln n} $. Then there must exist $x$ such that ${|(x+V)\cap S|}\ge  \frac{2\ln n}{\ln\ln n}$. But by \Cref{clm:potential-load}, this implies \[\Phi_k \ge  \frac{(\ln n)^{\frac{2\ln n}{\ln \ln n}}}{2^{u-k}} =  \frac{n^2}{2^\ell} = n,\] absurd!
\end{proof}

\subsection{A Tail Bound to Boost Existence to Abundance} 

The above theorem showed the existence of a choice of kernel vectors $v_1,\dots, v_k$ that minimized the potential function, thereby implying the existence of a load-balancing linear map. We would like to show most choices of $v_{\le k}$ will minimize the potential. To do so, we will prove a technical lemma that converts the conditional expectation upper bound guarantees from \Cref{clm:expsquare} into tail bounds on the final potential. In particular, while the last section showed the existence of $v_{\le k}$ such that $\Phi_k\le \Phi_0^{2^k}$, the following lemma shows that most choices of $v_{\le k}$ will have $\Phi_k\le (\Phi_0^{2^k})^{O(1)}$. 


\begin{lemma}
\label{lem:potential-tail-bound}
     Let $X_0\ge 1$ be a constant, and let $X_1,\dots, X_k\ge 1$ be random variables satisfying $\E[X_{i+1}|X_{\le i}] \le X_i^2$. For any $t > 1$,  \[\Pr[X_k\ge t^{2^{k-1}}]\le \frac{X_0^2 -1}{t-1}.\]
\end{lemma}

\begin{remark}
\label{rem:initial-tail-tightness}
    \Cref{lem:potential-tail-bound} is tight for the sequence \begin{itemize}\item $X_1  = \begin{cases} t & \text{with probability }\frac{X_0^2-1}{t-1} \\ 1 & \text{otherwise} \end{cases}$,
    \item For $i > 1$, $X_{i+1} = X_i^2.$ \end{itemize} 
\end{remark}


\begin{proof}[Proof of \Cref{lem:potential-tail-bound}]
We proceed by induction on $k$. For $k=1$, it follows by Markov's inequality and the fact $X_1-1$ is a nonnegative random variable that \[\Pr[X_1\ge t] = \Pr[X_1 - 1 \ge t - 1]\le \frac{X_0^2-1}{t-1}.\] Now assume we have the lemma for $k$ and wish to prove it for $k+1$. We can bound \begin{align*}\Pr[X_{k+1}\ge t^{2^k}]  & = \E_{X_1}\left[\Pr\left[X_{k+1}\ge (t^2)^{2^{k-1}}\right]|X_1\right] \le \E_{X_1}\left[\min\left(1,\frac{X_1^2-1}{t^2-1}\right)\right],
\end{align*}
where the inequality follows from the inductive hypothesis and the fact that all probabilities are at most 1. To bound the above expression, we will first upper bound the argument of $\E_{X_1}[\cdot ]$ in the domain $X_1\ge 1$ by a linear function.

\begin{claim}
\label{clm:upperapprox}
    Let $x\ge 1$ and $t> 1$. We have \[\min\left(1,\frac{x^2-1}{t^2-1}\right)\le \frac{x-1}{t-1}.\]
\end{claim}

\begin{proof}
    If $1 \le x \le t$, then $\frac{x^2-1}{t^2-1}\le 1$, $\frac{x+1}{t+1}\le 1$, and $\frac{x-1}{t-1}\ge 0$. Hence \[\min\left(1,\frac{x^2-1}{t^2-1}\right) = \frac{x^2-1}{t^2-1} = \left(\frac{x-1}{t-1}\right)\left(\frac{x+1}{t+1}\right) \le \frac{x-1}{t-1}.\] If $x > t$, we have $\frac{x-1}{t-1} > 1\ge \min\left(1,\frac{x^2-1}{t^2-1}\right)$.
\end{proof}

With this linear upper bound, we can use the bound on $\E[X_1]$ and linearity of expectation to finish the inductive step as follows.

\begin{align*}\Pr[X_{k+1}\ge t^{2^k}] \le \E_{X_1}\left[\min\left(1,\frac{X_1^2-1}{t^2-1}\right)\right]\le \E_{X_1}\left[\frac{X_1-1}{t-1}\right] \le \frac{X_0^2-1}{t-1}. \end{align*} The desired result follows.
\end{proof}


\subsection{Using the Tail Bound to Analyze Potentials}
With \Cref{lem:potential-tail-bound} in hand, we can now revisit the proof strategy of \Cref{thm:hashingexistence}, and use the tail bound to argue the potentials are minimized with high probability.

\begin{theorem}
\label{thm:hashingwhp}
    Let $\ell\ge 1, u\ge \ell + \log\ell$ be integers, and $n\coloneqq 2^\ell$. Let $S\subset\F_2^{u}$ be of cardinality $n$, and let $\cH$ be the set of all surjective linear maps $h: \F_2^{u}\to\F_2^\ell$.  For any $r\ge 1$,\[\Pr_{h\sim \cH}\left[M(S,h) \ge r\cdot \frac{\log n}{\log\log n}\right] \le \frac{3\log e}{2(r-1)}.\]
\end{theorem}

In the next section, we will establish a stronger tail bound that decays quadratically (\Cref{lem:quad-tail-surj}). \Cref{thm:hashingwhp} suffices for a high constant probability guarantee.

\begin{proof}
Let $k\coloneqq u-\ell$. To pick $h\sim \cH$, we will pick linearly independent vectors $v_1,\dots v_k\in \F_2^u$ uniformly at random, and then pick a uniformly random $h$ with kernel $V\coloneqq \Span(v_{\le k})$.  In particular, for $i=1,\dots, k$ we will iteratively pick $v_{i}\sim \F_2^u\setminus V_{i-1}$. Using $S$ and $v_{\le k}$, define the functions $\{S_i(x)\coloneqq |(x+V_i)\cap S|\}_{0\le i\le k}$, and the potentials $\{\Phi_i(x)\coloneqq \E_{x\sim \F_2^u}[\ell^{S_i(x)}]\}_{i\in[k]}$.
If some preimage of $h$ had load $r\ell/\log \ell$, then $|(x+V)\cap S|\ge r\ell/\log \ell$ for some shift $x$. \Cref{clm:potential-load} then implies \[\Phi_k \ge \frac{\ell^{r\ell/\log\ell}}{2^{u-k}}  = \frac{2^{r\ell}}{2^{\ell}} =  n^{r - 1}.\]

We can easily compute\[\Phi_0 = \E_x[\ell^{S(x)}] = 1 - \frac{n}{2^u} + \frac{n\ell}{2^{u}} < 1 + \frac{\ell}{2^{k}}.\] Consequently, $\Phi_0^2 \le 1 + 2\ell/2^{k} + (\ell/2^k)^2\le 1 + 3\ell/2^k$, where we used the assumption $ { u\ge \ell+\log \ell} \iff \ell/2^k\le 1$. We already know by \Cref{clm:expsquare} that $\E[\Phi_{i+1} | \Phi_{\le i}] \le \Phi_i^2$. Hence, by \Cref{lem:potential-tail-bound} (where all $\Phi_i\ge 1$ since $\ell \ge 1$), we have \begin{align*}\Pr\left[M(S,h)\ge \frac{r\ell}{\log \ell}\right] \le \Pr[\Phi_k \ge n^{r-1}]  &  \le \frac{\Phi_0^2 - 1}{n^{(r-1)/2^{k-1}} - 1} \\ &   \le \frac{3\ell/2^{k}}{(r-1)(\ln n)/2^{k-1}}\tag{$e^x-1\ge x$}  \\ &   = \frac{3\log e}{2(r-1)}.\end{align*}


\end{proof}

\section{Optimal Average Max-Load}
\label{sec:expectation}

In this section, we refine the techniques from \Cref{sec:whp} to prove tail bounds strong enough to establish our main result: optimal expected max-load. The tail bound in \Cref{thm:hashingwhp} decays too slowly to imply this expectation bound. At first glance, strengthening the tail bound appears difficult, as the technical lemma underpinning it, \Cref{lem:potential-tail-bound}, is tight by \Cref{rem:initial-tail-tightness}. Crucially, our potential functions satisfy a \emph{strong} monotonicity property that \Cref{lem:potential-tail-bound} does not exploit: $X_{i+1}-1 \ge 2(X_i - 1)$ for all $i \ge 1$ (\Cref{prop:strides}). 
%For instance, they form an increasing sequence, i.e., $X_{i+1} \ge X_i$. However, this alone is insufficient, because one can construct sequences satisfying $X_{i+1} \ge X_i$ that match the original tail bound asymptotically.
Under this assumption, we can prove a quadratically stronger version of \Cref{lem:potential-tail-bound} (see \Cref{lem:parsed-strong-tail}). 

Interestingly, the conditions required for quadratically decaying appear to be quite delicate for two reasons. \begin{itemize}
 \item A stronger version of \Cref{lem:potential-tail-bound} is not possible under the weaker and more standard monotonicity property $X_{i+1}\ge X_i$. There exists a random sequence $(X_i)$ with $\E[X_{i+1}|X_{\le i}]\le X_i^2$ and $X_{i+1}\ge X_i$ that asymptotically saturates the bound of \Cref{lem:potential-tail-bound}. 
    \item The tight example from \Cref{rem:initial-tail-tightness} satisfies $X_{i+1}-1 \ge 2(X_i - 1)$ for all $i \ge 1$, but not for $i = 0$---showing that even a single exceptional timestep can eliminate any asymptotic improvement on the tails.

\end{itemize}  


\subsection{A Stronger Tail Bound}
The main result we will show is the following.

\begin{theorem}
\label{lem:parsed-strong-tail}
    Let $X_0 > 1$ be a constant, and let $X_1,\dots, X_k$ be random variables satisfying $X_{i+1}-1\ge 2(X_i-1)$ and $\E[X_{i+1}|X_{\le i}]\le X_i^2$ for all $i$. For $ 1 + 4(X_0-1)\le t\le 2$, we have \[\Pr[X_k\ge t^{2^{k-1}}]\le 48\left(\frac{X_0-1}{t-1}\right)^2.\]
\end{theorem}

We would like to prove the above statement using induction, similar to the proof of \Cref{lem:potential-tail-bound}. However, to make the induction go through, we need to strengthen our inductive hypothesis. For each $i\ge 0$, define the functions
%\[\beta_i(t,\delta) = \frac{4^i\delta^2}{t^{2^i}-1-2^{i+1}\delta}.\] 
\[\beta_i(t,\delta) = \frac{t^{2^i} - (1+2^i\delta)^2}{t^{2^i}-(1+2^{i+1}\delta)} .\] The following stronger claim will be easier to prove via induction.


\begin{lemma}
\label{claim:op-tail-lemma}
    Let $\delta >0$ and $X_0 > 1$ be constants, and let $X_1,\dots, X_k$ be random variables such that $\forall i\ge 0$, $X_i\ge 1 +2^i\delta$, and $\E[X_{i+1}|X_{\le i}]\le X_i^2$. For any $t > 1+2\delta$,  \[\Pr[X_k\ge t^{2^{k-1}}]\le 1-\frac{t-X_0^2}{t-1-2\delta}\prod_{i=1}^{k-1}\beta_i(t,\delta).\]

   % Let $X_0\ge Y_0>1$ be constants, and let $Y_1,\dots, Y_k>1$ be random variables such that $\forall i$, $Y_{i+1}\ge 1 + 2^i(X_i-1)$ almost surely and $\E[Y_{i+1}|Y_{\le i}]\le Y_i^2$. $Y_0^2\ge 2X_0-1$. Define \[\beta_i(t,x) =  \frac{2^{2i}(x-1)^2}{(t^{2^i} - 1) - 2^{i+1}(x -1)} \] Then  \[\Pr[Y_k\ge t^{2^{k-1}}]\le 1-\frac{t-Y_0^2}{t-2X_0+1}\prod_{i=1}^{k-1}(1-\beta_i(t,X_0))\]
\end{lemma}
\begin{remark}
    \Cref{claim:op-tail-lemma} is tight for the sequence \begin{itemize}
        \item $X_0 = 1+\delta$, and $X_1 = \begin{cases}1+2\delta & \text{with probability }\frac{t-X_0^2}{t-1-2\delta}\\ t & \text{otherwise}\end{cases}$,
        \item for $i\ge 1$,
        \begin{itemize}
            \item if $X_i = t^{2^{i-1}}$, set $X_{i+1} = t^{2^i}$
            \item if $X_i = 1 + 2^i\delta$, set $X_{i+1} =\begin{cases} 1+2^{i+1}\delta & \text{with probability }\beta_i(t,\delta) \\ t^{2^i} & \text{otherwise}\end{cases}$.
        \end{itemize}
    \end{itemize}
\end{remark}

\begin{remark}
    Setting $\delta = 0$ recovers \Cref{lem:potential-tail-bound}.
\end{remark}

%\begin{remark}
 %   The motivation behind the $\beta_i$ functions is that $\beta_1(\delta, t)$ will relate to the slope of the best linear function upper bound, akin to \Cref{clm:upperapprox} (see \Cref{claim:mintolingeneral}). In the proof of \Cref{claim:op-tail-lemma}, we will apply the inductive hypothesis with the change of variables  $\delta\gets 2\delta$ and $t\gets t^2$. This motivates defining $\beta_{i+1}(t,\delta) = \beta_{i}(t^2,2\delta) $ (see \Cref{claim:recursebeta}).
%\end{remark}

Before we start the proof, we will establish some preliminary properties of $\beta_i(t,\delta)$.

\begin{claim}
\label{claim:recursebeta}
    $\beta_i(t^2,2\delta) = \beta_{i+1}(t,\delta)$
\end{claim}

\begin{proof}
    \begin{align*}\beta_i(t^2,2\delta) = \frac{(t^2)^{2^i} - (1 + 2^i(2\delta))^2}{(t^2)^{2^i} -(1 + 2^{i+1}(2\delta))}  = \frac{t^{2^{i+1}} - (1+2^{i+1}\delta)^2}{t^{2^{i+1}}-(1+2^{i+2}\delta)} = \beta_{i+1}(t,\delta).\end{align*}
\end{proof}

\begin{claim}
\label{claim:rangebeta}
   For all $i\ge 1$ and $t > 1+2\delta$, $0\le \beta_i(t,\delta)\le 1.$
\end{claim}

\begin{proof}
For the lower bound, note $t^{2^i}\ge 1+2^{i+1}\delta$ for all $i$ (by \Cref{claim:silly}). Consequently, the numerator and denominator of $\beta_i(t,\delta)$ are both positive.
For the upper bound, we see ${1- \beta_i(t,\delta)} = \frac{4^i\delta^2}{t^{2^i}-(1+2^{i+1}\delta)}$. The numerator is trivially nonnegative, and the denominator is positive by \Cref{claim:silly}.    
\end{proof}
%We now show a generalization of \Cref{clm:upperapprox}, which will lower bound an expression we will encounter by a linear function.





With these tools, we are ready to prove \Cref{claim:op-tail-lemma}.


\begin{proof}[Proof of \Cref{claim:op-tail-lemma}]
We apply induction on $k$. For the base case $k=1$, we apply Markov's inequality on the nonnegative random variable $X_1-1-2\delta$ to yield \begin{align*}\Pr[X_1\ge t]  = \Pr[X_1-1-2\delta\ge t-1-2\delta]   \le \frac{X_0^2-1-2\delta}{t-1 - 2\delta}   = 1-\frac{t-X_0^2}{t-1-2\delta}.\end{align*}  Note the implicit use of $t> 1+2\delta$ in the application of Markov's inequality.

Now assume the lemma for $k$. We will now prove it for $k+1$. Write the tail probability as
\begin{align}\Pr[X_{k+1}\ge t^{2^k}] = \E_{X_1}[\Pr[X_{k+1}\ge (t^2)^{2^{k-1}} | X_1]].\label{eqn:induct1}\end{align} For fixed $X_1$, it follows that $X_2,\dots, X_{k+1}$ is a sequence of random variables of length $k$ satisfying $X_{i+1}\ge 1 + 2^i(2\delta)$ and $\E[X_{i+2}|X_1,X_2,\dots, X_{i+1}] \le X_{i+1}^2$ for all $i\in [k]$. Furthermore, $t^2\ge 1+2(2\delta)$ by \Cref{claim:silly}. Hence, all assumptions of the inductive hypothesis are satisfied with the instantiation $\delta\gets 2\delta$, $t\gets t^2$. Utilizing this as well as the fact all probabilities are bounded by 1, we obtain \begin{align} \E_{X_1}[\Pr[X_{k+1}\ge (t^2)^{2^{k-1}} | X_1]]\notag  &\le \E_{X_1}\left[\min \left(1, 1-\frac{t^2-X_1^2}{t^2-1-4\delta}\prod_{i=1}^{k-1}\beta_i(t^2, 2\delta)\right)\right]\notag  \\ & = 1 - \E_{X_1}\left[\max\left(0,\frac{t^2-X_1^2}{t^2-1-4\delta}\prod_{i=2}^k \beta_i(t,\delta)\right)\right] \notag \\ & = 1 - \E_{X_1}\left[\max\left(0, \frac{t^2-X_1^2}{t^2-1-4\delta}\right)\right] \prod_{i=2}^k\beta_i(t,\delta) \label{eqn:induct2}\end{align}
where the last equality used the fact $\prod_{i=2}^k\beta_i(t,\delta)\ge 0$. To bound this expression, we would like to mimic the intuition of \Cref{clm:upperapprox} and bound the argument of $\E_{X_1}[\cdot]$ by a linear function in the domain $X_1\ge 1+2\delta$. The following claim does so. \begin{claim}
\label{claim:mintolingeneral}
    Let $\delta \ge 0$, $x\ge 1+2\delta$, and $t > 1+2\delta$. Then \[\max\left(0,\frac{t^2-x^2}{t^2-1-4\delta}\right)\ge \left(\frac{t-x}{t-1-2\delta}\right)\beta_1(t,\delta). \]
\end{claim}
Assuming this claim is true for now (see \Cref{rem:geointuit} for geometric intuition), we can use the fact $X_1\ge 1+2\delta$, $\beta_i(t,\delta)\ge 0$,  \Cref{claim:mintolingeneral}, and linearity of expectation to bound \begin{align}1 - \E_{X_1} \left[\max\left(0,\frac{t^2-X_1^2}{t^2-1-4\delta}\right)\right] \prod_{i=2}^k\beta_i(t,\delta)\notag  & \le 1 - \E_{X_1}\left[\frac{t-X_1}{t-1-2\delta}\cdot \beta_1(t,\delta)\right]\prod_{i=2}^k \beta_i(t,\delta)\notag \\ & \le 1 - \frac{t-X_0^2}{t-1-2\delta}\prod_{i=1}^k\beta_i(t,\delta).\label{eqn:induct3} \end{align} Combining \eqref{eqn:induct1},\eqref{eqn:induct2}, and \eqref{eqn:induct3} gives us \[\Pr[X_{k+1}\ge t^{2^k}]\le 1 - \frac{t-X_0^2}{t-1-2\delta}\prod_{i=1}^k \beta_i(t,\delta).\] The desired result follows by induction.
\end{proof}

We now prove \Cref{claim:mintolingeneral}. Notice when $\delta = 0$ this is exactly \Cref{clm:upperapprox}.
\begin{proof}[Proof of \Cref{claim:mintolingeneral}]
    If $x  >  t$, then  $\frac{t-x}{t-1-2\delta} < 0$ as $t > 1+2\delta$. Since we know $\beta_i(t,\delta)\ge 0$ by \Cref{claim:rangebeta}, it follows\[\left(\frac{t-x}{t-1-2\delta}\right)\beta_1(t,\delta) < 0 \le \max\left(0, \frac{t^2-x^2}{t^2-1-4\delta}\right).\] If $x \le t$, then  $\frac{t-x}{t-1-2\delta}\ge 0$ and $\frac{t^2-x^2}{t^2-1-4\delta}\ge 0$, since $t > 1+2\delta$ and $t^2 > 1+4\delta$ (by \Cref{claim:silly}). Hence, \begin{align*}\max\left(0, \frac{t^2-x^2}{t^2-1-4\delta}\right)  = \frac{t^2-x^2}{t^2-1-4\delta}   &  = \left(\frac{t-x}{t-1-2\delta}\right)\left(\frac{(t+x)(t-1-2\delta)}{t^2-1-4\delta}\right) \\ &    \ge  \left(\frac{t-x}{t-1-2\delta}\right)\frac{(t+1+2\delta)(t-1-2\delta)}{t^2-1-4\delta}\\ & = \left(\frac{t-x}{t-1-2\delta}\right)\left(\frac{t^2-(1+2\delta)^2}{t^2-1-4\delta}\right) \\ & = \left(\frac{t-x}{t-1-2\delta}\right)\beta_1(t,\delta).\end{align*} 
    %The conclusion now follows, as \begin{align*}\min\left(1,1-\frac{t^2-x^2}{t^2-1-4\delta}\alpha\right) & = 1 - \max(0,\frac{t^2-x^2}{t^2-1-4\delta}\alpha) \\ &  = 1 - \alpha\max(0,\frac{t^2-x^2}{t^2-1-4\delta})\\ & \le 1-\frac{t-x}{t-1-2\delta}(1-\beta_1(t,\delta))\alpha\end{align*}
\end{proof}

