At this point, we have unconditionally proven \Cref{claim:op-tail-lemma}. Using \Cref{claim:op-tail-lemma}, we can now show \Cref{lem:parsed-strong-tail} is true.



\begin{proof}[Proof of \Cref{lem:parsed-strong-tail}]
    Let $\delta \coloneqq X_0-1$. Notice that by composing the assumed inequality, the random variables satisfy $X_i-1\ge 2^i(X_0-1) = 2^i\delta$ for each $i$. Hence, we can apply \Cref{claim:op-tail-lemma} and use the fact $\beta_0(t,\delta) = \frac{t-(1+\delta)^2}{t-1-2\delta} = \frac{t-X_0^2}{t-1-2\delta}$ to yield \begin{align*}\Pr[X_k\ge t^{2^{k-1}}]  \le 1 - \left(\frac{t-X_0^2}{t-1-2\delta}\right)\prod_{i=1}^k\beta_i(t,\delta)  = 1 - \prod_{i=0}^k\beta_i(t,\delta). \end{align*} Since \Cref{claim:rangebeta} tells us $0\le \beta_i(t,\delta) \leq 1$ for all $i$, we can treat these quantities as probabilities. Consider $k+1$ independent and biased coins, where coin $i$ has probability $\beta_i(t,\delta)$ of showing heads. By the union bound on the event that at least one tail shows, we have
    %Using $0\le \beta_i(t,\delta) \leq 1$ for all $i \geq 1$ from \Cref{claim:rangebeta} and the fact $1-\beta_i(t,\delta) = \frac{4^i\delta^2}{t^{2^i}-(1+2^{i+1}\delta)}$, we can further bound 
    \[ 1 - \prod_{i=0}^k\beta_i(t,\delta)   
    %= \sum_{i=0}^k (1-\beta_i(t,\delta))\prod_{j=i+1}^k\beta_i(t,\delta)   
    \le \sum_{i=0}^k(1-\beta_i(t,\delta))   = \sum_{i=0}^k\frac{4^i\delta^2}{t^{2^i}-1 - 2^{i+1}\delta}   \le 2\delta^2\sum_{i=0}^k \frac{4^i}{t^{2^i}-1},\] where we used the fact that for all $i$, $t^{2^i} - 1\ge 2^i(t-1)\ge  2^{i+2}\delta$ by \Cref{claim:silly} and the theorem assumption. For $i\le \log\left(\frac{5}{t-1}\right)$, we have \begin{align*}\sum_{i\le \log\left(\frac{5}{t-1}\right)}\frac{4^i}{t^{2^i}-1}  =\sum_{i\le \log\left(\frac{5}{t-1}\right)}\frac{2^i}{\ln t}\cdot \frac{2^i\ln t}{e^{2^i\ln t}-1}  & \le \frac{1}{\ln t}\sum_{i\le \log\left(\frac{5}{t-1}\right)} 2^i\tag{$\frac{x}{e^x-1}\le 1$} \\ & \le \frac{1}{\ln t}\cdot \frac{10}{t-1}\\ & \le \frac{t}{t-1}\cdot \frac{10}{t-1} \tag{$1+x\ge e^{\frac{x}{1+x}}$}\\ & \le \frac{20}{(t-1)^2},\end{align*} For $i > \log\left(\frac{5}{t-1}\right)$, we can bound  \begin{align*}\sum_{i> \log\left(\frac{5}{t-1}\right)}\frac{4^i}{t^{2^i}-1}  = \sum_{j\ge 1} \frac{4^{\log(5/(t-1))}4^j}{(t^{5/(t-1)})^{2^j} - 1}  & \le \left(\frac{5}{t-1}\right)^2\sum_{j\ge 1}\frac{4^j}{(1 + \frac{5}{t-1}(t-1))^{2^j} - 1} \tag{\Cref{claim:silly}} \\ & \le \left(\frac{5}{t-1}\right)^2\sum_{j\ge 1}(4/35)^j \\ & \le \frac{4}{(t-1)^2}.  \end{align*} Hence we have \begin{align*}\Pr[X_k\ge t^{2^{k-1}}]  \le 2\delta^2\sum_{i=0}^k \frac{4^i}{t^{2^i}-1} \le 2\delta^2\left(\frac{20}{(t-1)^2}+\frac{4}{(t-1)^2}\right)  &  = 48\left(\frac{X_0-1}{t-1}\right)^2 .\end{align*}
\end{proof}

\subsection{Applying the Tail Bound To Our Potentials}

We will strengthen the tail bounds of \Cref{thm:hashingwhp}, and also generalize \Cref{thm:hashingwhp} to the setting of $m$ balls and $n$ bins, for $m\neq n$. For brevity, define \[\opt(m,n) = \begin{cases} \frac{\log n}{\log\left(\frac{n\ln n}{m}\right)} & m\le \frac{1}2 n\log n \\ \frac{m}n & m > \frac{1}2n\log n \end{cases}\] to be the function that outputs the maximum load obtained when a fully random hash maps $m$ balls to $n$ bins.


\begin{theorem}
\label{lem:quad-tail-surj}
Let $u,\ell,m\ge 1$ be integers such that $u\ge \ell + 2\log(\ell m)$, and let $n\coloneqq 2^\ell$. Let $\cH$ be the set of surjective linear maps $\F_2^u\to\F_2^\ell$. Let $S\subset \F_2^u$ be a subset of size $m$. Then for any real $r\ge 6$, \[\Pr_{h\sim \cH}\left[M(S,h)\ge r\cdot \opt(m,n)\right]\le \frac{48}{(r-2)^2}\]
\end{theorem}

\begin{proof}
     % It suffices to show the claim for large enough $u$, say $u\ge \ell + \log \ell + \log m$. To see why this doesn't lose generality, let $\cH'$ be a random uniform surjective linear map $h:\F_2^{u'}\to\F_2^\ell$ for some $u' < u$. Now consider a $u'$-dimensional subspace $V\subset \F_2^u$. There is an isomorphism $\iota: \F_2^{u'}\to V$. For $h\sim \cH$, $h|_V:V\to \F_2^\ell$ will be a random linear surjective map, and for any $T\subset V$, \begin{align*}M(T,h|_V) & = \max_{y\in \F_2^\ell} |(h|_V)^{-1}(y)\cap S| \\ & = \max_{y\in \F_2^\ell} |h^{-1}(y)\cap V \cap T| \\ & = \max_{y\in \F_2^\ell} |h^{-1}(y)\cap T| \\ & =M(T,h). \end{align*} Consequently, for any $M$,  \[\Pr_{h'\sim \cH}[M(S,h')\ge M] = \Pr_{h\sim \cH}[M(\iota(S), h|_V)\ge M]= \Pr_{h\sim \cH}[M(\iota(S), h)\ge M]. \]

    Define $k\coloneqq u-\ell$. We assume $r\le m$, since $M(S,h)\le |S| = m$ for any $h$. We will pick $h\sim\cH$ by iteratively sampling $v_{i+1}\sim \F_2^u\setminus V_i$, and then picking random $h$ with $\ker(h) = V$. Define the associated functions $\{S_i(x)\coloneqq |(x+V_i)\cap S|\}_{0\le i\le k}$. We will split into two cases.

    \noindent \textbf{Case 1: $m\le \frac{1}2 n\log n$}. 

    Set $b=n\ell/m$ and $\Phi_i \coloneqq \E_{x\sim \F_2^u}[b^{S_i(x)}]$ for $0\le i\le k$. Then \[\Phi_0 = \left(1-\frac{m}{2^u}\right)\cdot 1 + \frac{m}{2^u}\cdot b\le 1 + \frac{bm}{2^u}= 1 + \frac{\ell}{2^k}.\] By \Cref{clm:load-potential} and the fact $\opt(m,n) = \ell/\log b$ in this case, we have \begin{align*}\Pr[M(S,h) \ge r \cdot \opt(m,n)]  \le \Pr\left[\Phi_k\ge \frac{b^{r\cdot \opt(m,n)}}{n}\right]  = \Pr[\Phi_k\ge n^{r-1}].\end{align*} Note that for $t = 1 + r\ell/2^k$, $t^{2^{k-1}} \le e^{r\ell/2}  < n^{r-1}$. Furthermore, as $4\le r\le m$ and $u\ge \ell + \log( \ell m)$, we have $t-1\ge 4\ell/2^k\ge  4(\Phi_0-1)$ and $t-1 \le  mn\ell/2^u\le 1$. Finally, we have $\Phi_{i+1}-1\ge 2(\Phi_i-1)$ for all $i$ by \Cref{prop:strides}. Hence, we can use \Cref{lem:parsed-strong-tail} to bound \begin{align*}\Pr[\Phi_k\ge n^{r-1}]  \le \Pr[\Phi_k\ge t^{2^{k-1}}]   \le 48\left(\frac{\Phi_0-1}{t-1}\right)^2  \le 48\left(\frac{\ell/2^k}{r\ell/2^k}\right)^2 =\frac{48}{r^2}.  \end{align*} 

\noindent \textbf{Case 2:  $m > \frac{1}2n\log n$}. 

Define $\Phi_i \coloneqq \E_{x\sim\F_2^u}[2^{S_i(x)}]$ for $0\le i\le k$. Then \[\Phi_0 = 1-\frac{m}{2^u} + \frac{2m}{2^u} = 1 + \frac{m}{2^u}.\] By \Cref{clm:load-potential} and the fact $\opt(m,n) = m/n$ in this regime, \begin{align*}\Pr[M(S,h)\ge r\cdot \opt(m,n)] & = \Pr[M(S,h)\ge rm/n] \\ & \le \Pr[\Phi_k\ge 2^{rm/n-\ell}] \\ &  \le \Pr[\Phi_k\ge 2^{(r-2)m/n}]\tag{$m\ge \frac{1}2n\ell$ }\end{align*} For $t \coloneqq 1 + (r-2)m/2^u$, we have $t^{2^{k-1}}\le e^{(r-2)m/2n}\le 2^{(r-2)m/n}$. Since $6\le r\le m$ and $u\ge \ell + 2\log m$, we can deduce $t-1\ge 4m/2^u \ge 4(\Phi_0-1) $ and $t-1\le m^2/2^u\le 1$. Furthermore, we have $\Phi_{i+1}-1\ge 2(\Phi_i-1)$ for all $i$ by \Cref{prop:strides}. Hence, by \Cref{claim:op-tail-lemma}, we have \begin{align*}\Pr[\Phi_k\ge t^{2^{k-1}}]  \le 48\left(\frac{\Phi_0-1}{t-1}\right)^2   \le 48\left(\frac{m/2^u}{(r-2)m/2^u}\right)^2   = \frac{48}{(r-2)^2}.\end{align*} 

\end{proof}

With a simple argument (whose proof is deferred to \Cref{app:removing-surjectivity}), we can remove the artificial lower-bound condition on $u$ and the surjectivity condition on $h$. 

\begin{theorem}
\label{thm:quadratic-tail-final}
    Let $u\ge \ell\ge 1$ and $m\le 2^u$ be integers.  Let $n\coloneqq 2^\ell$. Let $h:\F_2^u\to\F_2^\ell$ be a random linear map. For any $S\subset \F_2^u$ of size $m$ and $r\ge 6$, we have \[\Pr_{h\sim \cH} [M(S,h)\ge r\cdot \opt(m,n)]\le \frac{49}{(r-2)^2}.\]
\end{theorem}
With these strong tails, optimal expected max-load is a simple corollary.

\begin{theorem}
    Let $u\ge \ell\ge 1$ be integers, and $n\coloneqq 2^\ell$. For uniformly random linear map $h:\F_2^u\to \F_2^\ell$, \[\E_h[M(S,h)]\le 16\cdot \opt(m,n).\]
\end{theorem}

\begin{proof}
    \begin{align*}\E_h[M(S,h)] & = \int_{0}^\infty\Pr[M(S,h)\ge t]dt \\ & \le \int_0^{9\cdot \opt(m,n)} 1dt + \int_{9\cdot \opt(m,n)}^\infty\Pr[M(S,h)\ge t]dt\\ & \le 9\opt(m,n)+ \opt(m,n)\int_{9}^\infty \Pr[M(S,h)\ge r\opt(m,n)]dr  \\ & \le 9\opt(m,n) + 49\opt(m,n)\int_{9}^\infty\frac{1}{(r-2)^2}dr \tag{\Cref{thm:quadratic-tail-final}}\\ & =   16\cdot \opt(m,n). \end{align*}
\end{proof}


\section{Two-Sided Bounds}
\label{sec:two-sided}

%We first confirm that all of the max-load upper bounds from \Cref{thm:hashingwhp} are tight in a very strong manner. We first start with the regime $m = O(n\log n)$. In this setting, most ball sets $S$ will not have a \emph{single} linear map with $M(S,h) \le (1-o(1))\opt(m,n)$.

%\begin{theorem}
%    Let $m,n\in \N$ with $2^u = m^2$. There exists a constant $C$ and a subset $S\subset\F_2^u$ of cardinality at most $m$ such that \emph{every} linear map $h:\F_2^{u}\to\F_2^\ell$ has $M(S,h) > (1-o(1)) \opt(m,n)$.
%\end{theorem}

%The proof uses standard techniques from the classical balls-and-bins problem, so we defer it to the appendix.

In the regime of $m = \Omega(n\log n)$, we can give two-sided bounds on all bins. In particular, we can show for any set of $m$ balls, a random linear map will hash $\Theta(m/n)$ balls to each bin with high probability.

\begin{theorem}
\label{thm:twosided}
    Let $0 <\eps < 1/2$ be a constant. There exists constants $C_1 < 1 < C_2$ depending on $\eps$ such that for $m\ge C_1^{-1} n\log n$ and any $S\subset\F_2^u$ of cardinality $m$, a uniformly random linear map $h:\F_2^u\to \F_2^\ell$ satisfies \[\Pr\left[\forall y\in \F_2^\ell, \frac{C_1 m}n\le |h^{-1}(y)\cap S|\le \frac{C_2 m}n\right] \ge 1-\eps.\] Furthermore, $C_1 = \Omega(\eps^{74})$ and $C_2 = O(\eps^{-1/2})$.
\end{theorem}

We reiterate that the condition $m=\Omega(n\log n)$ is necessary: there exists $S$ of size at least $ 0.69n \log n$ such that \emph{every} linear map has at least one empty bin (\cite{alon99}, Proposition 2.2). Interestingly, this two-sided bound is also proven using potential functions. To prove this, we will require the following tail bound.

\begin{lemma}
\label{lem:square-decay}
    Let $0<\eps < 1$ and $0 \le X_0 < 1$ be fixed, and let $ 1 > X_1\ge X_2\ge \dots  > 0$ be random variables satisfying $X_{i+1}\ge 2X_i - 1$ and $\E[X_{i+1}|X_{\le i}]\le X_i^2$. Then for ${C_\eps = (1-X_0)^{25}(\eps/2)^{50}\log(1/\eps)}$ and any $s$,

    \[\Pr\left[X_s\ge 2^{-C_\eps 2^s}\right]\le \eps.\]

\end{lemma}

We will first prove \Cref{thm:twosided} assuming this tail bound, and then prove the tail bound afterwards. 

\begin{proof}[Proof of \Cref{thm:twosided}]

    We first focus on the lower bound. Set $t = \log(4m/\eps)$ and factor $h = h_1\circ h_2$, where $h_1:\F_2^u\to\F_2^t$ is a uniformly random linear map, and $h_2:\F_2^t\to\F_2^\ell$ is a uniformly random \emph{surjective} linear map. $h_1$ will collide any fixed pair of elements in $S$ with probability $1/2^t$. Hence the expected number of pairwise collisions among $S$ is $\binom{m}2 \frac{1}{2^t}\le \frac{m^2}{2^{t+1}}$. Let $\cE$ denote the event in which there are at least $m/2$ pairs that collide. By Markov's inequality, \[\Pr[\cE] \le \frac{m^2}{2^{t+1}}\cdot \frac{2}{m} = \frac{m}{2^t} = \frac{\eps}4 .\]

    Letting $k\coloneqq t-\ell$, we will sample random linearly independent vectors $v_1,\dots, v_k\in \F_2^t$, and consider $h_2$ with kernel $V\coloneqq \Span(v_{\le k})$. Using the set $h_1(S)$ and vectors $v_{\le k}$, we construct the associated functions $\{S_i(x)\coloneqq |(x+V_i)\cap h_1(S)|\}_{0\le i\le k}$ and potentials $\{\Phi_i \coloneqq \E_{x\sim \F_2^u}[(1/2)^{S_i(x)}]\}_{0\le i\le k}$.

    Conditioning on $\neg\cE$, we have $|h_1(S)|\ge m-m/2 =  m/2$, and so the density of $h_1(S)\subset \F_2^t$ is lower bounded by $\frac{m/2}{4m/\eps} = \eps/8$. Consequently, we have \[\Phi_0 \le  \left(1-\frac{\eps}8\right)\cdot 1 + \frac{\eps}{8}\cdot \frac{1}2 = 1 - \frac{\eps}{16}.\]
   \Cref{clm:expsquare} and \Cref{prop:strides} show that $(\Phi_i)$ satisfy the premise of \Cref{lem:square-decay}. Hence, we can use \Cref{lem:square-decay} and the fact $\ell \le C_1m/n$ to deduce 
    \begin{align*}\Pr[\Phi_k > 2^{-C_1m/n - \ell}]   \le \Pr[\Phi_k > 2^{-2C_1m/n}]   = \Pr[\Phi_k > 2^{- (\eps/2)C_1 2^k}]  \le \eps/4\end{align*} for $C_1 \coloneqq \frac{2}\eps(1-\Phi_0)^{25}(\eps/8)^{50}\log(4/\eps) = \Omega(\eps^{74})$. 
    Now note for all $y\in \F_2^\ell$, we have \[h^{-1}(y) = \bigsqcup_{z\in h_2^{-1}(y)}h_1^{-1}(z).\] Hence, \begin{align*}|h^{-1}(y)\cap S|  = \sum_{z\in h_2^{-1}(y)}|h_1^{-1}(z)\cap S|  \ge \sum_{z\in h_2^{-1}(y)}\mathbf{1}(z\in h_1(S)) = |h_2^{-1}(y)\cap h_1(S)|.  \end{align*}
    Therefore, it follows \begin{align}\Pr\left[\forall y  \in \F_2^\ell, |h^{-1}(y)\cap S| < C_1 \frac{m}n\right]
     & \le \Pr\left[\forall y\in \F_2^\ell,|h_2^{-1}(y)\cap h_1(S)| < C_1\frac{m}n\right] \nonumber\\ & \le \frac{\eps}4 + \Pr\left[\forall y\in \F_2^\ell,|h_2^{-1}(y)\cap h_1(S)| < C_1\frac{m}n \big| \neg \cE\right] \nonumber
    \\ & \le \frac{\eps}4 + \Pr[\Phi_k > 2^{-C_1m/n - \ell} | \neg \cE]\nonumber
    \tag{\Cref{clm:blanketing}}
    \\ & \le \frac{\eps}4 + \frac{\eps}4 = 
    \frac{\eps}2.\label{eqn:upperbound}\end{align}
We already have from \Cref{thm:quadratic-tail-final} that there exists $C_2=7\eps^{-1/2}+2$ such that ${\Pr[M(S,h) > C_2m/n]}\le \eps/2$. Taking a union bound over this and \Cref{eqn:upperbound} gives the desired result.

\end{proof}

\begin{proof}[Proof of \Cref{lem:square-decay}]
The proof will resemble that of Theorem 7 in \cite{alon99}. Call $i$ a \emph{stride} if $X_{i-1} > 1/2$ and $(1-X_i)\ge \frac{5}4(1-X_{i-1})$, or if $X_{i-1} \le 1/2$ and $X_i\le \frac{3}4X_{i-1}$. We will show on any conditioning of $X_{\le i}$, $i+1$ is a stride with probability $\ge 1/3$. We split into two cases.

\begin{itemize}
\item If $X_{i}\le 1/2$, then $\E[X_{i+1}]\le X_{i}^2\le \frac{1}2X_i$. Therefore, by Markov's inequality, $\Pr[X_{i+1} > \frac{3}4X_i] < \frac{X_i/2}{3X_i/4} = 2/3$, so $i+1$ is a stride with probability at least $1/3$.

\item If $X_i > 1/2$, we will instead apply Markov's inequality on $1-2X_i+X_{i+1}$. Note \[\E[1-2X_i + X_{i+1} | X_{\le i}] = 1-2X_i + X_i^2 = (1-X_i)^2.\] Hence, conditioned on $X_{\le i}$, we have \begin{align*}\Pr_{X_{i+1}}\left[1-X_{i+1}< \frac{5}4(1-X_i)\right] & = \Pr_{X_{i+1}}\left [1-2X_i + X_{i+1} > \frac{3}4(1-X_i)]\right]   < \frac{(1-X_i)^2}{3(1-X_i)/4} < \frac{2}3,\end{align*} so $i+1$ is a stride with probability $\ge 1/3$ in this case as well. 

\end{itemize}

Let $j$ be the first integer such that $X_{j+1} < 1/2$, and let $k$ be the first integer such that $X_{k+1} < \eps^2/8$. Let $s_1$ be the number of strides in $[j]$, and let $s_2$ be the number of strides in $\{j+1,\dots, k\}$. We observe that $(1-X_0)(\frac{5}{4})^{s_1}\le \frac{1}2$, and so $s_1\le \log_{5/4}(1/2(1-X_0))$. Similarly, we must have $\frac{1}2\left(\frac{3}4\right)^{s_2}\ge \frac{\eps^2}8$, implying that $s_2\le \log_{4/3}(4/\eps^2)$. Therefore, there must be at most $s_1+s_2 \le \log_{5/4}(4/(1-X_0)\eps^2)$ strides in $[k]$. Define $k^*\coloneqq 8\log_{5/4}(4/(1-X_0)\eps^2)$. Let  $f(X_0, X_1,\dots, X_{k^*})$ evaluate the number of strides in the first $k^*$ steps, and define $Y_i \coloneqq \E[f(X_{\le k^*}) | X_{ < i}]$. Notice $(Y_i)$ is a Doob martingale with $|Y_{i+1}-Y_i|\le 1$ for all $i$. Furthermore, since we showed each index is a stride with probability $\ge 1/3$,  \[Y_0 \ge k^*/3 = (8/3)\log_{5/4}(4/(1-X_0)\eps^2) \ge 16\log(2/\eps)\] Hence, by Azuma's inequality (\Cref{fact:azuma}) and the above string of inequalities, \begin{align*}\Pr[k\ge k^*] &\le \Pr\left[f(X_{\le k^*})  \le  \log_{5/4}\left(\frac{4}{(1-X_0)\eps^2}\right)\right] \\ & \le \Pr\big[Y_{k^*} \le (3/8)Y_0\big] \\ &   \le e^{-\frac{(5Y_0/8)^2}{2k^*}}  \le e^{-\frac{(5/8)^2}6( 16\log (2/\eps))}  \le \eps/2.\end{align*} 
If $s \le k^*$, we have just shown with probability at most $\eps/2$ that $X_s\ge X_{k}\ge \eps^2/8\ge 2^{-C_\eps 2^s}$ for any $C_\eps\le \log(8/\eps^2)$. Henceforth, we will assume $s > k^*$. Conditioned on $k < k^*$, we have $X_{k^*} < \eps^2/8$. Let $\cE_i$ be the event $X_{k^*+i}< \eps^{2^{i} + 1}/2^{i+3}$ and denote $\cE_{\le t} = \bigwedge_{i=1}^t\cE_i$. Notice that $\E[X_{k^*+i+1}|\cE_{\le i}]\le \eps^{2^{i+1}+2}/2^{2i+6}$, so by Markov's inequality, \[\Pr[\neg \cE_{i+1}| \cE_{\le i}]\le \frac{\eps^{2^{i+1}+2}/2^{2i+6}}{\eps^{2^{i+1}+1}/2^{i+4}} \le \eps/2^{i+2}.\]  Hence for any $t$ we have \[\Pr\left[\neg\cE_{\le t}\right] = \sum_{i=0}^t \Pr\left[\neg \cE_{i+1}\wedge \cE_{\le i}\right]\le \sum_{i=0}^{t} \Pr[\neg\cE_{i+1}|\cE_{\le i}]\le \sum_{i\ge 0}\eps/2^{i+2}\le \eps/2.\] 

Consequently by a union bound, $k < k^*$ and $\cE_{\le (s-k^*)}$ occurs with probability at least $1-\eps$. In the event this happens, and noting $k^*=8\log_{5/4}(4/(1-X_0)\eps^2)\le 25\log(4/(1-X_0)\eps^2)$, it follows \[X_s \le  \frac{\eps^{2^{s-k^*}+1}}{2^{s-k^*+3}}\le \eps^{2^s((1-X_0)\eps^2/4)^{25} + 1} \le 2^{-C_\eps 2^s}\] for $C_\eps = (1-X_0)^{25}(\eps/2)^{50}\log(1/\eps)$. The desired result follows. 

\end{proof}

