\subsection{Proof of \Cref{thm:quadratic-tail-final}: Removing the Surjectivity Assumption}
\label{app:removing-surjectivity}
%We show that with only a mild loss in parameters, we can use our max-load theorem on random surjective linear maps with large enough universe size (\Cref{lem:quad-tail-surj}) to prove max-load bounds on random linear maps with any universe size (\Cref{thm:quadratic-tail-final}). The intuition is that with extremely high probability, a random linear map is surjective, and that a smaller universe only makes hashing easier.

\begin{proof}[Proof of \Cref{thm:quadratic-tail-final}]
 We will first show the result for $u$ large enough, i.e. $2^{u-\ell}\ge \max\{(m-2)^2,(m\ell)^2\}$. At the end, we will remove this assumption on $u$. Let $\cH$ be the set of linear maps $\F_2^u\to\F_2^\ell$, and let $\cK$ be the distribution of the nullity of $h\sim\cH$. If $k$ is the nullity of $h$, then the number of universe elements $v\in \F_2^u$ such that $h(v) = 0$ is $2^k$. For $h\sim \cH$ we have $\Pr[h(v) = 0] = 2^{-\ell}$ for fixed $v\neq 0$. Hence, we can compute by linearity that \begin{align*}\E_{k\sim K}[2^k]  = \E_{h\sim \cH}\left[\sum_{v\in \F_2^u}\mathbf{1}\{h(v) = 0\}\right]    = \sum_{v\in \F_2^u} \Pr_{h}[h(v) = 0]   = 1 + 2^{-\ell}(2^u-1)   \le  2^{u-\ell} + 1.   \end{align*}
Let $\cE$ be the event that $h$ is surjective, i.e. $k = u-\ell$. By Markov's inequality on the random variable $2^k - 2^{u-\ell}$ (as $k\ge u-\ell$), we have \[ \Pr\left[\neg \cE\right]  = \Pr_{k\sim \cK}[k\ge u-\ell + 1] = \Pr_{k\sim \cK}\left[2^k - 2^{u-\ell} \ge 2^{u-\ell}\right] \le \frac{1}{2^{u-\ell}}\le \frac{1}{(m-2)^2} \le \frac{1}{(r-2)^2}.\]

 For brevity, set $M\coloneqq r\cdot \opt(m,n)$. We can use \Cref{lem:quad-tail-surj}, the above observation, and the fact $u\ge \ell + 2\log(\ell m)$ to deduce
 \begin{align*}
    \Pr_{h\sim \cH}\left[M(S,h) \ge M\right]    \le \Pr[\neg \cE] + \Pr_{h\sim \cH}\left[M(S,h) \ge M| \cE\right]  \le  \frac{1}{(r-2)^2} + \frac{48}{(r-2)^2}    =\frac{49}{(r-2)^2}.
 \end{align*}

 We will now remove the lower bound assumption on $u$. Intuitively, for any $\ell\le u' < u$ we can simply embed $\F_2^{u'}$ into $\F_2^u$, and then port in the max-load result for $\F_2^u$.

 More formally, let $\cH'$ be the set of linear maps $\F_2^{u'}\to\F_2^\ell$. Take an arbitrary $u'$-dimensional subspace $V\leq \F_2^u$. There is an isomorphism $\iota: \F_2^{u'}\to V$. Denote $T\coloneqq \iota(S)$. Since $T\subset V$, we have for any $h:\F_2^u\to\F_2^\ell$ that \begin{align*}M(T,h|_V)  = \max_{y\in \F_2^\ell} |(h|_V)^{-1}(y)\cap T|  = \max_{y\in \F_2^\ell} |h^{-1}(y)\cap V \cap T|  = \max_{y\in \F_2^\ell} |h^{-1}(y)\cap T| =M(T,h). \end{align*} For $h\sim \cH$, $h|_V:V\to \F_2^\ell$ will be a uniform random linear map. Consequently, \begin{align*}\Pr_{h'\sim \cH'}[M(S,h')\ge M] = \Pr_{h\sim \cH}[M(T, h|_V)\ge M] = \Pr_{h\sim \cH}[M(T, h)\ge M]  \le \frac{49}{(r-2)^2} \end{align*} since $T$ has cardinality $m$.
\end{proof}


