\subsubsection{Complexity analysis of Problem \eqref{eq:P2}} 
The problem \eqref{eq:P2} can be decomposed into two subproblems: 1) the UAV trajectory optimization using the CVX toolbox; 2) BF vector optimization. The computational complexity of the BF design subproblem aligns with that of Problem \eqref{eq:P1}. In contrast, the UAV trajectory optimization subproblem is formulated as a convex optimization one and solved via CVX empowered by interior-point method. The complexity of this subproblem is quantified as $O(N^{3}_{\text{var}}\log(\epsilon^{-1})$, where $N_{\text{var}}$ denotes the number of variables, and $\epsilon$ denotes the solution accuracy. Consequently, the complete complexity is $\mathcal{O}\left( I_{\rm{iter}} ( N^{3}_{\text{var}}\log(\epsilon^{-1})   +   I_{\max}M_t)  \right)$.


\begin{algorithm}[H] 
	\caption{Proposed AO for Problems \eqref{eq:P1} and \eqref{eq:P2}}  
	\begin{algorithmic}[1]  
		\State  \textbf{Initialization:} the  maximum iteration number $I_{\max}$, initial and terminal position of UAV $q_0$ and $q_t$, the initial positions of MA $\mathbf{ x}_m^{(0)}$ (or the initial trajectory of UAV $\mathbf{q}_{u}^{(0)}$), the BF $\mathbf{ w}^{(0)}$,  $\tau_0 = f_{\mathbf{P1}}(\mathbf{ x}_{m}^{(0)}, \mathbf{ w}^{(0)})$ ($\tau_0 = f_{\mathbf{P2}}( \mathbf{q}_u^{(0)}, \mathbf{ w}^{(0)})$), index of initial iteration $i=0$, cooling factor $\rho$, and initial temperature $T^0$\\
		\textbf{Repeat}\\
		~~~~$k = k + 1$\\
		~~~~Update ${\mathbf{x}_\mathbf{MA}^{(k)}}$ (or ${\mathbf{q}_u^{(k)}}$) with initial point $\left({\mathbf{x}_m^{(k-1)}}, \mathbf{w}^{(k-1)} \right)$ (or $\left({\mathbf{q}_u^{(k-1)}}, \mathbf{w}^{(k-1)} \right)$) with Eq. \eqref{eq:P1-2} (or Eq. \eqref{eq:P2-1'} )\\
		~~~~Updating $\mathbf{w}^{(k)}$ with initial point $\left({{\mathbf{x}_m^{(k)}}_{\rm com}}, \mathbf{w}^{(k-1)}\right)$ with Eq. $\eqref{eq:w}$\\
		~~~~$\tau^{(k)}=f_{\mathbf{P1}}\left({\mathbf{x}_m^{(k)}}, \mathbf{w}^{(k)} \right)$ (or $\tau^{(k)}=f_{\mathbf{P2}}\left({\mathbf{q}_u^{(k)}}, \mathbf{w}^{(k)} \right)$).\\
		~~~~Calculating $p$ with Eq. (\ref{eq:p})\\

		~~~~\textbf{if} $p <  \mathbf{random}(0,1)$  \\        ~~~~~~~~$\tau^{(k)}=\tau^{(k-1)}$, $\mathbf{w}^{(k)}=\mathbf{w}^{(k-1)}$, $\mathbf{ x}_m^{(k)}= \mathbf{ x}_m^{(k-1)}$\\
		~~~~\textbf{end if} \\
		~~~~$T^{(k+1)}=\rho T^{(k)}$\\
		\textbf{Until} the maximum iteration number $I_{\max}$ is reached
	\end{algorithmic}
	\label{AO1}
\end{algorithm}

\emph{Findings:} Although both Problem \eqref{eq:P1} and Problem \eqref{eq:P2} follow a similar alternating optimization structure, the latter has higher computational complexity compared to the former due to the complexity of the trajectory optimization. In Problem \eqref{eq:P1},  the antenna positions are updated independently using a simple first-order method. By contrast, Problem \eqref{eq:P2} involves joint optimization of UAV's trajectory over multiple time slots using an interior-point method featured by second-order, resulting in higher computational complexity. Consequently, the overall complexity of Problem \eqref{eq:P2} increases substantially, especially when the number of time slots is large.



