\title{New Approximation Guarantees for \\
The Inventory Staggering Problem}
\author{%
Noga Alon\thanks{Department of Mathematics, Princeton University, Princeton, NJ, 08544. Email: {\tt nalon@math.princeton.edu}. 
Research supported in part by NSF grant DMS-2154082.}%
\and%
