    \centering
        \includegraphics[width=\columnwidth]{figures/1s_peak.png}
    \caption{Live coincidence histogram (1-second time frame) between Alice and Bob}
    \label{fig:1s_peak}
\end{figure}
\begin{figure}[ht]
    \centering
        \includegraphics[width=\columnwidth]{figures/accumulative_peak.png}
    \caption{Accumulated coincidence histogram over multiple intervals.}
    \label{fig:accumulative_peak}
\end{figure}

\begin{figure}[ht]
