\title{Threshold Signatures for Central Bank Digital Currencies}
%
\author{
  Mostafa Abdelrahman\inst{1,2}\and
  Filip Rezabek\inst{1}\and
  Lars Hupel\inst{1,2}\orcidID{0000-0002-8442-856X}\and
