%$i=1,2$,
\begin{align}
	\label{equation:geometric-interpolation-Gaussian-finite}
	(p_0p_1)^G_{\alpha}(x) = \Ncal(\mu_{\alpha}, C_{\alpha})(x),
	%	\\
	%\end{align}
	\text{ where }
	%\begin{align}
	C_{\alpha} &= [(1-\alpha)C_0^{-1} + \alpha C_1^{-1}]^{-1},
