%{\bf $M$-Jensen-Shannon divergence}
With the weighted $M$-mixture of $P$ and $Q$, the following is the generalization of the Jensen-Shannon divergence
in Eq.\eqref{equation:Jensen-Shannon-original}.
%\begin{definition}
%[\textbf{$M$-Jensen-Shannon divergence}]

\textbf{$M$-Jensen-Shannon divergence}.
%	\label{definition:M-Jensen-Shannon-divergence}
Let $M$ be a given abstract mean. 
%Let $\alpha \in [0,1]$. 
Let $P,Q \in \Pcal(\Xcal,\mu)$. The $M$-Jensen-Shannon divergence between 
$P$ and $Q$ is defined to be
\begin{align}
	\JS_{M_\alpha}(P||Q) = (1-\alpha)\KL(P||(PQ)^M_{\alpha}) + \alpha \KL(Q||(PQ)^M_{\alpha}), \;\; 0 \leq \alpha \leq 1.
\end{align}
%\end{definition}
For $M_{1/2} = A_{1/2}$, we recover the original Jensen-Shannon divergence in Eq.\eqref{equation:Jensen-Shannon-original}.

{\bf Geometric Jensen-Shannon divergence between Gaussian measures on $\R^n$}.
The {\it arithmetic mean} of two Gaussian measures $P,Q$ is not a Gaussian measure and,
as of the current writing, no closed-form formula is known for 
%the Jensen-Shannon divergence 
$\JS(P||Q) = \JS_{A_{1/2}}(P||Q)$ (however, $\JS(P||Q)$ admits a closed form formula if $P,Q$ are Cauchy distributions \cite{nielsen2021FDivergengeCauchy}).
%between two Gaussian measures. 
On the other hand, 
%as shown in 
by Eq.\eqref{equation:geometric-interpolation-Gaussian-finite},
the {\it geometric mean} of two Gaussian densities is another closed form Gaussian density. Consequently, we
have the following explicit expression for the geometric Jensen-Shannon divergence between two Gaussian measures.
Let $\mu_i = \Ncal(m_i, C_i)$, $i=0,1$, with $C_i \in \Sym^{++}(n)$. 
For $M_{\alpha} = G_{\alpha}$, $\alpha \in [0,1]$, we have \cite[Corollary 1]{nielsen2019geometricJensenShannon}
\begin{align}
	\label{equation:geometric-Jensen-Shannon-Gaussian-finite}
	&\JS_{G_{\alpha}}(\mu_0||\mu_1) = 
	\frac{(1-\alpha)}{2}||C_{\alpha}^{-1/2}(m_0- m_{\alpha})||^2 
	+\frac{\alpha}{2}||C_{\alpha}^{-1/2}(m_1- m_{\alpha})||^2
	\nonumber
	\\
	&\quad -\frac{1}{2}\log\frac{\det(C_0)^{1-\alpha}\det(C_1)^{\alpha}}{\det(C_{\alpha})} 
	%\nonumber
	%\\
	%& \quad 
	+ \frac{1}{2}\trace[C_{\alpha}^{-1}((1-\alpha)C_0 + \alpha C_1) - I].
\end{align}

