				&a(\la x,Ax\ra - 2 \la Am_1, x\ra + \la m_1,Am_1\ra) + b(\la x, Bx\ra  - 2 \la Bm_2, x\ra + \la m_2, Bm_2\ra)
				\\
				&= \la x, Cx\ra - 2\la Cm, x\ra + \la m, Cm\ra + D.
			\end{align*}
			First, comparing the quadratic terms of $x$ on both sides, we get  $C = a A + b B$.
			Next, comparing the linear terms of $x$ on both sides gives
			\begin{align*}
				Cm = aAm_1 + b Bm_2.
			\end{align*}
			Since $A, B \in \Sym^{++}(n)$ and $a^2 + b^2 > 0$,  $C$ is invertible, so that
			\begin{align*}
				m = C^{-1}(aAm_1 + b Bm_2)  = (aA + bB)^{-1}(aAm_1 + bBm_2).
			\end{align*}
			It follows then that
			\begin{align*}
				D &= a\la m_1, Am_1\ra + b \la m_2, Bm_2\ra - \la m,Cm\ra 
				\\
				&= a\la m_1, Am_1\ra + b \la m_2, Bm_2\ra 
				\\
				&\quad- \la (aA + bB)^{-1}(aAm_1 + bBm_2), (aAm_1 + b Bm_2)\ra.
			\end{align*}
			\qed
