\begin{theorem}
	[\cite{Minh:2020regularizedDiv}]
	\label{theorem:KL-gaussian}
	Let $\mu = \Ncal(m_1, Q)$, $\nu = \Ncal(m_2, R)$, with $\ker(Q) = \ker{R} = \{0\}$, and
	%Assume that 
	$\mu \sim \nu$.
	Let $S \in \Sym(\Hcal) \cap \HS(\Hcal)$, $I-S > 0$, 
	be such that $R = Q^{1/2}(I-S)Q^{1/2}$, then
	\begin{align}
		\label{equation:KL-gaussian}
		\KL(\nu ||\mu) = \frac{1}{2}||Q^{-1/2}(m_2-m_1)||^2 -\frac{1}{2}\log\dettwo(I-S).
