	{\bf Regularized geometric Jensen-Shannon divergence}.
	%Motivated by the regularized $\KL$ divergence defined Eq.\eqref{equation:regularized-KL-infinite} and the limiting behavior in Eq.\eqref{equation:limit-regularized-KL}, 
	With the infinite-dimensional Log-Det divergence,
	we now formulate the regularized geometric Jensen-Shannon divergence between any pair of Gaussian measures in $\Gauss(\Hcal)$. Let
	$\mu_i = \Ncal(m_i, C_i) \in \Gauss(\Hcal)$, $i=0,1$. Let $\gamma>0, \gamma \in \R$ be fixed. Define the following regularized terms
	\begin{align}
		\label{equation:C-alpha-gamma}
		C_{\alpha, \gamma} &= [(1-\alpha)(C_0 + \gamma I)^{-1} + \alpha (C_1 + \gamma I)^{-1}]^{-1}, \; 0 \leq \alpha \leq 1,
		\\
		m_{\alpha,\gamma} &= C_{\alpha,\gamma}[(1-\alpha)(C_0+\gamma I)^{-1}m_0 + \alpha (C_1+\gamma I)^{-1}m_1].
		\label{equation:m-alpha-gamma}
	\end{align}
	The following shows that $C_{\alpha,\gamma}$ has the form $C_{\alpha,\gamma} = \gamma I +A \in \PC_1(\Hcal)$, for $A \in \Sym(\Hcal) \cap \Tr(\Hcal)$.
	\begin{lemma}
		\label{lemma:C-alpha-gamma-form}
		Let $\gamma \in \R, \gamma > 0$ be fixed. Let $C_{\alpha,\gamma}$ be as defined in Eq.\eqref{equation:C-alpha-gamma}. Then 
		$C_{\alpha,\gamma} = \gamma I + A \in \PC_1(\Hcal)$, where
		$A = \gamma (I-B)^{-1/2}B(I-B)^{-1/2}\in \Sym(\Hcal) \cap \Tr(\Hcal)$, $B = (1-\alpha)C_0(C_0+\gamma I)^{-1} + \alpha C_1(C_1+\gamma I)^{-1}\in \Sym(\Hcal) \cap \Tr(\Hcal)$.
		% $A = [(1-\alpha)C_0(C_0+\gamma I)^{-1} +\alpha C_1(C_1+\gamma I)^{-1}][(1-\alpha)(C_0 + \gamma I)^{-1} + \alpha (C_1 + \gamma I)^{-1}]^{-1}\in \Sym(\Hcal) \cap \Tr(\Hcal)$.
	\end{lemma}
	With $C_{\alpha,\gamma} \in \PC_1(\Hcal)$, the quantity $d^1_{\logdet}[(C+\mu I), C_{\alpha,\gamma}]$ is then well-defined
	$\forall (C+\mu I) \in \PC_1(\Hcal)$, so that the following definition is well-justified.
	\begin{definition}
		[\textbf{Regularized geometric Jensen-Shannon divergence between Gaussian measures on Hilbert space}]
		\label{definition:regularized-geometric-JS-Gaussian-Hilbert-space}
		Let
		$\mu_i = \Ncal(m_i, C_i) \in \Gauss(\Hcal)$, $i=0,1$. Let $\gamma>0, \gamma \in \R$ be fixed. Let $0 \leq \alpha \leq 1$ be fixed. Let $C_{\alpha,\gamma}$, $m_{\alpha,\gamma}$ be as defined in Eqs.\eqref{equation:C-alpha-gamma},
		\eqref{equation:m-alpha-gamma}, respectively.
		The regularized geometric Jensen-Shannon divergence between $\mu_0$ and $\mu_1$ is defined to be
		\begin{align}
			&\JS_{G_{\alpha}}^{\gamma}(\mu_0||\mu_1) = 
			\frac{1-\alpha}{2}||C_{\alpha, \gamma}^{-1/2}(m_0 - m_{\alpha,\gamma})||^2 + \frac{\alpha}{2}||C_{\alpha, \gamma}^{-1/2}(m_1 - m_{\alpha,\gamma})||^2 
			\nonumber
			\\
			&\quad +\frac{(1-\alpha)}{2}d^1_{\logdet}[(C_0+\gamma I), C_{\alpha,\gamma}]
			%\nonumber
			%\\
			%&\quad 
			+ \frac{\alpha}{2} d^1_{\logdet}[(C_1+\gamma I), C_{\alpha,\gamma}].
		\end{align}
	\end{definition}
	\begin{proposition}
		\label{proposition:property-regularized-JS-divergence}
		Let $\gamma\in \R, \gamma > 0$ be fixed. Let $0 < \alpha < 1$. Then
		\begin{align}
			&\JS_{G_{\alpha}}^{\gamma}(\mu_0||\mu_1) \geq 0 \;\;\forall \mu_0,\mu_1 \in \Gauss(\Hcal),
			\\
			&\JS_{G_{\alpha}}^{\gamma}(\mu_0||\mu_1) = 0 \equivalent \mu_0 = \mu_1 \equivalent m_0 = m_1, C_0 = C_1.
		\end{align}
	\end{proposition}
	The following result shows that
	%, as with the regularized $\KL$ divergence, 
	for two equivalent
	Gaussian measures $\mu_0 \sim \mu_1$ with zero mean,
	%$\Ncal(m_1,C_1) \sim \Ncal(m_2,C_2)$, then 
	we recover the exact geometric $\JS$ divergence as
	% the regularization parameter 
	$\gamma \approach 0^{+}$.
	% that is
	\begin{theorem}
		[\textbf{Limiting behavior of the regularized geometric Jensen-Shannon divergence}]
		\label{theorem:limit-regularized-JS-Gaussian}
		Let
		$\mu_i = \Ncal(0, C_i) \in \Gauss(\Hcal)$, $i=0,1$. Let $0 \leq \alpha \leq 1$ be fixed. Assume that $\mu_0 \sim \mu_1$. Then
		\begin{align}
			\lim_{\gamma \approach 0^{+}}\JS_{G_{\alpha}}^{\gamma}(\mu_0||\mu_1) = \JS_{G_{\alpha}}(\mu_0||\mu_1).
		\end{align}
	\end{theorem}

