\begin{theorem}
	[\cite{Minh:2020regularizedDiv}, Theorem 11 and Corollary 2]
	\label{theorem:radon-nikodym-infinite}
	Let $\mu = \Ncal(m_1, Q)$, $\nu = \Ncal(m_2,R)$, with $m_2 - m_1 \in \range(Q^{1/2})$, $R = Q^{1/2}(I-S)Q^{1/2}$, $S \in \SymHS(\Hcal)_{<I}$.
	The Radon-Nikodym density $\frac{d\nu}{d\mu}$
	%of $\nu$ with respect to $\mu$ 
	is given by
	\begin{align}
		\label{equation:RN-infinite}
		\frac{d\nu}{d\mu}(x) = \exp\left[-\frac{1}{2}\sum_{k=1}^{\infty}\Phi_k(x)\right]\exp\left[-\frac{1}{2}||(I-S)^{-1/2}Q^{-1/2}(m_2 - m_1)||^2\right],
		%\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x-m_1) + \frac{1}{1-\alpha_k}W_{\phi_k}(x-m_1)W_{\phi_k}(m_1 - m_2) + \log(1-\alpha_k)\right]\right\},
	\end{align}
	where for each $k \in \Nbb$
	\begin{align}
		\label{equation:Phik}
		\Phi_k = \frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k} - \frac{2}{1-\alpha_k}\la Q^{-1/2}(m_2-m_1), \phi_k\ra W_{\phi_k}+ \log(1-\alpha_k).
	\end{align}
	The series $\sum_{k=1}^{\infty}\Phi_k$ converges in 
	$\Lcal^2(\Hcal,\mu)$ and
	% the function 
	$s(x) = \exp\left[-\frac{1}{2}\sum_{k=1}^{\infty}\Phi_k(x)\right] \in \Lcal^1(\Hcal, \mu)$.
\end{theorem}
For the case $m_1 = m_2 = 0$, this is Corollary 6.4.11 in \cite{Bogachev:Gaussian}.
In particular, for the case $S \in \Sym(\Hcal) \cap \Tr(\Hcal)$, $I -S > 0$, we have
\begin{align}
	\label{equation:RN-traceclass}
	\frac{d\nu}{d\mu}(x) &= [\det(I-S)]^{-1/2}
	\\
	& \times \exp\left\{-\frac{1}{2}\la Q^{-1/2}(x-m_1), S(I-S)^{-1}Q^{-1/2}(x-m_1)\ra \right\}
	\nonumber
	\\
	&\times \exp(\la Q^{-1/2}(x-m_1), (I-S)^{-1}Q^{-1/2}(m_2 - m_1)\ra)
	\nonumber
	\\
	&\times \exp\left[-\frac{1}{2}||(I-S)^{-1/2}Q^{-1/2}(m_2 - m_1)||^2\right].
	\nonumber
\end{align}
For the case $Q=R \equivalent S=0$, i.e. two measures have the same covariance operator), we have
\begin{align}
\label{equation:RN-same-covariance}
\frac{d\nu}{d\mu}(x) &= \exp(\la Q^{-1/2}(x-m_1), Q^{-1/2}(m_2 - m_1)\ra)
\nonumber
\\
&\quad \times \exp\left[-\frac{1}{2}||Q^{-1/2}(m_2 - m_1)||^2\right].
\end{align}
Let $P_N = \sum_{k=1}^Ne_k \otimes e_k$, $N \in \Nbb$, be the orthogonal projection onto the $N$-dimensional subspace of $\Hcal$ spanned
by $\{e_k\}_{k=1}^N$, where $\{e_k\}_{k=1}^{\infty}$ are the orthonormal eigenvectors of $Q$.
In the above expression,
\begin{align}
	&\la Q^{-1/2}(x-m_1), S(I-S)^{-1}Q^{-1/2}(x-m_1)\ra 
	\nonumber
	\\
	& \doteq \lim_{N \approach \infty} \la Q^{-1/2}P_N(x-m_1), S(I-S)^{-1}Q^{-1/2}P_N(x-m_1)\ra 
	\\
	&
	\la Q^{-1/2}(x-m_1), (I-S)^{-1}Q^{-1/2}(m_2 - m_1)\ra 
	\nonumber
	\\
	&\doteq \lim_{N \approach \infty} \la Q^{-1/2}P_N(x-m_1), (I-S)^{-1}Q^{-1/2}(m_2 - m_1)\ra,
\end{align}
with the limits being in the 
%$\Lcal^1(\Hcal,\mu)$ and 
$\Lcal^2(\Hcal, \mu)$ sense.
