\end{align}
In the case $m_1 = m_2 = 0$,
\begin{align}
	\label{equation:log-Radon-Nikodym-S-HS-zero-mean}
	\log\left\{{\frac{d\nu}{d\mu}(x)}\right\} = -\frac{1}{2}\sum_{k=1}^{\infty}\Phi_k(x) = -\frac{1}{2}\sum_{k=1}^{\infty}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x) + \log(1-\alpha_k)\right].
\end{align}
In particular, for $S \in \SymTr(\Hcal)_{<I}$, with $m_1 = m_2 = 0$,
\begin{align}
	\label{equation:log-Radon-Nikodym-S-trace-class-zero-mean}
