For the proof of Proposition \ref{proposition:inner-logRN-mu-star}, we need the following technical results.

\begin{lemma}
	[\cite{Minh2024:FisherRaoGaussian}, Lemma 22]
	\label{lemma:HS-inner-expansion}
	Let $S,T \in \Sym(\Hcal) \cap \HS(\Hcal)$, with eigenvalues $\{\alpha_k\}_{k \in \Nbb}$, $\{\beta_k\}_{k \in \Nbb}$
	and corresponding orthonormal eigenvectors $\{\phi_k\}_{k \in \Nbb}$, $\{\psi_k\}_{k \in \Nbb}$, respectively.
	Let $A \in \Sym(\Hcal)$.
	Then
	\begin{align}
		%\la A^{1/2}SA^{1/2},A^{1/2}TA^{1/2}\ra_{\HS} = 
		\trace(ASAT) =\trace(SATA) = \sum_{k,j=1}^{\infty}\alpha_k \beta_j \la A\phi_k, \psi_j\ra^2.
	\end{align}
	If, in addition, $A \in \Sym(\Hcal)\cap \HS(\Hcal)$, then $\trace(AS) = \sum_{k=1}^{\infty}\alpha_k\la \phi_k, A\phi_k\ra$.
\end{lemma}

\begin{lemma}
	\label{lemma:inner-UV-expansion}
	Let $S,T \in \Sym(\Hcal)$ be compact, with eigenvalues $\{\alpha_k\}_{k \in \Nbb}$, $\{\beta_k\}_{k \in \Nbb}$
	and corresponding orthonormal eigenvectors $\{\phi_k\}_{k \in \Nbb}$, $\{\psi_k\}_{k \in \Nbb}$, respectively.
	Let $A \in \Sym(\Hcal)$.
	Then $\forall u,v \in \Hcal$,
	\begin{align}
		\la Su, ATv\ra = \sum_{k,j=1}^{\infty}\alpha_k\beta_j \la u,\phi_k\ra\la v, \psi_j\ra \la \phi_k, A\psi_j\ra.
	\end{align}
	%	Let $A \in \Sym(\Hcal)$.
\end{lemma}
\begin{proof} With $\{\phi_k\}_{k \in \Nbb}$, $\{\psi_k\}_{k \in \Nbb}$ being both orthonormal bases in $\Hcal$,
	\begin{align*}
		&\sum_{k,j=1}^{\infty}\alpha_k\beta_j \la u,\phi_k\ra\la v, \psi_j\ra \la \phi_k, A\psi_j\ra = \sum_{k=1}^{\infty}
		\alpha_k \la u,\phi_k\ra\sum_{j=1}^{\infty}\la v, T\psi_j\ra \la A\phi_k, \psi_j\ra
		\\
		&= \sum_{k=1}^{\infty}
		\la u,S\phi_k\ra\la Tv, A\phi_k\ra = \sum_{k=1}^{\infty}
		\la Su,\phi_k\ra\la ATv, \phi_k\ra = \la Su, ATv\ra.
	\end{align*}
	\qed
\end{proof}

\begin{lemma}
	\label{lemma:quadratic-form-expansion}
	Let $S \in \Sym(\Hcal)$ be compact, with eigenvalues $\{\alpha_k\}_{k \in \Nbb}$
	and corresponding orthonormal eigenvectors $\{\phi_k\}_{k \in \Nbb}$. Then $\forall u \in \Hcal$,
	\begin{align}
		\la u, Su\ra = \sum_{k=1}^{\infty}\alpha_k \la u, \phi_k\ra^2.
	\end{align}
\end{lemma}
\begin{proof} With $\{\phi_k\}_{k \in \Nbb}$ being an orthonormal basis in $\Hcal$,
	\begin{align*}
		\sum_{k=1}^{\infty}\alpha_k \la u, \phi_k\ra^2 = \sum_{k=1}^{\infty}\la u, S\phi_k\ra \la u, \phi_k \ra= \sum_{k=1}^{\infty}\la Su, \phi_k\ra \la u, \phi_k\ra = \la u, Su\ra.
	\end{align*}
	\qed
\end{proof}

\begin{lemma}[\cite{Minh2024:FisherRaoGaussian}, Lemma 23]
	\label{lemma:logdet-2-inverse}
	Let $A \in \SymHS(\Hcal)_{< I}$ with eigenvalues $\{\lambda_k\}_{k=1}^{\infty}$. Then
	\begin{align}
		\log\dettwo[(I-A)^{-1}] &= -\sum_{k=1}^{\infty}\left[\frac{\alpha_k}{1-\alpha_k} + \log(1-\alpha_k)\right]
		\\
		&= - [\log\dettwo(I-A) + \trace(A^2(I-A)^{-1})].
	\end{align}
	In particular, for $A \in \SymTr(\Hcal)_{< I}$, $\log\dettwo[(I-A)^{-1}] = -\log\det(I-A) - \trace[A(I-A)^{-1}]$.
\end{lemma}

\begin{lemma}
	[\cite{Minh:2020regularizedDiv}, Lemma 24]
	\label{lemma:integral-a2b-Gaussian-Hilbert}
	Let $\Ncal(m,Q) \in \Gauss(\Hcal)$ be fixed but arbitrary. 
	For any pair $a,b \in \Hcal$,
	\begin{align}
		\int_{\Hcal}\la x-m, a\ra^2\la x-m, b\ra \Ncal(m,Q)(dx) = 0.
	\end{align}
\end{lemma}


\begin{lemma}
	\label{lemma:integral-Wa2Wb-Gaussian-Hilbert}
	Let $\nu = \Ncal(m_{\nu}, C_{\nu}) \in \Gauss(\Hcal, \mu_{*})$, $m_{\nu} \in \Hcal$, $C_{\nu} = C_{*}^{1/2}(I-S_{\nu})C_{*}^{1/2}$,
	$S_{\nu} \in \SymHS(\Hcal)_{< I}$. Then for any $a,b \in \Hcal$,
	\begin{align}
		\int_{\Hcal}W_a^2(x)W_b(x)d\nu(x)& = \la  (I-S_{\nu})a, a\ra\la C_{*}^{-1/2}(m_{\nu}-m_{*}), b\ra 
		\nonumber
		\\
		& \quad+  2\la C_{*}^{-1/2}(m_{\nu} - m_{*}), a\ra\la (I-S_{\nu})a, b\ra 
		\nonumber
		\\
		& \quad + \la C_{*}^{-1/2}(m_{\nu} - m_{*}), a\ra^2\la C_{*}^{-1/2}(m_{\nu}-m_{*}), b\ra.
	\end{align}
\end{lemma}
\begin{proof}
	For $a,b \in \range(C_{*}^{1/2})$, we have
	\begin{align*}
		&J = \int_{\Hcal}W_a^2(x)W_b(x)d\nu(x) 
		\\
		&= \int_{\Hcal}\la x-m_{*}, C_{*}^{-1/2}a\ra^2 \la x-m_{*}, C_{*}^{-1/2}b\ra\Ncal(m_{\nu},C_{\nu})(dx)
		\\
		& = \int_{\Hcal}\la x-m_{\nu} + m_{\nu} - m_{*}, C_{*}^{-1/2}a\ra^2 \la x-m_{\nu} + m_{\nu} - m_{*},C_{*}^{-1/2}b\ra \Ncal(m_{\nu},C_{\nu})(dx)
		\\
		& = \int_{\Hcal}[\la x- m_{\nu}, C_{*}^{-1/2}a\ra^2 + 2 \la x-m_{\nu}, C_{*}^{-1/2}a\ra\la m_{\nu} - m_{*}, C_{*}^{-1/2}a\ra 
		%\\
		%+ \la m_{\nu} - m_{*}, C_{*}^{-1/2}a\ra^2]
		\\
		&+ \la m_{\nu} - m_{*}, C_{*}^{-1/2}a\ra^2][\la x-m_{\nu}, C_{*}^{-1/2}b\ra + \la m_{\nu}-m_{*}, C_{*}^{-1/2}b\ra] \Ncal(m_{\nu},C_{\nu})(dx)
		\\
		& = \int_{\Hcal}\la x- m_{\nu}, C_{*}^{-1/2}a\ra^2\la x-m_{\nu}, C_{*}^{-1/2}b\ra \Ncal(m_{\nu},C_{\nu})(dx)
		\\
		&+ \la m_{\nu}-m_{*}, C_{*}^{-1/2}b\ra\int_{\Hcal}\la x- m_{\nu}, C_{*}^{-1/2}a\ra^2  \Ncal(m_{\nu},C_{\nu})(dx)
		\\
		&+ 2\la m_{\nu} - m_{*}, C_{*}^{-1/2}a\ra\int_{\Hcal}\la x-m_{\nu}, C_{*}^{-1/2}a\ra \la x-m_{\nu}, C_{*}^{-1/2}b\ra\Ncal(m_{\nu},C_{\nu})(dx)
		\\
		&+ 2\la m_{\nu} - m_{*}, C_{*}^{-1/2}a\ra\la m_{\nu}-m_{*}, C_{*}^{-1/2}b\ra\int_{\Hcal} \la x-m_{\nu}, C_{*}^{-1/2}a\ra \Ncal(m_{\nu},C_{\nu})(dx)
		\\
		&+ \la m_{\nu} - m_{*}, C_{*}^{-1/2}a\ra^2\int_{\Hcal}\la x-m_{\nu}, C_{*}^{-1/2}b\ra\Ncal(m_{\nu},C_{\nu})(dx)
		\\
		&+\la m_{\nu} - m_{*}, C_{*}^{-1/2}a\ra^2\la m_{\nu}-m_{*}, C_{*}^{-1/2}b\ra.
	\end{align*}
	With $C_{\nu} = C_{*}^{1/2}(I-S_{\nu})C_{*}^{1/2}$, using Lemma \ref{lemma:integral-a2b-Gaussian-Hilbert}, we obtain
	\begin{align*}
		J &= \la C_{*}^{-1/2}(m_{\nu}-m_{*}), b\ra \la  C_{*}^{1/2}(I-S_{\nu})C_{*}^{1/2}(C_{*}^{-1/2}a), C_{*}^{-1/2}a\ra
		\\
		&\quad + 2\la C_{*}^{-1/2}(m_{\nu} - m_{*}), a\ra \la C_{*}^{1/2}(I-S_{\nu})C_{*}^{1/2}(C_{*}^{-1/2}a), C_{*}^{-1/2}b\ra 
		\\
		&\quad + \la C_{*}^{-1/2}(m_{\nu} - m_{*}), a\ra^2\la C_{*}^{-1/2}(m_{\nu}-m_{*}), b\ra
		\\
		& = \la  (I-S_{\nu})a, a\ra\la C_{*}^{-1/2}(m_{\nu}-m_{*}), b\ra  +  2\la C_{*}^{-1/2}(m_{\nu} - m_{*}), a\ra\la (I-S_{\nu})a, b\ra 
		\\
		& \quad + \la C_{*}^{-1/2}(m_{\nu} - m_{*}), a\ra^2\la C_{*}^{-1/2}(m_{\nu}-m_{*}), b\ra.
	\end{align*}
	Since $\range(C_{*}^{1/2})$ is dense in $\Hcal$,
	the result for the general case $a,b \in \Hcal$ is then obtained via a limiting argument.
	\qed
\end{proof}

\begin{proof}[\textbf{of Proposition \ref{proposition:inner-logRN-mu-star}}]
	Let $\{\alpha_k\}_{k \in \Nbb}$ and $\{\beta_k\}_{k \in \Nbb}$ be the eigenvalues of $S_1$ and $S_2$, with corresponding orthonormal eigenvectors
	$\{\phi_k\}_{k \in \Nbb}$ and $\{\psi_k\}_{k \in \Nbb}$, respectively.
	Consider the white noise mapping $W: \Hcal \mapto \Lcal^2(\Hcal, \mu_{*})$. Let $u_1 = C_{*}^{-1/2}(m_1-m_{*})$,
	$u_2 =  C_{*}^{-1/2}(m_1-m_{*})$. Then
	the Radon-Nikodym densities $\frac{d\mu_1}{d\mu_{*}}$ and $\frac{d\mu_2}{d\mu_{*}}$ are given by
	\begin{align*}
		&\log\left\{{\frac{d\mu_1}{d\mu_{*}}(x)}\right\} = 
		%-\frac{1}{2}||(I-S)^{-1/2}C_{*}^{-1/2}(m_1 - m_{*})||^2
		%\\
		%& \quad 
		-\frac{1}{2}\sum_{k=1}^{\infty}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x)
		 - \frac{2}{1-\alpha_k}\la u_1, \phi_k\ra W_{\phi_k} 
		+\log(1-\alpha_k)\right].
		\\
		&\log\left\{{\frac{d\mu_2}{d\mu_{*}}(x)}\right\} =
		%-\frac{1}{2}||(I-T)^{-1/2}C_{*}^{-1/2}(m_2 - m_{*})||^2
		%\\
		%&\quad 
		-\frac{1}{2}\sum_{k=1}^{\infty}\left[\frac{\beta_k}{1-\beta_k}W^2_{\psi_k}(x) 
		-\frac{2}{1-\beta_k}\la u_2, \psi_k\ra W_{\psi_k}
		+ \log(1-\beta_k)\right].
	\end{align*}
	By Lemma 19 in \cite{Minh:2020regularizedDiv}, with $u_{\nu} = C_{*}^{-1/2}(m_{\nu} - m_{*})$, for any $a,b \in \Hcal$,
	\begin{align*}
		&\int_{\Hcal}W_a(x)d\nu(x) = \la u_{\nu}, a\ra,
		\\
		&\int_{\Hcal}W_a(x)W_b(x)d\nu(x) = \la a, (I-S_{\nu})b\ra + \la u_{\nu}, a\ra \la u_{\nu}, b\ra,
		\\
		&\int_{\Hcal}W^2_{a}(x)d\nu(x) = \la a, (I-S_{\nu})a\ra + \la u_{\nu}, a\ra^2.
		%\la C_{*}^{-1/2}(m_{\nu} - m_{*}), a\ra^2.
	\end{align*}
	By Lemma 22 in \cite{Minh:2020regularizedDiv}, for any pair $a,b \in \Hcal$, with $u_{\nu} = C_{*}^{-1/2}(m_{\nu} - m_{*})$,
	\begin{align*}
		\int_{\Hcal}W^2_a(x)W^2_b(x)d\nu(x) &=\la a, (I-S_{\nu})a\ra \la b, (I-S_{\nu})b\ra + 2 \la a,(I-S_{\nu})b\ra^2
		\\
		& \quad + \la u_{\nu}, b\ra^2 \la a, (I-S_{\nu})a\ra
		%\\
		%& 
		+ 4\la u_{\nu}, a\ra \la u_{\nu}, b\ra\la a, (I-S_{\nu})b\ra
		\\
		& \quad + \la u_{\nu}, a\ra^2 \la b, (I-S_{\nu})b\ra
		%\\
		%& 
		+ \la u_{\nu}, a\ra^2\la u_{\nu}, b\ra^2.
	\end{align*}
	By Lemma \ref{lemma:integral-Wa2Wb-Gaussian-Hilbert}, for any pair $a,b \in \Hcal$, with $u_{\nu} = C_{*}^{-1/2}(m_{\nu} - m_{*})$,
	\begin{align*}
		\int_{\Hcal}W_a^2(x)W_b(x)d\nu(x)& = \la  (I-S_{\nu})a, a\ra\la u_{\nu}, b\ra 
		+  2\la u_{\nu}, a\ra\la (I-S_{\nu})a, b\ra 
		+ \la u_{\nu}, a\ra^2\la u_{\nu}, b\ra.
	\end{align*}
	%Recall that $\int_{\Hcal}W^2_{\phi_k}d\mu_0(x) = ||\phi_k||^2 = 1$, 
	%$\int_{\Hcal}W^2_{\psi_k}d\mu_0(x) = ||\psi_k||^2 = 1$. 
	For each pair $k, j \in \Nbb$, with $u_i = C_{*}^{-1/2}(m_i - m_{*})$, $i=1,2$,
	\begin{align*}
		J_{kj} &= \int_{\Hcal}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x)  - \frac{2}{1-\alpha_k}\la u_1, \phi_k\ra W_{\phi_k}(x) + \log(1-\alpha_k)\right]
		\\
		& \quad \quad \quad \times \left[\frac{\beta_j}{1-\beta_j}W^2_{\psi_j}(x) - \frac{2}{1-\beta_j}\la u_2, \psi_j\ra W_{\psi_j}(x)+ \log(1-\beta_j)\right]d\nu(x)
		\\
		& = J_{kj,1} + J_{kj,2},
	\end{align*}
	where
	\begin{align*}
	J_{kj,1} &= \int_{\Hcal}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x)   + \log(1-\alpha_k)\right]
	%\\
	%& \quad \quad \quad \times 
	\left[\frac{\beta_j}{1-\beta_j}W^2_{\psi_j}(x) + \log(1-\beta_j)\right]d\nu(x),
	\\
	J_{kj,2}&=-\frac{2}{1-\beta_j}\int_{\Hcal}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x)+ \log(1-\alpha_k)\right]\la u_2, \psi_j\ra W_{\psi_j}(x)d\nu(x)
	\\
	&\quad + \frac{4}{(1-\alpha_k)(1-\beta_j)}\int_{\Hcal}\la u_1, \phi_k\ra W_{\phi_k}(x)\la u_2, \psi_j\ra W_{\psi_j}(x)d\nu(x)
	\\
	& \quad - \frac{2}{1-\alpha_k} \int_{\Hcal}\left[\frac{\beta_j}{1-\beta_j}W^2_{\psi_j}(x) + \log(1-\beta_j)\right]\la u_1, \phi_k\ra W_{\phi_k}d\nu(x).
	\end{align*}
	For each fixed pair $N,M \in \Nbb$, define 
	\begin{align*}
		f &= \frac{1}{2}\sum_{k=1}^{\infty}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x) -\frac{2}{1-\alpha_k}\la u_1, \phi_k\ra W_{\phi_k}+ \log(1-\alpha_k)\right],
		\\
		f_N &= \frac{1}{2}\sum_{k=1}^{N}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x) -\frac{2}{1-\alpha_k}\la u_1, \phi_k\ra W_{\phi_k}+ \log(1-\alpha_k)\right],
		\\
		g &= \frac{1}{2}\sum_{k=1}^{\infty}\left[\frac{\beta_k}{1-\beta_k}W^2_{\psi_k}(x) -\frac{2}{1-\beta_k}\la u_2, \psi_k\ra W_{\psi_k}+ \log(1-\beta_k)\right],\;
		\\
		g_M &= \frac{1}{2}\sum_{k=1}^{M}\left[\frac{\beta_k}{1-\beta_k}W^2_{\psi_k}(x) -\frac{2}{1-\beta_k}\la u_2, \psi_k\ra W_{\psi_k}+ \log(1-\beta_k)\right].
	\end{align*}
	By Propositions 8 and 10 in \cite{Minh:2020regularizedDiv}, $f,g \in \Lcal^2(\Hcal,\nu)$, with $\lim\limits_{N \approach \infty}||f_N - f||_{\Lcal^2(\Hcal,\nu)} = 0$, $\lim\limits_{M \approach \infty}||g_M - g||_{\Lcal^2(\Hcal,\nu)} = 0$. By H\"older's inequality,
	$\lim\limits_{N,M \approach \infty}||f_Ng_M - fg||_{\Lcal^1(\Hcal,\nu)} = 0$.
	It follows that
	\begin{align*}
		J& = \left\la \log\left\{{\frac{d\mu_1}{d\mu_{*}}(x)}\right\}, \log\left\{{\frac{d\mu_2}{d\mu_{*}}(x)}\right\}\right\ra_{\Lcal^2(\Hcal,\nu)}
		%\\
		= \int_{\Hcal}f(x)g(x)\nu(dx) 
		\\
		&= \lim_{N, M \approach \infty}\int_{\Hcal}f_N(x)g_M(x)\nu(dx) = \frac{1}{4}\sum_{k,j=1}^{\infty}J_{kj}
		= \frac{1}{4}\sum_{k,j=1}^{\infty}[J_{kj,1} + J_{kj,2}].
	\end{align*}
	Let us now calculate $J_{kj,1}$ and $J_{kj,2}$. For each pair $k,j \in \Nbb$,
	\begin{align*}
		&J_{kj,1} = \int_{\Hcal}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x)   + \log(1-\alpha_k)\right]
		%\\
		%& \quad \quad \quad \times 
		\left[\frac{\beta_j}{1-\beta_j}W^2_{\psi_j}(x) + \log(1-\beta_j)\right]d\nu(x)
		\\
		&= \frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}[\la \phi_k, (I-S_{\nu})\phi_k\ra \la \psi_j, (I-S_{\nu})\psi_j\ra + 2 \la \phi_k,(I-S_{\nu})\psi_j\ra^2] 
		\\
		& \quad + \frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}\la u_{\nu}, \psi_j\ra^2 \la \phi_k, (I-S_{\nu})\phi_k\ra
		\\
		& \quad + 4\frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}\la u_{\nu}, \phi_k\ra\la u_{\nu}, \psi_j\ra\la \phi_k, (I-S_{\nu})\psi_j\ra
		\\
		& \quad + \frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}\la u_{\nu}, \phi_k\ra^2 \la \psi_j, (I-S_{\nu})\psi_j\ra
		%\\
		%& \quad 
		+ \frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}\la u_{\nu}, \phi_k\ra^2\la u_{\nu}, \psi_j\ra^2
		\\
		&\quad + \frac{\alpha_k}{1-\alpha_k}\log(1-\beta_j)[\la \phi_k, (I-S_{\nu})\phi_k\ra + \la u_{\nu}, \phi_k\ra^2]
		\\
		&\quad + \frac{\beta_j}{1-\beta_j}\log(1-\alpha_k) [\la \psi_j, (I-S_{\nu})\psi_j\ra + \la u_{\nu}, \psi_j\ra^2]
		%\\
		%&\quad 
		+ \log(1-\alpha_k)\log(1-\beta_j).
	\end{align*}
	Rearranging the terms in $J_{kj,1}$ gives, with $u_{\nu} = C_{*}^{-1/2}(m_{\nu} - m_{*})$,
\begin{align*}
	J_{kj,1} &= 2\frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}[\la \phi_k, (I-S_{\nu})\psi_j\ra^2] 
	\\
	& \quad + 4\frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}\la u_{\nu}, \phi_k\ra\la u_{\nu}, \psi_j\ra\la \phi_k, (I-S_{\nu})\psi_j\ra
	\\
	&\quad + \left[\frac{\alpha_k}{1-\alpha_k}(\la \phi_k, (I-S_{\nu})\phi_k\ra + \la u_{\nu}, \phi_k\ra^2) + \log(1-\alpha_k)\right]
	\\
	& \quad \times 
	\left[\frac{\beta_j}{1-\beta_j}(\la \psi_j, (I-S_{\nu})\psi_j\ra + \la u_{\nu}, \psi_j\ra^2)+ \log(1-\beta_j)\right].
\end{align*}
Equivalently,
\begin{align*}
	J_{kj,1}	& = 2\frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}[\la \phi_k, (I-S_{\nu})\psi_j\ra^2] 
	\\
	& \quad + 4\frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}\la u_{\nu}, \phi_k\ra\la u_{\nu}, \psi_j\ra\la \phi_k, (I-S_{\nu})\psi_j\ra
	\\
	&\quad + \left[- \frac{\alpha_k}{1-\alpha_k}\la \phi_k, S_{\nu}\phi_k\ra + \frac{\alpha_k}{1-\alpha_k}\la u_{\nu}, \phi_k\ra^2+  \frac{\alpha_k}{1-\alpha_k} + \log(1-\alpha_k)\right]
	\\
	& \quad \times \left[- \frac{\beta_j}{1-\beta_j}\la \psi_j, S_{\nu}\psi_j\ra + \frac{\beta_j}{1-\beta_j}\la u_{\nu}, \psi_j\ra^2+ \frac{\beta_j}{1-\beta_j} + \log(1-\beta_j)\right].
\end{align*}
	%\begin{align*}
	%\left[\frac{\alpha_k}{1-\alpha_k}\right]\left[\frac{\beta_j}{1-\beta_j}\right]
	%\end{align*}
Let us sum the terms in $J_{kj,1}$ separately. By Lemma \ref{lemma:HS-inner-expansion},
		\begin{align}
		&\sum_{k,j=1}^{\infty}\frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}[\la \phi_k, (I-S_{\nu})\psi_j\ra^2] 
		\nonumber
		\\
		&= \trace[(I-S_{\nu})S_1(I-S_1)^{-1}(I-S_{\nu})S_2(I-S_2)^{-1}].
		\label{equation:Jkj-sum-1-1}
		\\
		& \sum_{k=1}^{\infty}\frac{\alpha_k}{1-\alpha_k}\la \phi_k, S_{\nu}\phi_k\ra = \trace(S_{\nu}S_1(I-S_1)^{-1}),
		\label{equation:Jkj-sum-1-2}
		\\
		& \sum_{j=1}^{\infty}\frac{\beta_j}{1-\beta_j}\la \psi_j, S_{\nu}\psi_j\ra  = \trace(S_{\nu}S_2(I-S_2)^{-1}).
		\label{equation:Jkj-sum-1-3}
		\end{align}
		By Lemma \ref{lemma:inner-UV-expansion},
		\begin{align}
			&\sum_{k,j=1}^{\infty}\frac{\alpha_k}{1-\alpha_k}\frac{\beta_j}{1-\beta_j}\la u_{\nu}, \phi_k\ra\la u_{\nu}, \psi_j\ra\la \phi_k, (I-S_{\nu})\psi_j\ra
			\nonumber
			\\
			&= \la S_1(I-S_1)^{-1}u_{\nu}, (I-S_{\nu})S_2(I-S_2)^{-1}u_{\nu}\ra.
			\label{equation:Jkj-sum-2}
		\end{align}
		By Lemma \ref{lemma:quadratic-form-expansion},
		\begin{align}
			&\sum_{k=1}^{\infty}\frac{\alpha_k}{1-\alpha_k}\la u_{\nu}, \phi_k\ra^2 
			%\nonumber
			%\\
			%&
			= 
			\la u_{\nu}, S_1(I-S_1)^{-1}u_{\nu}\ra,
			\label{equation:Jkj-sum-3-1}
			\\
		&	\sum_{j=1}^{\infty}\frac{\beta_j}{1-\beta_j}\la u_{\nu}, \psi_j\ra^2
		%\nonumber
		%\\
		%&
		=	\la u_{\nu}, S_2(I-S_2)^{-1}u_{\nu}\ra.
		\label{equation:Jkj-sum-3-2}
		\end{align}
		By Lemma \ref{lemma:logdet-2-inverse},
