	\sum_{k=1}^{\infty}\left[\frac{\alpha_k}{1-\alpha_k} + \log(1-\alpha_k)\right] = -	\log\dettwo[(I-S_1)^{-1}],
	\label{equation:Jkj-sum-4-1}
	\\
	 \sum_{j=1}^{\infty}\left[\frac{\beta_j}{1-\beta_j} + \log(1-\beta_j)\right] = -	\log\dettwo[(I-S_2)^{-1}].
	 \label{equation:Jkj-sum-4-2}
		\end{align}
		Combining
		% the expressions in 
		Eqs.\eqref{equation:Jkj-sum-1-1}, \eqref{equation:Jkj-sum-1-2}, \eqref{equation:Jkj-sum-1-3}, \eqref{equation:Jkj-sum-2}, \eqref{equation:Jkj-sum-3-1}, \eqref{equation:Jkj-sum-3-2}, \eqref{equation:Jkj-sum-4-1}, \eqref{equation:Jkj-sum-4-2}, we obtain
		\begin{align}
		%J &= \left\la \log\left\{{\frac{d\mu_1}{d\mu_{*}}(x)}\right\}, \log\left\{{\frac{d\mu_2}{d\mu_{*}}(x)}\right\}\right\ra_{\Lcal^2(\Hcal,\nu)} = 
		&\frac{1}{4}\sum_{k,j=1}^{\infty}J_{kj,1} 
		%\\
		%&
		= \frac{1}{2}\trace[(I-S_{\nu})S_1(I-S_2)^{-1}(I-S_{\nu})S_1(I-S_2)^{-1}]
