		\\
		&\quad + \la S_1(I-S_1)^{-1}u_{\nu}, (I-S_{\nu})S_2(I-S_2)^{-1}u_{\nu}\ra
		\nonumber
		\\
		& \quad + \frac{1}{4}\left[\la u_{\nu}, S_1(I-S_1)^{-1}u_{\nu}\ra - \trace(S_{\nu}S_1(I-S_1)^{-1})-	\log\dettwo[(I-S_1)^{-1} \right]
		\nonumber
		\\
		& \quad \quad \times \left[\la u_{\nu}, S_2(I-S_2)^{-1}u_{\nu}\ra-\trace(S_{\nu}S_2(I-S_2)^{-1})-	\log\dettwo[(I-S_2)^{-1}\right].
		\label{equation:sum-Jkj-1-total}
		\end{align}
