Next, we calculate $J_{kj,2}$. For each pair $k,j \in \Nbb$,
	\begin{align*}
	& J_{kj,2}=-\frac{2}{1-\beta_j}\int_{\Hcal}\left[\frac{\alpha_k}{1-\alpha_k}W^2_{\phi_k}(x)+ \log(1-\alpha_k)\right]\la u_2, \psi_j\ra W_{\psi_j}(x)d\nu(x)
	\\
	&+ \frac{4}{(1-\alpha_k)(1-\beta_j)}\int_{\Hcal}\la u_1, \phi_k\ra W_{\phi_k}(x)\la u_2, \psi_j\ra W_{\psi_j}(x)d\nu(x)
	\\
	& - \frac{2}{1-\alpha_k} \left[\frac{\beta_j}{1-\beta_j}W^2_{\psi_j}(x) + \log(1-\beta_j)\right]\la u_1, \phi_k\ra W_{\phi_k}d\nu(x)
	\\
	&= - \frac{2\alpha_k\la u_2, \psi_j\ra[\la  (I-S_{\nu})\phi_k, \phi_k\ra\la u_{\nu}, \psi_j\ra +  2\la u_{\nu}, \phi_k\ra\la (I-S_{\nu})\phi_k, \psi_j\ra + \la u_{\nu}, \phi_k\ra^2\la u_{\nu}, \psi_j\ra]}{(1-\alpha_k)(1-\beta_j)}
	\\
	& \quad - \frac{2\la u_2, \psi_j\ra \la u_{\nu}, \psi_j\ra \log(1-\alpha_k)}{1-\beta_j}
	\\
	& \quad + \frac{4\la u_1, \phi_k\ra \la u_2, \psi_j\ra [\la \phi_k, (I-S_{\nu})\psi_j\ra + \la u_{\nu}, \phi_k\ra \la u_{\nu}, \psi_j\ra]}{(1-\alpha_k)(1-\beta_j)}
	\\
	& \quad - \frac{2\beta_j\la u_1, \phi_k\ra[\la  (I-S_{\nu})\psi_j, \psi_j\ra\la u_{\nu}, \phi_k\ra +  2\la u_{\nu}, \psi_j\ra\la (I-S_{\nu})\psi_j, \phi_k\ra + \la u_{\nu}, \psi_j\ra^2\la u_{\nu}, \phi_k\ra]}{(1-\alpha_k)(1-\beta_j)}
	\\
	& \quad - \frac{2\la u_1, \phi_k\ra \la u_{\nu}, \phi_k\ra\log(1-\beta_j)}{1-\alpha_k}.	
\end{align*}
Rearranging the terms in $J_{kj,2}$ gives
\begin{align*}
	&J_{kj,2} = -2 \frac{\la u_2, \psi_j\ra\la u_{\nu}, \psi_j\ra}{1-\beta_j}\left[\frac{\alpha_k\la  (I-S_{\nu})\phi_k, \phi_k\ra}{(1-\alpha_k)} +  \log(1-\alpha_k) + \frac{\alpha_k}{1-\alpha_k}\la u_{\nu}, \phi_k\ra^2\right] 
