	\\
	& \quad - 2\frac{\la u_1, \phi_k\ra\la u_{\nu}, \phi_k\ra}{1-\alpha_k}\left[\frac{\beta_j\la  (I-S_{\nu})\psi_j, \psi_j\ra}{(1-\beta_j)} + \log(1-\beta_j) + \frac{\beta_j}{1-\beta_j }\la u_{\nu}, \psi_j\ra^2\right]
	\\
	& \quad - \frac{4\beta_j\la u_1, \phi_k\ra\la u_{\nu}, \psi_j\ra\la (I-S_{\nu})\psi_j, \phi_k\ra ]}{(1-\alpha_k)(1-\beta_j)}.
\end{align*}
Summing each of the terms in $J_{kj,2}$ individually, we get for the first term,
\begin{align}
	&\sum_{k,j=1}^{\infty}\frac{\la u_2, \psi_j\ra\la u_{\nu}, \psi_j\ra}{1-\beta_j}\left[\frac{\alpha_k\la  (I-S_{\nu})\phi_k, \phi_k\ra}{(1-\alpha_k)} +  \log(1-\alpha_k) + \frac{\alpha_k}{1-\alpha_k}\la u_{\nu}, \phi_k\ra^2\right] 
	\nonumber
	\\
	& = \la (I-S_2)^{-1}u_2,u_{\nu}\ra
