	\nonumber
	\\
	& = -\la (I-S_2)^{-1}u_2,u_{\nu}\ra  [\trace(S_{\nu}S_1(I-S_1)^{-1})+\log\dettwo(I-S_1)^{-1} ]
	\nonumber
	\\
	&\quad + \la (I-S_2)^{-1}u_2,u_{\nu}\ra \la u_{\nu}, S_1(I-S_1)^{-1}u_{\nu}\ra].
