\end{align}
For the second term,
\begin{align}
	&\sum_{k,j=1}^{\infty}\frac{\alpha_k\la u_2, \psi_j\ra\la u_{\nu}, \phi_k\ra\la (I-S_{\nu})\phi_k, \psi_j\ra }{(1-\alpha_k)(1-\beta_j)}
	\nonumber
	\\
