	\nonumber
	\\
	& = \la (I-S_1)^{-1}u_1, (I-S_{\nu})(I-S_2)^{-1}u_2\ra + \la (I-S_1)^{-1}u_1,u_{\nu}\ra \la (I-S_2)^{-1}u_2,u_{\nu}\ra. 
