	\begin{align}
		&\int_{\Hcal}\exp\left(\frac{1}{2}\la M y, y\ra + \la b,y\ra\right)\Ncal(0,Q)(dy)
		%\nonumber
		\\
		& = [\det(I - Q^{1/2}MQ^{1/2})]^{-1/2}\exp\left(\frac{1}{2}||(I-Q^{1/2}MQ^{1/2})^{-1/2}Q^{1/2}b||^2\right).
		\nonumber
	\end{align}
\end{theorem}

The following result is standard, for the proof see e.g. \cite{Minh:2021RiemannianEstimation}. 
\begin{lemma}
\label{lemma:trace-class-orthogonal-projection}
Let $A \in \Tr(\Hcal)$. Let $\{e_k\}_{k \in \Nbb}$ be any
orthonormal basis in $\Hcal$. Let $N \in \Nbb$. Consider the orthogonal projection
$P_N = \sum_{k=1}^Ne_k \otimes e_k$. Then
\begin{align}
\lim_{N \approach \infty}||P_NAP_N-A||_{\trace} = \lim_{N \approach \infty}||P_NA-A||_{\tr} = \lim_{N\approach \infty}||AP_N - A||_{\tr} = 0.
\end{align}
\end{lemma}

