We now prove the following result, whose statement is well-defined by the limits in Proposition \ref{proposition:RN-S-trace-class-quadratic-form-convergence}. It is a generalization of Proposition 6 in \cite{Minh:2020regularizedDiv}.

\begin{proposition}
	\label{proposition:exponetial-quadratic-whitenoise-Gaussian}
	Let $\mu = \Ncal(m,C) \in \Gauss(\Hcal)$, $C \in \Sym^{++}(\Hcal) \cap \Tr(\Hcal)$.
	Assume that $A \in \SymTr(\Hcal)_{< I}$, $b \in \Hcal$. Consider
	the orthogonal projection $P_N = \sum_{k=1}^N e_k \otimes e_k$, $N \in \Nbb$, where $\{e_k\}_{k \in \Nbb}$
	are the orthonormal eigenvectors of $C$.
	Define
	\begin{align}
	&\la C^{-1/2}(x-m), AC^{-1/2}(x-m)\ra + \la C^{-1/2}(x-m),b\ra 
	%\nonumber
	\\
	&\doteq \lim_{N \approach \infty}\la C^{-1/2}P_N(x-m), AC^{-1/2}P_N(x-m)\ra + \la C^{-1/2}P_N(x-m),b\ra,
	\nonumber
	\end{align}
	where the limit is in the $\Lcal^2(\Hcal,\mu)$ sense.
	Then
	\begin{align}
		&\int_{\Hcal}\exp\left(\frac{1}{2}\la C^{-1/2}(x-m), AC^{-1/2}(x-m)\ra + \la C^{-1/2}(x-m),b\ra\right)\Ncal(m,C)(dx)
		\nonumber
		\\
		& = [\det(I- A)]^{-1/2}\exp\left(\frac{1}{2}||(I-A)^{-1/2}b||^2\right).	\label{equation:exponetial-quadratic-whitenoise-Gaussian}
	\end{align}
\end{proposition}
%In the following, 
%we make use of
{\bf Special cases}. Let $A = c_1 g \otimes g$, $b = c_2g$, where $c_1,c_2 \in \R$, $g \in \Hcal$, with $c_1||g||^2 < 1$. Then Eq.\eqref{equation:exponetial-quadratic-whitenoise-Gaussian} gives
	\begin{align}
	&\int_{\Hcal}\exp\left[\frac{1}{2}c_1W_{g}^2(x) + c_2W_{g}(x) \right]\Ncal(m,C)(dx)
	\nonumber
	\\
	&=\frac{1}{(1-c_1||g||^2)^{1/2}}\exp\left(\frac{c_2^2||g||^2}{2(1-c_1||g||^2)}\right).
	%\nonumber
\end{align} 
This is Proposition 6 in \cite{Minh:2020regularizedDiv}. In particular, with $c_1 = 0$,
\begin{align}
	\int_{\Hcal}\exp[c_2W_{g}(x)]\Ncal(m,C)(dx) = \exp\left(\frac{c_2^2}{2}||g||^2\right).
\end{align}
With $c_2 = 1$, the above formula gives Proposition 1.2.7 in \cite{DaPrato:PDEHilbert}.

The proof of Proposition \ref{proposition:exponetial-quadratic-whitenoise-Gaussian} utilizes the Vitali Convergence Theorem on {\it uniformly integrable} sequences of functions,
%which we now recall 
(see e.g. \cite{Folland:Real,Rudin:RealComplex}).
Let 
$(\Xcal, \Fcal, \mu)$ be a positive measurable space. A sequence of functions $\{f_n\}_{n\in \Nbb} \in \Lcal^1(\Xcal,\mu)$ 
is said to be {\it uniformly integrable} if $\forall \epsilon > 0$ $\exists \delta > 0$ such that
\begin{align}
	\sup_{n \in \Nbb}\int_{E}|f_n|d\mu < \epsilon \;\;\; \text{whenever} \;\;\; \mu(E) < \delta, E \in \Fcal.
\end{align}

\begin{theorem}
	[\textbf{Vitali's Convergence Theorem}]
	Assume that $(\Xcal, \Fcal, \mu)$ is a positive measurable space with $\mu(\Xcal) < \infty$.
	Let $\{f_n\}_{n\in \Nbb}$ be a sequence of functions that are uniformly integrable on $\Xcal$, with
	$f_n \approach f$ a.e. and $|f| < \infty$ a.e.. Then $f \in \Lcal^1(\Xcal, \mu)$ and $||f_n - f||_{\Lcal^1(\Xcal, \mu)} \approach 0$.
\end{theorem}
\begin{proof}
	[\textbf{of Proposition \ref{proposition:exponetial-quadratic-whitenoise-Gaussian}}]
	It suffices to prove Eq.\eqref{equation:exponetial-quadratic-whitenoise-Gaussian} for $m=0$.
Define the sequence $\{f_N = \exp\left(\frac{1}{2}\la C^{-1/2}P_Nx, AC^{-1/2}P_Nx\ra + \la C^{-1/2}P_Nx,b\ra\right)\}_{N \in \Nbb}$.
We show that the sequence $\{f_N\}_{N \in \Nbb}$ is uniformly integrable on $(\Hcal,\mu)$, then apply Vitali's convergence theorem.
% is applicable.

By assumption, $A \in \SymTr(\Hcal)_{< I}$, i.e. $A \in \Tr(\Hcal)$ and $I-A > 0$. We first show that $\exists p > 1$ such that
$I -pA > 0$. Let $\{\lambda_k\}_{k\in \Nbb}$ be the eigenvalues of $A$, then $\lambda_k < 1$ $\forall k\in \Nbb$  and $\lim_{k \approach \infty}\lambda_k = 0$. Let $\lambda_{\max}$ be the largest eigenvalue. If $\lambda_{\max} \leq 0$, then
$1-p\lambda_k \geq 1 $ $\forall p > 0$. If $0< \lambda_{\max} <1$, then let $1 < p < \frac{1}{\lambda_{\max}}$, so that
$1-p\lambda_k \geq 1 - p\lambda_{\max} > 0$ $\forall k \in \Nbb$.
Thus it follows that $I-pA > 0$, hence $pA \in \SymTr(\Hcal)_{< I}$.
%\begin{align*}
%	&\la C^{-1/2}P_Nx, AC^{-1/2}P_Nx\ra + \la C^{-1/2}P_Nx,b\ra 
	%\\
	%&= 
%	=\la x, C^{-1/2}P_NAC^{-1/2}P_Nx\ra 
%	+ \la x, C^{-1/2}P_Nb\ra
%\end{align*}

Let $M = C^{-1/2}P_NAC^{-1/2}P_N$. Since $C^{-1/2}P_N \in \Sym(\Hcal)$ and $C^{-1/2}P_NC^{1/2} = P_N$, we have $M \in \Sym(\Hcal)$ and $C^{1/2}MC^{1/2} = P_NAP_N$. Then $P_NAP_N \in \SymTr(\Hcal)_{< I}$ and $pP_NAP_N \in \SymTr(\Hcal)_{< I}$.
Thus by Theorem \ref{theorem:exponential-quadratic-Gaussian},
\begin{align*}
&J_{N,p} \doteq \int_{\Hcal}\exp\left(\frac{p}{2}\la C^{-1/2}P_Nx, pAC^{-1/2}P_Nx\ra + p\la C^{-1/2}P_Nx,b\ra\right) \Ncal(0,C)(dx)
\\
& = \int_{\Hcal}\exp\left(\frac{1}{2}\la x, p C^{-1/2}P_NAC^{-1/2}P_Nx\ra + \la x,pC^{-1/2}P_Nb\ra\right) \Ncal(0,C)(dx)
\\
& = \int_{\Hcal}\exp\left(\frac{1}{2}\la x, pMx\ra + \la x,pC^{-1/2}P_Nb\ra\right)\Ncal(0,C)(dx)
\\
& = [\det(I- pP_NAP_N)]^{-1/2}\exp\left(\frac{p^2}{2}||(I-pP_NAP_N)^{-1/2}P_Nb||^2\right).
\end{align*}
Taking limit as $N \approach \infty$, applying Lemma \ref{lemma:trace-class-orthogonal-projection} and the continuity of the Fredholm determinant in the trace class norm, we obtain
\begin{align}
&\lim_{N \approach \infty}J_{N,p} = \lim_{N \approach \infty}[\det(I- pP_NAP_N)]^{-1/2}\exp\left(\frac{p^2}{2}||(I-pP_NAP_N)^{-1/2}P_Nb||^2\right)
\nonumber
\\
& = [\det(I- pA)]^{-1/2}\exp\left(\frac{p^2}{2}||(I-pA)^{-1/2}b||^2\right) < \infty.
\label{equation:limit-JNp}
\end{align}
Let $q$ be the H\"older conjugate of $p$, i.e. $\frac{1}{p} + \frac{1}{q} = 1$.
By H\"older's inequality, for any set $A \in \Bsc(\Hcal)$,
\begin{align*}
	J_N &\doteq \int_{A}\exp\left(\frac{1}{2}\la C^{-1/2}P_Nx, AC^{-1/2}P_Nx\ra + \la C^{-1/2}P_Nx,b\ra\right) \Ncal(0,C)(dx)
	\\
	&= \int_{\Hcal}\onebf_A\exp\left(\frac{1}{2}\la C^{-1/2}P_Nx, AC^{-1/2}P_Nx\ra + \la C^{-1/2}P_Nx,b\ra\right) \Ncal(0,C)(dx)
	\\
	& \leq \mu(A)^{1/q}
	\\
	& \times \left(\int_{\Hcal}\exp\left(\frac{p}{2}\la C^{-1/2}P_Nx, AC^{-1/2}P_Nx\ra + p\la C^{-1/2}P_Nx,b\ra\right) \Ncal(0,C)(dx)\right)^{1/p}.
\end{align*}
Combining this inequality with the limit in Eq.\eqref{equation:limit-JNp}, it follows that $\forall \epsilon > 0$, $\exists \delta > 0$ such that $\forall A \in \Bsc(\Hcal)$ with $\mu(A) < \delta$,
\begin{align*}
\sup_{N \in \Nbb}\int_{A}\exp\left(\frac{1}{2}\la C^{-1/2}P_Nx, AC^{-1/2}P_Nx\ra + \la C^{-1/2}P_Nx,b\ra\right) \Ncal(0,C)(dx) < \epsilon.
\end{align*}
Thus $\{f_N = \exp\left(\frac{1}{2}\la C^{-1/2}P_Nx, AC^{-1/2}P_Nx\ra + \la C^{-1/2}P_Nx,b\ra\right)\}_{N \in \Nbb}$ is uniformly integrable on $(\Hcal,\mu)$. Since
$\lim_{N \approach \infty}\la C^{-1/2}P_N(x-m), AC^{-1/2}P_N(x-m)\ra + \la C^{-1/2}P_N(x-m),b\ra = \la C^{-1/2}(x-m), AC^{-1/2}(x-m)\ra + \la C^{-1/2}(x-m),b\ra$ in $\Lcal^2(\Hcal,\mu)$, there is a subsequence 
of $\{f_N\}_{N \in \Nbb}$ that converges a.e.
to  $\exp\left(\frac{1}{2}\la C^{-1/2}x, AC^{-1/2}x\ra + \la C^{-1/2}x,b\ra\right)$.
Applying Vitali's convergence theorem to this subsequence then gives
\begin{align*}
&J \doteq \int_{\Hcal}\exp\left(\frac{1}{2}\la C^{-1/2}x, AC^{-1/2}x\ra + \la C^{-1/2}x,b\ra\right)N(0,C)(dx)
\\
&= \lim_{N \approach \infty}\int_{\Hcal}\exp\left(\frac{1}{2}\la C^{-1/2}P_Nx, AC^{-1/2}P_Nx\ra + \la C^{-1/2}P_Nx,b\ra\right)\Ncal(0,C)(dx)
\\
& = \lim_{N \approach \infty}[\det(I-P_NAP_N)]^{-1/2}\exp\left(\frac{1}{2}||(I-P_NAP_N)^{-1/2}P_Nb||^2\right)
\\
& = [\det(I-A)]^{-1/2}\exp\left(\frac{1}{2}||(I-A)^{-1/2}b||^2\right).
\end{align*}
\qed
\end{proof}

The following is a special case of Corollary 3 in \cite{Minh:Positivity2020}.
\begin{lemma}
	\label{lemma:A-alpha-I+A-HS-Tr}
	Let $0 \leq \alpha \leq 1$.
	Let $A \in \Sym(\Hcal) \cap \HS(\Hcal)$, $I+A > 0$. Then
	\begin{align}
		&(1-\alpha)(I+A)^{-\alpha} + \alpha (I+A)^{1-\alpha} \in \PC_1(\Hcal), 
		\\
		\text{with } &(1-\alpha)(I+A)^{-\alpha} + \alpha (I+A)^{1-\alpha} - I \in \Sym(\Hcal) \cap \Tr(\Hcal).
	\end{align}
	\end{lemma}
As a consequence of Lemma \ref{lemma:A-alpha-I+A-HS-Tr}, we have $0 < \det[(1-\alpha)(I+A)^{-\alpha} + \alpha (I+A)^{1-\alpha}] < \infty$ for $0 \leq \alpha \leq 1$
and $A \in \Sym(\Hcal) \cap \HS(\Hcal)$, $I+A > 0$.
\begin{lemma}
[\cite{Minh:2019AlphaBeta}, Lemma 10]
\label{lemma:I+A-power-Tr}
Let $A \in \Sym(\Hcal) \cap \Tr(\Hcal)$, with $I+A > 0$. Let $\beta \in \R$ be fixed but arbitrary.
Then $(I+A)^{\beta} \in \PC_1(\Hcal)$, with $(I+A)^{\beta} - I \in \Sym(\Hcal) \cap \Tr(\Hcal)$.
\end{lemma}
As a consequence of Lemma \ref{lemma:I+A-power-Tr}, for $I+A \in \PC_1(\Hcal)$, we have $\det[(I+A)^{\beta}]$ is well-defined $\forall \beta \in \R$. Furthermore, from definition of $\det(I+A)$,
\begin{align}
	\det[(I+A)^{\beta}] = [\det(I+A)]^{\beta} > 0, \;\;\forall \beta \in \R.
\end{align}
\begin{proposition}
	[\textbf{Normalizing factor}]
	\label{proposition:normalizing factor}
	Assume the hypothesis of Theorem \ref{theorem:geometric-interpolation-equivalent-Gaussian-Hilbert-space}.
	Assume further that $S_i \in \SymTr(\Hcal)_{< I}$, $i=0,1$. Then the normalizing factor $Z_{\alpha}^G(p_0:p_1)$ is given by
	\begin{align}
		&Z_{\alpha}^G(p_0:p_1) \doteq \int_{\Hcal}p_0^{1-\alpha}(x)p_1^{\alpha}(x) \; d\mu_{*}(x)
