		\nonumber
		\\
		& \quad \times \exp\left[-\frac{1-\alpha}{2}||(I-S_0)^{-1/2}C_{*}^{-1/2}(m_0 - m_{*})||^2\right]
		\nonumber
		\\
		& \quad \times 
		\exp\left[-\frac{\alpha}{2}||(I-S_1)^{-1/2}C_{*}^{-1/2}(m_1 - m_{*})||^2\right]
		\nonumber
		\\
		&\quad \times J,
		\label{equation:normalizing-1}
		%\int_{\Hcal}\exp\left\{-\frac{1}{2}\la C_{*}^{-1/2}(x-m_{*}), [(1-\alpha)S_0(I-S_0)^{-1} + \alpha S_1(I-S_1)^{-1}]\right.
		%\\
		%&\quad \quad \quad \quad \quad C_{*}^{-1/2}(x-m_{*})\ra 
		%\right\}
		%\\
		%& \quad \quad \quad \quad \quad +(\la C_{*}^{-1/2}(x-m_{*}), (1-\alpha)(I-S_0)^{-1}C_{*}^{-1/2}(m_0 - m_{*})\ra)
		%\\
		%& \quad \quad \quad \quad \quad \left.+ (\la C_{*}^{-1/2}(x-m_{*}), \alpha(I-S_1)^{-1}C_{*}^{-1/2}(m_1 - m_{*})\ra) \right\}.
