	where $J$ is the following integral over $\Hcal$ with respect to $\mu_{*} = \Ncal(m_{*}, C_{*})$
	\begin{align*}
		J &= \int_{\Hcal}\exp\left\{-\frac{1}{2}\la C_{*}^{-1/2}(x-m_{*}), [(1-\alpha)S_0(I-S_0)^{-1} + \alpha S_1(I-S_1)^{-1}]\right.
		\\
		&\quad \quad \quad \quad \quad C_{*}^{-1/2}(x-m_{*})\ra 
		%\right\}
		\\
		& \quad \quad \quad \quad \quad +(\la C_{*}^{-1/2}(x-m_{*}), (1-\alpha)(I-S_0)^{-1}C_{*}^{-1/2}(m_0 - m_{*})\ra)
