\end{align*}
With this definition of $S_{\alpha}$, we have
\begin{align*}
S_{\alpha}(I-S_{\alpha})^{-1} = -A \equivalent I-A = I+S_{\alpha}(I-S_{\alpha})^{-1} = (I-S_{\alpha})^{-1}.
\end{align*}
It follows that
\begin{align}
\det(I-A) = \det(I-S_{\alpha})^{-1}.
\label{equation:normalize-detI-A-S-alpha}
\end{align}
Define $m_{\alpha} \in \Hcal$ by
\begin{align*}
