The following is a special case of Theorem 33 in \cite{Minh:2019AlphaBeta}.

\begin{proposition}
	[\cite{Minh:2019AlphaBeta}, Theorem 33]
	\label{proposition:limit-(I+A)-power-r}.
	Let $r \in \R$ be fixed but arbitrary.
	Let $A,\{A_k\}_{k\in \Nbb} \in \Sym(\Hcal) \cap \HS(\Hcal)$ be such that $I + A > 0$, $I+A_k > $ $\forall k \in \Nbb$. Assume that
	$\lim_{k \approach \infty}||A_k - A||_{\HS} = 0$. Then
	\begin{align}
		\lim_{k \approach \infty}||(I+A_k)^r - (I+A)^r||_{\HS} = 0.
	\end{align}
\end{proposition}

The following result then follows from Proposition \ref{proposition:limit-(I+A)-power-r} by repeated application of the triangle inequality.

\begin{corollary}
	\label{corollary:limit-product-I+A-I+B}
	Let $A,B,\{A_k\}_{k \in \Nbb}, \{B_k\}_{k \in \Nbb} \in \Sym(\Hcal) \cap \HS(\Hcal)$ be such that $I + A > 0$, $I+B > 0$, $I+A_k > $, $I+B_k > 0$ $\forall k \in \Nbb$. Assume that
	$\lim_{k \approach \infty}||A_k - A||_{\HS} = 0$, $\lim_{k \approach \infty}||B_k - B||_{\HS} = 0$. Then
	\begin{align}
		&\lim_{k \approach \infty}||(I+B_k)^{-1/2}(I+A_k)(I+B_k)^{-1/2} 
		\nonumber
		\\
		& \quad \quad \quad - (I+B)^{-1/2}(I+A)(I+B)^{-1/2}||_{\HS} 
		\\
		&= \lim_{k \approach \infty}||(I+B_k)^{-1/2}(A_k-B_k)(I+B_k)^{-1/2} 
		\nonumber
		\\
		&\quad \quad \quad - (I+B)^{-1/2}(A-B)(I+B)^{-1/2}||_{\HS}
		= 0.
	\end{align}
\end{corollary}

