	\begin{proposition}
	\label{proposition:KL-divergence-equivalent-Gaussian-measures-mu-star}
	Let $\mu_i = \Ncal(m_i, C_i) \in \Gauss(\Hcal, \mu_{*})$, $i=0,1$, with $C_i= C_{*}^{1/2}(I-S_i)C_{*}^{1/2}$, $S_i \in \SymHS(\Hcal)_{< I}$. Then
	\begin{align}
		\KL(\mu_2||\mu_1) &= \frac{1}{2}||C_1^{-1/2}(m_2-m_1)||^2 -\frac{1}{2}\log\dettwo(C_1^{-1/2}C_2C_1^{-1/2})
		\\
		&=\frac{1}{2}||C_1^{-1/2}(m_2-m_1)||^2 - \frac{1}{2}\log\dettwo([(I-S_1)^{-1}(I-S_2)]).
	\end{align}
\end{proposition}

