		%+\frac{\alpha}{\gamma}\left[I - \frac{C_1}{\gamma}\left(\frac{C_1}{\gamma} + I\right)^{-1}\right]
		\\
		& = \frac{1}{\gamma}\left[I - (1-\alpha)C_0(C_0+\gamma I)^{-1} - \alpha C_1(C_1+\gamma I)^{-1}\right] = \frac{1}{\gamma}(I-B),
	\end{align*}
	where $B = (1-\alpha)C_0(C_0+\gamma I)^{-1} +\alpha C_1(C_1+\gamma I)^{-1} \in \SymTr(\Hcal)_{<I}$.
	Thus
	\begin{align*}
		C_{\alpha, \gamma} &= \gamma (I-B)^{-1} =\gamma [I + (I-B)^{-1/2}B(I-B)^{-1/2}] 
