	%	\\
	%	& = -\log\dettwo(I + (1-\alpha)[(C_0+\gamma I)^{-1}(C_1 + \gamma I) - I])
	%\end{align*}
	Since $\mu_0 \sim \mu_1$, $\exists S \in \SymHS(\Hcal)_{< I}$ such that $C_1 = C_0^{1/2}(I-S)C_0^{1/2}$.
	With $C_1 = C_0^{1/2}(I-S)C_0^{1/2} = C_0 - C_0^{1/2}SC_0^{1/2}$, for any $\gamma \in \R, \gamma > 0$, we have $C_1 +\gamma I = C_0+\gamma I - C_0^{1/2}SC_0^{1/2}$ and consequently,
	\begin{align*}
		&(C_0 + \gamma I)^{-1/2}(C_1 + \gamma I)(C_0 + \gamma I)^{-1/2} 
		\\
		&= I - (C_0 + \gamma I)^{-1/2}C_0^{1/2}SC_0^{1/2}(C_0 + \gamma I)^{-1/2}.
	\end{align*}
	By Proposition \ref{proposition:limit-product-A-plus-gamma-B},
	\begin{align*}
		\lim_{\gamma \approach 0^{+}}||(C_0 + \gamma I)^{-1/2}C_0^{1/2}SC_0^{1/2}(C_0 + \gamma I)^{-1/2} - S||_{\HS} = 0.
	\end{align*}
	By the continuity of the Hilbert-Carleman determinant $\dettwo$ in the $\HS$ norm
	\begin{align*}
		&\lim_{\gamma \approach 0^{+}}\log\dettwo(I + (1-\alpha)[(C_0+\gamma I)^{-1/2}(C_1 + \gamma I)(C_0+\gamma I)^{-1/2} - I])
		\\
		&=\log\dettwo[I-(1-\alpha)S],
	\end{align*}
	which is well-defined by Lemma \ref{lemma:Hilbert-Carleman-det2-modified}. Let us express this in terms of the operators $S_{\alpha}, S_0, S_1 \in \SymHS(\Hcal)_{< I}$ as defined in Theorem
	\ref{theorem:geometric-interpolation-equivalent-Gaussian-Hilbert-space}. We have
	\begin{align*}
		(I-S_{\alpha})^{-1} &= (1-\alpha)(I-S_0)^{-1} + \alpha (I-S_1)^{-1},
		\\
		%\end{align*}
		%\begin{align*}
		(I-S_{\alpha})^{-1}(I-S_1) &= (1-\alpha)(I-S_0)^{-1}(I-S_1) + \alpha I.
	\end{align*}
	As in the proof of Proposition \ref{proposition:KL-divergence-equivalent-Gaussian-measures-mu-star}, 
	consider the polar decomposition $(I-S_0)^{1/2}C_{*}^{1/2} = V(C_{*}^{1/2}(I-S_0)C_{*}^{1/2})^{1/2} = VC_0^{1/2}$
	with $V \in \Ubb(\Hcal)$. Then
	\begin{align*}
		I-S &= V^{*}(I-S_0)^{-1/2}(I-S_1)(I-S_0)^{-1/2}V
		\\
		\equivalent S &= I- V^{*}(I-S_0)^{-1/2}(I-S_1)(I-S_0)^{-1/2}V 
		\\
		&= V^{*}[I - (I-S_0)^{-1/2}(I-S_1)(I-S_0)^{-1/2}]V.
	\end{align*}
	With $A \in \Sym(\Hcal) \cap \HS(\Hcal)$, $\dettwo(I+A)$ is completely determined by the eigenvalues of $A$,
	which are the same as those of $V^{*}AV$ for $V \in \Ubb(\Hcal)$. Thus
	\begin{align*}
		&\log\dettwo[I - (1-\alpha)S] 
		\\
		& = \log\dettwo[I - (1-\alpha)V^{*}[I-(I-S_0)^{-1/2}(I-S_1)(I-S_0)^{-1/2}]V]
		\\
		&= \log\dettwo[I - (1-\alpha)[I-(I-S_0)^{-1/2}(I-S_1)(I-S_0)^{-1/2}]]
		\\
		& = \log\dettwo[I - (1-\alpha)[I-(I-S_0)^{-1}(I-S_1)]]
		\\
		& = \log\dettwo[\alpha I + (1-\alpha)(I-S_0)^{-1}(I-S_1)]
		\\
		& = \log\dettwo[(I-S_{\alpha})^{-1}(I-S_1)]
	\end{align*}
	It follows that $\lim_{\gamma \approach 0^{+}}d^1_{\logdet}[(C_1 + \gamma I), C_{\alpha,\gamma}]= -\log\dettwo[(I-S_{\alpha})^{-1}(I-S_1)]$.
	Similarly, $\lim_{\gamma \approach 0^{+}}d^1_{\logdet}[(C_0 + \gamma I), C_{\alpha,\gamma}]= -\log\dettwo[(I-S_{\alpha})^{-1}(I-S_0)]$.
	\qed
\end{proof}


\begin{lemma}
	\label{lemma:equivalent-Gaussian-covariance-range}
	Let $\Ncal(m,C)$, $\Ncal(m_0, C_0)$ be two equivalent Gaussian measures on $\Hcal$. Then
	$\range(C^{1/2}) = \range(C_0^{1/2})$.
\end{lemma}
\begin{proof}
	By Theorem 2.1 in \cite{Fillmore:1971Operator}, for any bounded operator $A \in \Lcal(\Hcal)$, we have $\range(A) = \range(AA^{*})^{1/2}$.
	With $\Ncal(m,C) \sim \Ncal(m_0,C_0)$, $\exists S \in \SymHS(\Hcal)_{< I}$ such that
	$C= C_0^{1/2}(I-S)C_0^{1/2}$. Let $A = C_0^{1/2}(I-S)^{1/2}$, then 
	\begin{align*}
		\range(C^{1/2}) &= \range(AA^{*})^{1/2} = \range(A) = \range[C_0^{1/2}(I-S)^{1/2}] 
		\\
		&= \range(C_0^{1/2}).
	\end{align*} 
	\qed
\end{proof}

