\begin{lemma}
	[\cite{Minh:2020regularizedDiv}]
	\label{lemma:limit-quadratic-form}
	Let $A$ be a self-adjoint, compact, strictly positive operator on $\Hcal$. Then
	\begin{align}
		\lim_{\gamma \approach 0^{+}}\la x, (A+\gamma I)^{-1}x\ra 
		= \left\{
		\begin{matrix}
			||A^{-1/2}x||^2 & \text{ if } x \in \range(A^{1/2}),
			\\
			\infty & \text{otherwise}.
		\end{matrix}
		\right.
