\end{lemma}

\begin{lemma}
	\label{lemma:equivalent-norm-C-m}
	Let $\Ncal(m_0,C_0)$, $\Ncal(m,C)$, $\ker(C) = \ker(C_0) = \{0\}$, be two equivalent Gaussian measures on $\Hcal$, with
	$C = C_0^{1/2}(I-S)C_0^{1/2}$, where $S \in \SymHS(\Hcal)_{< I}$. Then
	\begin{align}
		||C^{-1/2}x|| = ||(I-S)^{-1/2}C_0^{-1/2}x||, \;\; \forall x \in \range(C^{1/2}) = \range(C_0^{1/2}).
	\end{align}
\end{lemma}
\begin{proof}
	%	For $C = C_0^{1/2}(I-S)C_0^{1/2}$, for $m \in \range(C_0^{1/2}) = \range(C^{1/2})$
	%	\begin{align*}
		%		||C^{-1/2}m||^2 = ||[C_0^{1/2}(I-S)C_0^{1/2}]^{-1/2}m||^2 = 
		%	\end{align*}
	We have $\range(C^{1/2}) = \range(C_0^{1/2})$ by Lemma \ref{lemma:equivalent-Gaussian-covariance-range}.
	Since $\ker(C_0) = 0$, the operator $(I-S)^{1/2}C_0^{1/2}$ admits the following polar decomposition
	\begin{align*}
		(I-S)^{1/2}C_0^{1/2} = V[C_0^{1/2}(I-S)C_0^{1/2}]^{1/2},
	\end{align*}
	with $V \in \Ubb(\Hcal)$, from which it follows that
	\begin{align*}
		C^{1/2} = [C_0^{1/2}(I-S)C_0^{1/2}]^{1/2} = V^{*}(I-S)^{1/2}C_0^{1/2} = C_0^{1/2}(I-S)^{1/2}V.
	\end{align*}
	It follows that for  $x \in \range(C_0^{1/2}) = \range(C^{1/2})$,
	\begin{align*}
	C^{-1/2}x = y =  V^{*}(I-S)^{-1/2}C_0^{-1/2}x,
	\end{align*}
	as can be verified directly that $C^{1/2}y = x$. Thus
	\begin{align*}
		||C^{-1/2}x|| = [C_0^{1/2}(I-S)C_0^{1/2}]^{-1/2}x|| &= ||V^{*}(I-S)^{-1/2}C_0^{-1/2}x||
		\\
		& = ||(I-S)^{-1/2}C_0^{-1/2}x||.
	\end{align*}
	\qed
\end{proof}

\begin{proposition}
	\label{proposition:limit-regularized-JS-mean-term}
	Let $\Ncal(m_i,C_i) \in \Gauss(\Hcal, \mu_{*})$. Let
	$m_{\alpha}\in \Hcal, C_{\alpha}\in \Sym(\Hcal)\cap\Tr(\Hcal)$ be defined as in Theorem \ref{theorem:geometric-interpolation-equivalent-Gaussian-Hilbert-space}.
	Let $C_{\alpha,\gamma}$ be defined as in Eq.\eqref{equation:C-alpha-gamma}. Then
	%for $i=0,1$,
	\begin{align}
		\lim_{\gamma \approach 0^{+}}||C_{\alpha,\gamma}^{-1/2}(m_i - m_{\alpha})|| = ||C_{\alpha}^{-1/2}(m_i - m_{\alpha})||, \;\; i=0,1.
	\end{align}
\end{proposition}
\begin{proof}
	[\textbf{of Proposition \ref{proposition:limit-regularized-JS-mean-term}}]
	It suffices to prove for $i=0$.
	With $C_{\alpha,\gamma}=	[(1-\alpha)(C_0 + \gamma I)^{-1} + \alpha (C_1 + \gamma I)^{-1}]^{-1}$, by 
	Lemma \ref{lemma:limit-quadratic-form} we have
	%	With $C_i = C_{*}^{1/2}(I-S_i)C_{*}^{1/2}$, we have
	%\begin{align*}
	%(1-\alpha)C_0 + \alpha C_1 = C_{*}^{1/2}[(1-\alpha)S_0 + \alpha S_1]C_{*}^{1/2}
	%\end{align*}
	\begin{align*}
		&\lim_{\gamma \approach 0^{+}}||C_{\alpha,\gamma}^{-1/2}(m_0 - m_{\alpha})||^2 
		= \lim_{\gamma \approach 0^{+}}\la m_0 - m_{\alpha}, C_{\alpha,\gamma}^{-1}(m_0 - m_{\alpha})\ra
		\\
		& = \lim_{\gamma \approach 0^{+}}\la m_0 - m_{\alpha}, [(1-\alpha)(C_0 + \gamma I)^{-1} + \alpha (C_1 + \gamma I)^{-1}](m_0 - m_{\alpha})\ra
		\\
		& = (1-\alpha)||C_0^{-1/2}(m_0 - m_{\alpha})||^2 + \alpha ||C_1^{-1/2}(m_0-m_{\alpha})||^2.
	\end{align*}
	With $C_i = C_{*}^{1/2}(I-S_i)C_{*}^{1/2}$, $i=0,1$, by Lemma \ref{lemma:equivalent-norm-C-m},
	\begin{align*}
		||C_i^{-1/2}(m_0 - m_{\alpha})||^2 &= ||(I-S_i)^{-1/2}C_{*}^{-1/2}(m_0 - m_{\alpha})||^2 
		\\
		& = \la C_{*}^{-1/2}(m_0 - m_{\alpha}), (I-S_i)^{-1}C_{*}^{-1/2}(m_0 - m_{\alpha})\ra.
	\end{align*}
	Combining this with the previous expression gives
	\begin{align*}
		&\lim_{\gamma \approach 0^{+}}||C_{\alpha,\gamma}^{-1/2}(m_0 - m_{\alpha})||^2 
		\\
		&= 
		\la C_{*}^{-1/2}(m_0 - m_{\alpha}), [(1-\alpha)(I-S_0)^{-1} + \alpha (I-S_1)^{-1}]C_{*}^{-1/2}(m_0-m_{\alpha})\ra
		\\
		& = \la C_{*}^{-1/2}(m_0 - m_{\alpha}), (I-S_{\alpha})^{-1}C_{*}^{-1/2}(m_0 - m_{\alpha})\ra
		\\
		& = ||(I-S_{\alpha})^{-1/2}C_{*}^{-1/2}(m_0 - m_{\alpha})||^2 = ||C_{\alpha}^{-1/2}(m_0 - m_{\alpha})||^2,
	\end{align*}
	where the last equality follows from Lemma \ref{lemma:equivalent-norm-C-m}.
	\qed
\end{proof}

