%     \mathrm{SNR} \;=\;\frac{\lambda_{2}(S)}{\|E\|_{2}}
% =\Theta\!\Bigl((\sqrt{c(\sigma)\,a}-\sqrt{c(\sigma)\,b})\sqrt{\tfrac{n}{\log n}}\Bigr)
% >1
% \end{align*}
% for Davis–Kahan perturbation to drive misclassification to \(o(n)\) (\cite{davis_1970_the, abbe_2015_community}).  Thus exact recovery holds only when \(\bigl(\sqrt{c(\sigma)\,a}-\sqrt{c(\sigma)\,b}\bigr)^2>2\) and \(n/\log n\) is sufficiently large; in regimes where \(\sqrt{n/\log n}\) is small or the raw gap \(\sqrt{c(\sigma)a}-\sqrt{c(\sigma)b}\) is too tiny, MASO may fail to achieve exact reconstruction despite its higher‐order reinforcement.  




\section{GeoDe: Iterative Geometric Denoising}
\label{sec-geode}
We now present Iterative Geometric Denoising (GeoDe), a novel algorithm that boosts community recovery performance via reducing geometric noise. The algorithm is built on top of spectral clustering methods, which are commonly used for community recovery. The goal of GeoDe is to extract a clean SBM such that community structure is more recoverable. This is done through two alternating steps: (1) community inference (C-step) and (2) geometry-informed edge reweighting (G-step). After each C and G- step, edges are reweighted so to emphasize community structure. GeoDe is motivated by the idea that edges are either community-induced or geometry-induced, and we can target geometry-induced edges to enhance community structure. GeoDe is also configurable with various spectral clustering methods, where different spectral clustering functions can be used for the C- and G- step. In our paper, we focus on the case where the same spectral clustering method is used for both steps of the algorithm, but we believe it is an interesting future direction to explore different configurations depending on network type.

We describe GeoDe at Algorithm ~\ref{algorithm:geode}. \footnote{$Q^C$ denotes the $n \times K$ matrix of softmax probabilities of each node's membership to each community. $Q^G$ denotes the $n \times B$ matrix denoting softmax probabilities of each node's membership to each geometric ball. $z^C$ and $z^G$ denote the hard labels for communities and geometric balls respectively.}.

\label{algorithm:geode}
\begin{algorithm}
\caption{GeoDe: Iterative Geometric Denoising}
\DontPrintSemicolon
\LinesNumbered
\KwIn{$H=(V,E,w)$; communities $K$; geometry balls $B$;\\
      spectral routines \textbf{SpecComm}, \textbf{SpecGeom};\\
      initial shrink $\lambda_s$, boost $\lambda_b$; \textbf{Decay}(\,)\,— a schedule applied to $(\lambda_s,\lambda_b)$ each round;\\
      thresholds $\tau_C,\tau_G$ (shrink) and stricter $\tau_C^{+},\tau_G^{+}$ (boost);\\
      weight bounds $w_{\min},w_{\max}$; max iters $T$, patience $P$.}
\KwOut{soft matrix $Q$, hard labels $z$}
\BlankLine
$G\leftarrow H$\;
\For{$t\gets1$ \KwTo $T$}{
  \tcp{C-step}
  $(Q^C,z_C)\leftarrow\textbf{SpecComm}(G,K)$\;
  $p_{ij}\gets\sum_{k=1}^{K} Q^C_{ik}Q^C_{jk}$ \textbf{for all} $(i,j)\in E$\;
  $\mathcal S_C\gets\{(i,j):p_{ij}>\tau_C\}$,\quad $\mathcal B_C\gets\{(i,j):p_{ij}>\tau_C^{+}\}$\;
  %
  \tcp{G-step}
  $(Q^G,z_G)\leftarrow\textbf{SpecGeom}(G,B)$\;
  $c_{ij}\gets\tfrac12\bigl(Q^G_{i,z_G(i)}+Q^G_{j,z_G(j)}\bigr)$\;
  $\mathcal S_G\gets\{(i,j):z_G(i)=z_G(j)\wedge c_{ij}>\tau_G\}$,\quad $\mathcal B_G\gets\{(i,j):z_G(i)=z_G(j)\wedge c_{ij}>\tau_G^{+}\}$\;
  %
  \tcp{Decay step}
  $(\lambda_s,\lambda_b)\leftarrow\textbf{Decay}(\lambda_s,\lambda_b,t)$\;
  %
  \tcp{Re-weight graph}
  \Rescale{$\mathcal S_C\cup\mathcal S_G,\;\lambda_s,\;\text{shrink}$}\quad \Rescale{$\mathcal B_C\cup\mathcal B_G,\;\lambda_b,\;\text{boost}$}\;
  %
  \tcp{Early stopping}
  \If{\NoProgress{$Q^C,P$} \textbf{or} $E(G)=\emptyset$}{\textbf{break}}
}
$Q\leftarrow Q^C$,\quad $z_i\leftarrow\arg\max_k Q_{ik}$\;
\Return{$(Q,z)$}
\end{algorithm}

\paragraph{Community step (C-step).}
The purpose of the C-step is to identify edges that are highly likely to be community induced. By calling a spectral clustering method and finding confidences, we can determine a posterior probability of an edge being between two vertices of the same community.

Let $K$ denote the target number of communities.
We apply a spectral routine
$\textbf{SpecComm}$ (e.g.\ Bethe–Hessian, MASO)
to the current weighted graph $G^{(t)}$ and obtain a soft membership matrix
$Q^C\in[0,1]^{n\times K}$ with
$\sum_{k=1}^{K} Q^C_{ik}=1$.
For every edge $(i,j)\in E$ we compute
\[
  p_{ij}\;=\;\sum_{k=1}^{K} Q^C_{ik}\,Q^C_{jk},
\]
the posterior probability that the endpoints belong to the \emph{same} block.
Edges whose $p_{ij}$ exceed a percentile threshold~$\tau_C$
populate the \emph{shrink set} $\mathcal S_C$;
those above the stricter percentile~$\tau_C^{+}>\tau_C$
form the \emph{boost set} $\mathcal B_C$.
The C-step therefore highlights links that are either
moderately likely (\,$\mathcal S_C$\,) or
almost certain (\,$\mathcal B_C$\,) to be intra-community
according to the current spectral evidence.

\paragraph{Geometry step (G-step).}
To characterize the latent geometric structure, we run a second routine
$\textbf{SpecGeom}$ with $B\!\gg\!K$ clusters
and obtain a soft matrix $Q^G\in\![0,1]^{n\times B}$. This is motivated by the idea that geometric structure arises in tighter formations than community structure, which may be far more expansive. By searching for a much higher number of communities, we aim to uncover the tight geometric formations.

Let $z_G(i)=\arg\max_b Q^G_{ib}$.
For any edge whose endpoints share the same ball
($z_G(i)=z_G(j)$)
we define a geometry confidence
\[
  c_{ij}\;=\;\frac12\bigl(Q^G[i,z_G(i)]
                         +Q^G[j,z_G(j)]\bigr).
\]
Edges with $c_{ij}>\tau_G$ enter the shrink set
$\mathcal S_G$, whereas those with
$c_{ij}>\tau_G^{+}>\tau_G$ fill the boost set $\mathcal B_G$.
The G-step thus isolates links whose presence is best explained
by short latent distances rather than by community affinity.

\paragraph{Edge-reweighting justification.}
At iteration~$t$ the four sets
\(\mathcal S=\mathcal S_C\cup\mathcal S_G\)
and
\(\mathcal B=\mathcal B_C\cup\mathcal B_G\)
drive the multiplicative update
\[
  w_{ij}^{(t+1)} \;=\;
  \begin{cases}
    \displaystyle
    \max\bigl(w_{\min},\;(1-\lambda_s)\,w_{ij}^{(t)}\bigr),
      & (i,j)\in\mathcal S \quad\text{(\emph{shrink})},\\[6pt]
    \displaystyle
    \min\bigl(w_{\max},\;(1+\lambda_b)\,w_{ij}^{(t)}\bigr),
      & (i,j)\in\mathcal B \quad\text{(\emph{boost})},\\[4pt]
    w_{ij}^{(t)}, & \text{otherwise.}
  \end{cases}
\]

  Links flagged by either the C- or G-step in $\mathcal{S}$ are common yet
  only moderately reliable. Scaling them by $(1-\lambda_s)$
  attenuates degree heterogeneity and suppresses geometry-induced noise,
  sharpening subsequent eigenvectors without disconnecting the graph. A tiny top-percentile of edges (\(\mathcal B\))
  is boosted to act as high-confidence \emph{anchors}.
  These anchors stabilize the spectral basis across iterations,
  compensate for heavy censoring, and accelerate convergence.
  The global caps \(w_{\min}\le w_{ij}\le w_{\max}\)
  guarantee that no edge can dominate the Laplacian spectrum. Boosting edges with high latent geometry helps maintain connectivity and spectral stability.

\subsection{Convergence Guarantee}
We now show that GeoDe pushes for convergence to a standard SBM given a latent-kernel SBM as input.
\begin{theorem}[Convergence of GeoDe]
\label{thm:geode-conv}
Let $W^{(t)}\!\in\!\mathbb{R}^{n\times n}$ be the weight matrix after
$t$ GeoDe updates and let $W^{\star}$ denote the latent
stochastic-block-model (SBM) matrix.
Assume the observed adjacency matrix decomposes as
$
   A = W^{\star} + G^{\star},\; G^{\star}\succeq 0 .
$
Let $C$ and $G$ be diagonal projectors onto the (disjoint) edge sets
updated by the \textbf{community} and \textbf{geometry} rules, so that
$CG^{\star}=0$ and $GW^{\star}=0$.

\paragraph{Step-size schedule.}
Choose positive, non-increasing sequences \footnote{In our experiments, we use a linear \textbf{Decay} schedule due to finite $T$, but asymptotic convergence requires an inverse linear schedule.} $\{\lambda_C^{(t)}\}_{t\ge0}$
and $\{\lambda_G^{(t)}\}_{t\ge0}$ obeying
\[
\lambda_C^{(t)},\lambda_G^{(t)}\to 0,\quad
\sum_{t=0}^{\infty}\lambda_C^{(t)}=\infty,\quad
\sum_{t=0}^{\infty}\!\bigl(\lambda_C^{(t)}\bigr)^{2}, \sum_{t=0}^{\infty}\!\bigl(\lambda_G^{(t)}\bigr)^{2}<\infty,\quad \lambda_G^{(t)}\le\gamma\,\lambda_C^{(t)}\text{ for some }\gamma>0
\]

\paragraph{Claim.}
Under these step sizes,
\(
  W^{(t)}\xrightarrow{\text{a.s.}} W^{\star}
\)
and the true community partition is recovered exactly
whenever the SBM eigen-gap satisfies the usual
$K$-cluster signal condition
\(
  \lambda_{\min}(W^{\star})-\lambda_{K+1}(W^{\star})
    \ge c\sqrt{\log n/n}.
\)
\end{theorem}
\begin{proof}[Proof sketch]
Expressing one update in conditional expectation shows that the error
$\Delta^{(t)}=W^{(t)}-W^{\star}$ obeys a stochastic-approximation
recursion whose two orthogonal components (on $C$ and $G$) contract at
rates $\lambda_C^{(t)}$ and $\lambda_G^{(t)}$, respectively.  Taking
Frobenius norms and using the projector orthogonality yields a
super-martingale bound
$\mathbb{E}[\|\Delta^{(t+1)}\|_F^{2}\mid\mathcal F_t]
      \le(1-\lambda_C^{(t)})\|\Delta^{(t)}\|_F^{2}
      +O\!\bigl((\lambda_C^{(t)})^{2}\bigr)$.
Because $\sum_t\lambda_C^{(t)}=\infty$ but
$\sum_t(\lambda_C^{(t)})^{2}<\infty$, the Robbins–Siegmund theorem
implies $\|\Delta^{(t)}\|_F^{2}\to0$ almost surely, i.e.\ convergence to
$W^{\star}$.  Finally, a standard eigen-gap condition ensures that the
limit matrix reveals the correct $K$-cluster partition.  A complete,
step-by-step proof is provided in Appendix~\ref{proof:geode-conv}. We also provide a corollary on GeoDe for exact community recovery in Appendix ~\ref{cor:geode-recovery}.
\end{proof}


\subsection{Limitations}
GeoDe is based on the assumption that geometric noise is independent from community structure, which is often not true. While the boosting of strongly geometric edges does preserve strong relationships between latent features and community membership, GeoDe does not inherently assume a correlation between the two. Another limitation of GeoDe is its efficiency due to its repetitive calls to its spectral clustering base. This perhaps limits GeoDe's usage to particularly challenging graphs and limits its applicability to cases such as temporal networks. 

% ---------------------- Validation Section ----------------------
\section{Validation}
\label{sec-validation}

In this section, we evaluate the performance of our proposed methods—MASO and GeoDe—on both synthetic and real-world networks. We focus on assessing their ability to recover community structure in settings where traditional spectral methods fail due to geometric noise.

\subsection{Synthetic benchmarks}
\label{sec:synthetic}

We generated $\textbf{75}$ independent 
latent-kernel stochastic block model (SBM) at each noise level
$\sigma \in \{0.75, 0.5, 0.25, 0.1\}$, giving us a total of \textbf{300} graphs. We randomly chose the parameters $n, a,b$ with $n \in [100, 1000], a \in [15, 100], b \in [1, 50]$ and generated the latent-kernel SBM according to Definition ~\ref{def:lksbm}.

\begin{figure}[t]
\centering
\includegraphics[width=0.48\textwidth]{spectral_plots.png}%
\hfill
\includegraphics[width=0.48\textwidth]{NEW_recovery_plots.png}
\caption{\textbf{Left:} Average clustering accuracy of four spectral operators as a function of the geometric--noise parameter $\sigma$;“\textbf{MASO}” denotes our Motif--Attention Spectral Operator; “\textbf{Non--Backtracking (Control)}” uses the non--backtracking matrix; “\textbf{Bethe--Hessian (Control)}” is the classical Bethe--Hessian operator; and “\textbf{Motif--Laplacian (Control)}” is the unmodified motif Laplacian.\newline
\textbf{Right:} End--to--end community--recovery accuracy of the GeoDe pipeline instantiated with either the MASO backbone or the Bethe--Hessian backbone, compared against three baselines: belief propagation, motif counting, and the graph neural network \textbf{GCN--MixHop}.}
\label{fig:empirical_results}
\end{figure}


Figure~\ref{fig:empirical_results}(left) demonstrates that MASO
maintains perfect community recovery up to $\sigma\ge0.5$, degrades
only to $0.87$ at $\sigma=0.25$ and $0.59$ at $\sigma=0.1$, thus
outperforming the non–backtracking operator by $2$–$10$ points and
out-performing both Bethe–Hessian~\cite{saade_2025_spectral}
and motif–Laplacian~\cite{benson_2016_higherorder}, which collapse
under moderate noise.

This empirical advantage directly reflects the latent-kernel SBM’s
noise structure: geometric noise injects long‐range “shortcut” edges
that connect otherwise distant communities.  MASO’s multi-hop PPMI
features and motif-guided attention automatically {\it strengthen}
edges with consistent local‐and‐multi‐hop support while {\it
down‐weighting} spurious shortcuts.  In contrast, Bethe–Hessian and
motif–Laplacian treat all small cycles uniformly, and non–backtracking
lacks higher-order motif cues meaning none filter out noise as effectively.

When embedded in the GeoDe pipeline, MASO’s high‐fidelity edge weights
ensure that the motif‐ and geometry‐based pruning rules remove the bulk
of noisy edges before clustering.  As a result,
GeoDe+MASO achieves perfect recovery for $\sigma\ge0.25$ and still
$0.78$ at $\sigma=0.1$ (Figure~\ref{fig:empirical_results}, right),
significantly outperforming belief propagation~\cite{fortunato_2010_community},
motif counting~\cite{benson_2016_higherorder}, and a generic
GCN–MixHop model~\cite{abuelhaija_2019_mixhop} (which remains near
chance).  Over $91\%$ of these runs satisfy the information‐theoretic
exact‐recovery threshold (see Appendix~\ref{addl:exp-threshold}), and
all gains of MASO over non–backtracking and of GeoDe+MASO over the
next‐best competitor are significant at $p=0.05$ after
Benjamini–Hochberg correction (Appendices~\ref{appendix:sig-spec-ops},
\ref{appendix:sig-recovery}). 

