\section{Definitions} 
\label{defs}

\subsection{Definition of Recovery}
\label{def-recovery}
In our work, we focus on the community recovery problem in the latent-kernel stochastic block model (Definition ~\ref{def:lksbm}), in which node connectivity is driven by both hidden community labels and by a smooth kernel on latent positions. Our goal is, given only the observed graph $G$, to design estimators $\hat z \in \{\pm 1\}^n$ that achieve both weak recovery and exact recovery of the true labels $z$. 

Let \(\hat z = \hat z(G)\in\{\pm1\}^n\) be any estimator based on the observed graph \(G\).  We consider two success criteria:

\begin{itemize}
  \item \textbf{Weak recovery.}  We say weak recovery is \emph{achievable} if there exists an estimator \(\hat z\) and a constant \(\epsilon>0\) such that
  \[
    \lim_{n\to\infty}
      \Pr\!\Bigl(\tfrac{1}{n}\sum_{i=1}^n \hat z_i z_i \ge \tfrac12 + \epsilon\Bigr)
    = 1.
  \]
  In other words, the overlap between \(\hat z\) and the truth \(z\) exceeds random guessing by a fixed margin, with probability tending to one.

  \item \textbf{Exact recovery.}  We say exact recovery is \emph{achievable} if there exists an estimator \(\hat z\) satisfying
  \[
    \lim_{n\to\infty}
      \Pr\bigl(\hat z = z)
    = 1.
  \]
  That is,  \(\hat z\) matches the true labeling perfectly with high probability.
\end{itemize}

\subsection{Definition of Belief Propagation Algorithm} 
\label{algorithm:bp}
The belief propagation algorithm we utilized to test against our developed methods follows the following procedure: 
Let \(M_{i\to j}^{(t)}(k)\in[0,1]\) be the message that node \(i\)
sends to neighbour \(j\) at iteration \(t\) in favour of community
\(k\), and let \(w_{ij}\ge 0\) denote the (undirected) edge weight
stored on \(\{i,j\}\).  
Given an inverse–temperature parameter \(\beta>0\), the
weight-aware compatibility factor is  
\[
\phi_{i\to j}^{(t)}(k)
\;=\;
1 + \bigl(e^{\beta\,w_{ij}}-1\bigr)\,
      M_{i\to j}^{(t)}(k)
\]
Larger \(w_{ij}\) therefore amplify the influence of the incoming
belief \(M_{i\to j}^{(t)}(k)\), while smaller weights attenuate it; the
standard Bethe–Peierls update is recovered when \(w_{ij}=1\).


\section{Proofs} 
\label{appendix-proofs}


\subsection{Concentration of Latent-Kernel SBM}
\label{app:concentration}

\begin{definition}[Edge Probability]
\label{def:edge-probability}
	For node pair $(i,j)$, the probability of an edge is
	\[
	\mathbb{P}[(i,j) \in E \mid x_i, x_j, z_i, z_j] = B_{z_i, z_j} \cdot \exp\left(-\frac{\|x_i - x_j\|^2}{2\sigma^2} \right),
	\]
	where $B_{z_i, z_j} = p_{\text{in}}$ if $z_i = z_j$, and $B_{z_i, z_j} = p_{\text{out}}$ otherwise.
\end{definition}

\begin{definition}[Average Kernel]
\label{def:average-kernel}
	\[
	c(\sigma) = \mathbb{E}_{x,y \sim \text{Unif}([0,1]^d)}\left[ \exp\left(-\frac{\|x - y\|^2}{2\sigma^2} \right) \right].
	\]
\end{definition}

\begin{theorem}[Convergence to a Rescaled SBM]
\label{thm:convergence}
Let $G$ be generated by the latent–kernel SBM with two communities, latent positions $x_i \sim \mathrm{Unif}([0,1]^d)$ and edge probabilities as in Definition ~\ref{def:edge-probability}. Then, with high probability as $n\to\infty$, $G$ is contiguous to a classical two,–block SBM with edge parameters

$$
  \pin' = c(\sigma)\,\frac{a\log n}{n}, \qquad
  \pout' = c(\sigma)\,\frac{b\log n}{n},
$$

where $c(\sigma)$ is the average kernel defined in Definition ~\ref{def:average-kernel}.
\end{theorem}

\begin{proof}
Write $\Delta_{ij}=K_{ij}-c(\sigma)\in[-c(\sigma),1-c(\sigma)]\subset[-1,1]$.
Fix a label vector $\tilde z$ at Hamming distance $m$ from the ground truth
$z^{\ast}$ and let
\(
  \mathcal D=\{(i,j):\mathbf 1_{\tilde z_i=\tilde z_j}\neq
                       \mathbf 1_{z_i^{\ast}=z_j^{\ast}}\}
\)
be the set of \emph{disagreement pairs}, whose size is
$T\equiv|\mathcal D|=m(n-m)\le mn$.

\paragraph{Step 1 (moderate-deviation bound).}
For fixed $\mathcal D$ the variables $(\Delta_{ij})_{(i,j)\in\mathcal D}$ are
independent and centred with range~$2$.  Hoeffding’s inequality gives, for any
$\varepsilon>0$,
\[
  \Pr\!\Bigl(\Bigl|\!\!\sum_{(i,j)\in\mathcal D}\!\!\Delta_{ij}\Bigr|
         >\varepsilon T\Bigr)
  \le 2\exp(-2\varepsilon^{2}T).
\]
Choose $\varepsilon=(\log n)^{-1/4}$.  Since
$T\ge m(n-m)\ge m(n/2)$ when $m\le n/2$, we obtain
\[
  2\varepsilon^{2}T \;\;\ge\;\; \frac{m\sqrt{\log n}}{2}.
\tag{1}\label{eq:step1}
\]

\paragraph{Step 2 (union bound over disagreements).}
The number of label vectors at distance $m$ is $\binom{n}{m}$.  Applying
\eqref{eq:step1} and Stirling’s bound $\binom{n}{m}\le (en/m)^m$,
\begin{align*}
  \Pr\Bigl(\exists\,\tilde z\!:&~\bigl|\!\sum_{(i,j)\in\mathcal D}\!\!\Delta_{ij}\bigr|
                   >m\sqrt{\log n}\Bigr) \\
  &\le
  \sum_{m=1}^{n}\binom{n}{m} \,
         2\exp\!\bigl(-m\sqrt{\log n}/2\bigr)
  \;\le\;
  2\sum_{m=1}^{n}\Bigl(\tfrac{e n}{m}\,
         e^{-\sqrt{\log n}/2}\Bigr)^{m}.
\end{align*}
For large $n$, the base of the parenthesis is $<\!1$, so the geometric
series is $o(1)$.  Hence, with probability $1-o(1)$,
\[
  \bigl|\!\!\sum_{(i,j)\in\mathcal D}\!\!\Delta_{ij}\bigr|
  \le m\sqrt{\log n}
  \quad\text{for \emph{all}}~\mathcal D.
\tag{2}\label{eq:step2}
\]

\paragraph{Step 3 (contiguity).}
Condition~\eqref{eq:step2} says that, uniformly over all labelings,
kernel–weighted log-likelihoods differ from their expectations by at most
$o(m\log n)$.  Re-writing the latent–kernel model’s log-likelihood and
subtracting its mean therefore shows the likelihood ratio between the
latent–kernel SBM and the classical SBM with parameters
$(\pin',\pout')$ is $\exp(o(1))$.  Le Cam’s second lemma then yields
mutual contiguity of the two models, completing the proof.
\end{proof}

\subsection{Lemma ~\ref{lem:exp-mixed}}
\begin{lemma}[Expectation of mixed weights]
\label{lem:exp-mixed}
Under the latent–kernel SBM and embedding separation assumptions, the mixed weight satisfies
\[
\mathbb E[\widetilde W_{ij}\mid z_i,z_j]
=\begin{cases}
w_{\rm in}\Bigl[(1-\beta)+\beta\bigl((n_{+}-2)w_{\rm in}^{2}+n_{-}w_{\rm out}^{2}\bigr)\Bigr],
&z_i=z_j,\\[6pt]
w_{\rm out}\Bigl[(1-\beta)+\beta(n-2)\,w_{\rm in}w_{\rm out}\Bigr],
&z_i\neq z_j,
\end{cases}
\]
where $w_{\rm in}=p_{\rm in}e^{\rho_{\rm in}/\sqrt d}$ and $w_{\rm out}=p_{\rm out}e^{\rho_{\rm out}/\sqrt d}$.
\end{lemma}
\begin{proof}
Fix an unordered pair $\{i,j\}$ and write $\delta_{ij}=\mathbf 1\{z_i=z_j\}$.  
Recall
\[
  W_{ij}=A_{ij}\exp\!\bigl(\langle z_i,z_j\rangle/\sqrt d\bigr),
  \quad
  X_{ij}=\sum_{k\neq i,j} W_{ik}W_{kj},
  \quad
  \widetilde W_{ij}=(1-\beta)W_{ij}+\beta W_{ij}X_{ij}.
\]
Throughout let
\[
  w_{\mathrm{in}}
    =p_{\mathrm{in}}e^{\rho_{\mathrm{in}}/\sqrt d},
  \qquad
  w_{\mathrm{out}}
    =p_{\mathrm{out}}e^{\rho_{\mathrm{out}}/\sqrt d},
\]
and denote by $n_{+}$ (resp.\ $n_{-}$) the number of $+1$ (resp.\ $-1$) labels.

\medskip
\textbf{Step 1: Factorization:}
Edge indicators $\{A_{uv}\}_{u<v}$ are mutually independent, hence  
$A_{ij}$ is independent of every $A_{ik},A_{kj}$ for $k\neq i,j$.  
Because $z_\ell$ depends only on the latent variables of vertex $\ell$,  
$W_{ij}$ is independent of every $W_{ik},W_{kj}$ ($k\neq i,j$).  Therefore
\[
  \mathbb{E}\!\bigl[W_{ij}W_{ik}W_{kj}\bigr]
  =\mathbb{E}[W_{ij}]\,\mathbb{E}[W_{ik}]\,\mathbb{E}[W_{kj}],
  \qquad k\neq i,j,
\]
so that
\[
  \mathbb{E}\bigl[W_{ij}X_{ij}\mid z_i,z_j\bigr]
  =\mathbb{E}[W_{ij}\mid z_i,z_j]\,
   \mathbb{E}[X_{ij}\mid z_i,z_j].
\]

\medskip
\textbf{Step 2: One–Hop Expectations:}
\[
  \mathbb{E}[W_{ij}\mid z_i=z_j]=w_{\mathrm{in}},
  \qquad
  \mathbb{E}[W_{ij}\mid z_i\neq z_j]=w_{\mathrm{out}}.
\]

\medskip
\textbf{Step 3: Two–Hop Expectations:}

For same $z$, assume $z_i=z_j=+1$ (the $-1$ case is analogous).  
There are $n_{+}-2$ intermediates $k$ with $z_k=+1$ and $n_{-}$ with $z_k=-1$:
\[
  \mathbb{E}[X_{ij}\mid z_i=z_j]
  =(n_{+}-2)\,w_{\mathrm{in}}^{2} + n_{-}\,w_{\mathrm{out}}^{2}.
\]

For different $z$, W.L.O.G. \ $z_i=+1$, $z_j=-1$.  
For every $k\neq i,j$ one edge is intra, the other inter, giving a product $w_{\mathrm{in}}w_{\mathrm{out}}$:
\[
    \mathbb{E}[X_{ij}\mid z_i\neq z_j]
  =(n-2)\,w_{\mathrm{in}}\,w_{\mathrm{out}}.
\]


\medskip
\textbf{Step 4: Mixed Weights:}
Inserting the above derived results into
\(
  \mathbb{E}[\widetilde W_{ij}]=(1-\beta)\mathbb{E}[W_{ij}]
          +\beta\,\mathbb{E}[W_{ij}]\,\mathbb{E}[X_{ij}],
\)
we obtain
\[
  \mathbb{E}[\widetilde W_{ij}\mid z_i=z_j]
  =w_{\mathrm{in}}\!\Bigl[
      (1-\beta)+\beta\bigl((n_{+}-2)w_{\mathrm{in}}^{2}+n_{-}w_{\mathrm{out}}^{2}\bigr)
    \Bigr],
\]
\[
  \mathbb{E}[\widetilde W_{ij}\mid z_i\neq z_j]
  =w_{\mathrm{out}}\!\Bigl[
      (1-\beta)+\beta(n-2)w_{\mathrm{in}}w_{\mathrm{out}}
    \Bigr],
\]
establishing \eqref{lem:exp-mixed}.  \qedhere
\end{proof}

\subsection{Lemma ~\ref{lem:noise-conc}}
\begin{lemma}[Concentration of the noise matrix]
\label{lem:noise-conc}
Let $E=\widetilde W-\mathbb{E}[\widetilde W]$.  Then with high probability
\[
\|E\|_{2}=O\bigl(\sqrt{\log n}\bigr).
\]
\end{lemma}
\begin{proof}
Recall $E=\widetilde W-\mathbb{E}\widetilde W$ with
\(
  \widetilde W_{ij}
  =(1-\beta)W_{ij}+\beta W_{ij}X_{ij},
\)
where
\(W_{ij}=A_{ij}\exp(\langle z_i,z_j\rangle/\sqrt d)\)
and
\(X_{ij}=\sum_{k\neq i,j}W_{ik}W_{kj}\).
We work in the logarithmic–degree regime
\(
  p_{\mathrm{in}}=a\,c(\sigma)\frac{\log n}{n},
  \;
  p_{\mathrm{out}}=b\,c(\sigma)\frac{\log n}{n},
  \; a>b>0.
\)

\paragraph{1.\ Writing $E$ as a sum of independent matrices.}
For every unordered edge $e=\{i,j\}$ set
\[
  Y_e\;=\;
  \bigl(\widetilde W_{ij}-\mathbb{E}\widetilde W_{ij}\bigr)
  \bigl(e_i e_j^{\!\top}+e_j e_i^{\!\top}\bigr),
\]
so $E=\sum_{e}Y_e$ and $\mathbb{E}Y_e=0$.%
\footnote{%
$e_i$ is the $i$-th standard basis vector in $\mathbb{R}^n$.}
Independent edges give independent matrices $\{Y_e\}$.

\paragraph{2.\ Uniform bound on $\|Y_e\|_{2}$.}
Let
\(
  w_{\mathrm{in/out}}
  =p_{\mathrm{in/out}}\exp(\rho_{\mathrm{in/out}}/\sqrt d)
  =\Theta\!\bigl((\log n)/n\bigr).
\)
Because $A_{ij}\le1$,
\(
  |W_{ij}|\le C_{1}\tfrac{\log n}{n}
\)
for some constant $C_1=C_1(a,b,\sigma,\rho_{\mathrm{in/out}})$.

For any $i\neq j$,
\(
  |W_{ik}W_{kj}|\le C_{1}^{2}(\log n/n)^{2},
\)
and there are at most $n-2$ summands in $X_{ij}$; hence
\[
  |X_{ij}|\;\le\;C_{1}^{2}\,\frac{(\log n)^{2}}{n}.
\]
Multiplying,
\(
  |W_{ij}X_{ij}|\le C_{2}\,(\log n)^{3}/n^{2}
\)
for some $C_{2}$.  Thus
\[
  |\widetilde W_{ij}|
  \;\le\;
  (1-\beta)C_{1}\frac{\log n}{n}
  +\beta C_{2}\frac{(\log n)^{3}}{n^{2}}
  \;\le\;L:=C\,\frac{\log n}{n},
\]
with $C\ge\max\{C_{1},C_{2}\}$.  Therefore
\[
  \|Y_e\|_{2}
  =|\widetilde W_{ij}-\mathbb{E}\widetilde W_{ij}|
  \le 2L
  =O\!\Bigl(\tfrac{\log n}{n}\Bigr).
\tag{1}
\]

\paragraph{3.\ Variance proxy.}
Define $V=\sum_e\mathbb{E}[Y_e^{2}]$.  Because $Y_e$ has only two non-zero
entries in rows $i,j$,
\[
  \|V\|_{2}\;\le\;
  \max_{u\in V}\sum_{v\neq u}
    \mathbb{E}\bigl[(\widetilde W_{uv}-\mathbb{E}\widetilde W_{uv})^{2}\bigr].
\]
Any pair $(u,v)$ is intra-block with probability
$\tfrac{n_{+}(n_{+}-\delta_{uv})+n_{-}(n_{-}-\delta_{uv})}{n(n-1)}$
and inter-block otherwise, but
\(
  (\widetilde W_{uv}-\mathbb{E}\widetilde W_{uv})^{2}
  \le L^{2}.
\)
Hence
\[
  \|V\|_{2}
  \;\le\;
  n\,L^{2}
  =C_{v}\,\frac{(\log n)^{2}}{n},
\quad
  \text{so set } \sigma^{2}:=\|V\|_{2}.
\tag{2}
\]

\paragraph{4.\ Matrix Bernstein.}
Tropp’s matrix Bernstein inequality
~\cite{tropp_2011_userfriendly}
gives for any $t>0$
\[
  \Pr\!\bigl(\|E\|_{2}\ge t\bigr)
  \;\le\;
  2n\exp\!\Bigl(-\tfrac{t^{2}/2}{\sigma^{2}+Lt/3}\Bigr).
\]
Insert $L$ and $\sigma^{2}$ from (1)–(2) and choose
$t=\kappa\sqrt{\log n}$ with $\kappa>3\sqrt{C_{v}}$.
Then $Lt/3\le\sigma^{2}/2$ for all $n$ large, and
\[
  \Pr\!\bigl(\|E\|_{2}\ge\kappa\sqrt{\log n}\bigr)
  \le 2n\exp\!\bigl(-(\kappa^{2}/4)\bigr)
  = n^{-\bigl(\kappa^{2}/4-1\bigr)}.
\]
Taking $\kappa>4$ makes the exponent strictly larger than $2$, so the
probability is $O(n^{-2})$.

\paragraph{5.\ Conclusion.}
With probability at least $1-O(n^{-2})$,
\(
  \|E\|_{2}\le\kappa\sqrt{\log n},
\)
i.e.\ $\|E\|_{2}=O(\sqrt{\log n})$ as claimed.
\end{proof}


\subsection{Proof of Lemma ~\ref{lem:signal-gap}}
\begin{lemma}[Eigen‐gap of the signal]
\label{lem:signal-gap}
Define $S=\mathbb{E}[\widetilde W]$.  Then $S$ has rank~2, and its second eigenvalue
\[
\gamma\;=\;\lambda_{2}(S)
=\tfrac12\,(w_{\rm in}-w_{\rm out})\bigl[1-\beta+\beta\kappa n\bigr]\,n
=\Theta(\log n).
\]
\end{lemma}
\begin{proof}[Proof of Lemma~\ref{lem:signal-gap}]
Let $n_{+}=|\{i:z_i=+1\}|$, $n_{-}=n-n_{+}$ and define the \emph{label vector}
\[
  g_i=\begin{cases}+1,&z_i=+1,\\-1,&z_i=-1.\end{cases}
\]
For $i\neq j$ write $\delta_{ij}=1$ if $z_i=z_j$ and $0$ otherwise.
From Lemma~\ref{lem:exp-mixed},
\[
  \mathbb{E}[\widetilde W_{ij}\mid\delta_{ij}]
  \;=\;
     w_{\mathrm{out}}
     +\tfrac12\,(w_{\mathrm{in}}-w_{\mathrm{out}})\bigl[1-\beta+\beta\kappa n\bigr]\,(2\delta_{ij}-1),
\]
where
\(
  \kappa=\tfrac12\bigl(w_{\mathrm{in}}^{2}+w_{\mathrm{out}}^{2}\bigr)
  =\Theta\!\bigl((\log n/n)^{2}\bigr).
\)
Because the diagonal of $\widetilde W$ is zero, the same formula holds for
all $i\neq j$ and $S:=\mathbb{E}\widetilde W$ can be written
\[
  S=\alpha\,\mathbf 1\mathbf 1^{\!\top}+\beta^{\star}gg^{\!\top},\qquad
  \alpha:=w_{\mathrm{out}}+\tfrac12\beta^{\star},\qquad
  \beta^{\star}:=\tfrac12\,(w_{\mathrm{in}}-w_{\mathrm{out}})\bigl[1-\beta+\beta\kappa n\bigr].
\]
\emph{Rank}.  The matrices $\mathbf 1\mathbf 1^{\!\top}$ and $gg^{\!\top}$ each
have rank~$1$.  If $g$ were collinear with $\mathbf 1$ the model would place
every vertex in the same community, which is excluded.  Hence $g\not\parallel\mathbf1$
and $\mathrm{rank}(S)=2$.

\smallskip
\emph{Eigenvalues.}
Let $u=\mathbf 1/\sqrt n$ and
\(
  h=g-\frac{\langle g,u\rangle}{\langle u,u\rangle}\,u
   =g-\frac{n_{+}-n_{-}}{n}\,\mathbf 1
\)
be the projection of $g$ onto the subspace $u^{\perp}$.  Then
$u\perp h$, $\|u\|=1$ and
\(
  \|h\|^{2}=n-\frac{(n_{+}-n_{-})^{2}}{n}.
\)

Because $u u^{\!\top}h=0$,
\[
  S\,h
  =\bigl(\alpha\,\mathbf 1\mathbf 1^{\!\top}+\beta^{\star}gg^{\!\top}\bigr)h
  =\beta^{\star}(g^{\!\top}h)\,g
  =\beta^{\star}\Bigl(n-\frac{(n_{+}-n_{-})^{2}}{n}\Bigr)h.
\]
Thus $h$ is an eigenvector of $S$ with eigenvalue
\[
  \lambda_{2}(S)
  =\beta^{\star}\Bigl(n-\frac{(n_{+}-n_{-})^{2}}{n}\Bigr)
  =\tfrac12\,(w_{\mathrm{in}}-w_{\mathrm{out}})\bigl[1-\beta+\beta\kappa n\bigr]
     \Bigl(n-\frac{(n_{+}-n_{-})^{2}}{n}\Bigr).
\]
Whenever both communities contain a linear fraction of vertices
(i.e.\ $\min\{n_{+},n_{-}\}=\Theta(n)$) the factor in parentheses
is $\Theta(n)$, giving
\[
  \boxed{\;
    \lambda_{2}(S)
    =\tfrac12\,(w_{\mathrm{in}}-w_{\mathrm{out}})
       \bigl[1-\beta+\beta\kappa n\bigr]\,n
       \;=\;\Theta(\log n).
  \;}
\]
(The leading eigenvalue is $\lambda_{1}(S)=(\alpha n+\beta^{\star}(n_{+}-n_{-}))>0$,
and all remaining eigenvalues are zero, confirming rank~2.)
\end{proof}

\subsection{Lemma ~\ref{lem:davis-kahan}}
\begin{lemma}[Davis--Kahan perturbation]
\label{lem:davis-kahan}
Let $\hat v$ be the second eigenvector of $\widetilde W=S+E$.  Then
\[
\sin\angle(\hat v,v_{2}(S))
\;\le\;\frac{\|E\|_{2}}{\gamma}
\;=\;O\bigl((\log n)^{-1/2}\bigr),
\]
so the preliminary labels $\text{sign}(\hat v_i)$ disagree with the planted labels on only $o(n)$ vertices.
\end{lemma}
\begin{proof}
Recall the decomposition $\widetilde W = S + E$, where $S=\mathbb{E}\widetilde W$
is rank~$2$ (Lemma~\ref{lem:signal-gap}) and $E$ is a centred noise matrix.
Let $v_{2}=v_{2}(S)$ be the (unit) eigenvector corresponding to
$\lambda_{2}(S)=\gamma$ and let $\hat v$ be the second unit eigenvector of
$\widetilde W$.

\paragraph{1.\ Davis--Kahan angle bound.}
Because $S$ is symmetric, $\lambda_{3}(S)=0$ and
\(
  \gamma=\lambda_{2}(S)-\lambda_{3}(S)>0.
\)
The sin–$\Theta$ form of the Davis--Kahan theorem
\cite[Theorem~4]{davis_1970_the} states
\[
  \sin\angle(\hat v,v_{2})
  \;\le\;
  \frac{\|E\|_{2}}{\gamma}.
\tag{1}
\]
By Lemma~\ref{lem:noise-conc},
$\|E\|_{2}=O(\sqrt{\log n})$, and Lemma~\ref{lem:signal-gap} gives
$\gamma=\Theta(\log n)$; hence
\[
  \sin\angle(\hat v,v_{2})
  =O\!\bigl((\log n)^{-1/2}\bigr).
\tag{2}
\]

\paragraph{2.\ Translating angle to Hamming error.}
Let
\(
  g_i = \pm1
\)
be the planted labels and note $v_{2}=g/\|g\|$ with
$\|g\|^{2}=n_{+}+n_{-}=n$.  Write
\(
  \hat v = \cos\theta\,v_{2} + \sin\theta\,u
\)
where $\theta=\angle(\hat v,v_{2})$ and $u\perp v_{2}$, $\|u\|=1$.
Then for each vertex $i$
\[
  \bigl|\hat v_i - v_{2,i}\bigr|
  \le 2\sin\theta.
\]
A sign mistake occurs only if
$\hat v_i v_{2,i}<0$, which requires
$|\hat v_i - v_{2,i}|\ge 2/\|g\| = 2/\sqrt n$.
Hence the number of errors satisfies
\[
  \#\{\text{mislabelled }i\}
  \;\le\;
  \frac{\|\hat v - v_{2}\|_{2}^{2}}{(2/\sqrt n)^{2}}
  = \frac{n}{4}\,\sin^{2}\theta.
\tag{3}
\]
Using (2) we get
\(
  \sin^{2}\theta = O\bigl((\log n)^{-1}\bigr),
\)
so (3) yields
\[
  \#\{\text{mislabelled }i\}
  = O\!\bigl(n/\log n\bigr)=o(n).
\]

\paragraph{3.\ Conclusion.}
Combining (1)--(3) we have
\[
  \sin\angle(\hat v,v_{2})
  \le\frac{\|E\|_{2}}{\gamma}
  =O\bigl((\log n)^{-1/2}\bigr),
  \qquad
  \#\{\text{errors}\}=o(n),
\]
completing the proof.\qedhere
\end{proof}

\subsection{Proof of Theorem \ref{thm:motif-attention-exact-recovery}}
\label{proof:motif-attention-exact-recovery}
\begin{proof}
By Lemma \ref{lem:exp-mixed} the \emph{signal gap} \(\Delta=\mathbb{E}[\widetilde W_{ij}\mid z_i=z_j]  \mathbb{E}[\widetilde W_{ij}\mid z_i\neq z_j]\) is amplified to $\Theta(\log n)$.  Lemma \ref{lem:noise-conc} shows the \emph{noise} satisfies  $\|E\|_{2}=O(\sqrt{\log n})$, and Lemma \ref{lem:signal-gap} gives the signal eigen‐gap $\gamma=\Theta(\log n)$.  Applying Lemma \ref{lem:davis-kahan}, the spectral sign‐rule mislabels only $o(n)$ vertices.  A single pass of the local‐flip refinement step then corrects all remaining errors, yielding exact recovery with probability $1-o(1)$. \end{proof}


\subsection{Proof of Exact Recovery Threshold}
\label{app:exact-exact-recovery}

\begin{theorem}
\label{thm:app-exact-recovery}
    In the latent–kernel SBM of Definition~\ref{def:lksbm}, exact recovery of the planted labels is possible if and only if
\[
  \bigl(\sqrt{c(\sigma)\,a} - \sqrt{c(\sigma)\,b}\bigr)^2 > 2.
\]
\end{theorem}

The two directions are handled by the following lemmas.

\begin{lemma}[Impossibility below threshold]
\label{lem:impossibility}
If 
\[
  \bigl(\sqrt{c(\sigma)\,a} - \sqrt{c(\sigma)\,b}\bigr)^2 < 2,
\]
then any estimator misclassifies a positive fraction of vertices with probability \(1 - o(1)\).
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:impossibility}]
Let \(z\in\{\pm1\}^n\) be the true balanced labeling, so \(|\{i:z_i=+1\}|=n/2\).  By Fano’s inequality,
\[
  \Pr\{\hat z \neq z\}
  \;\ge\;
  1 \;-\; \frac{I(z;G) + 1}{H(z)}
  \;=\;
  1 \;-\; \frac{I(z;G) + 1}{n\ln 2}.
\]
A simple pairwise KL‐divergence calculation shows that changing one label contributes only \(O(\log n)\) to the mutual information \(I(z;G)\).  Hence \(I(z;G) = o(n)\) whenever \((\sqrt{c(\sigma)a} - \sqrt{c(\sigma)b})^2 < 2\), and the error probability tends to~1.
\end{proof}

\begin{lemma}[Achievability above threshold]
\label{lem:achievability}
If 
\[
  \bigl(\sqrt{c(\sigma)\,a} - \sqrt{c(\sigma)\,b}\bigr)^2 > 2,
\]
then the maximum‐likelihood estimator recovers all labels with probability \(1 - o(1)\).
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:achievability}]
Write \(a' = c(\sigma)\,a\) and \(b' = c(\sigma)\,b\).  For any labeling \(z\) differing from the truth in \(m\) vertices, Chernoff bounds yield
\[
  \Pr\{\ell(z)\ge\ell(z^*)\}
  \;\le\;
  \exp\!\Bigl[-\,m\Bigl(\tfrac12(\sqrt{a'}-\sqrt{b'})^2 - o(1)\Bigr)\ln n\Bigr].
\]
There are at most \(\binom{n}{m}\le (en/m)^m\) such choices of \(z\), and summing over \(m=1,\dots,n/2\) shows the total error probability is \(o(1)\) exactly when \((\sqrt{a'}-\sqrt{b'})^2>2\).
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:app-exact-recovery}]
Lemma~\ref{lem:impossibility} shows no algorithm can achieve exact recovery below the threshold, while Lemma~\ref{lem:achievability} exhibits the maximum‐likelihood estimator above it.  This completes the proof of the sharp recovery threshold.
\end{proof}


