\subsection{Proof of Weak Recovery Threshold}
\label{proof-weak-recovery}
\begin{theorem}[Weak Recovery Threshold]
\label{thm:weak-recovery}
With the same notation, non-trivial recovery is possible iff

$$
  \left(c(\sigma)a-c(\sigma)b\right)^2 > 2\bigl(c(\sigma)a+c(\sigma)b\bigr).
$$

\end{theorem}

We again divide the argument into impossibility and algorithmic
achievability.

\begin{lemma}[Impossibility below the KS line]\label{lem:ks-line}
If \(\bigl(c(\sigma)a-c(\sigma)b\bigr)^{2}\le
     2\bigl(c(\sigma)a+c(\sigma)b\bigr)\),
every estimator’s signed overlap is \(o(1)\) with probability \(1-o(1)\).
\end{lemma}

\begin{lemma}[Achievability above the KS line]\label{lem:above-ks}
If \(\bigl(c(\sigma)a-c(\sigma)b\bigr)^{2}>
     2\bigl(c(\sigma)a+c(\sigma)b\bigr)\),
a polynomial-time algorithm achieves positive overlap.
\end{lemma}

\paragraph{Proof of Lemma~\ref{lem:ks-line}.}
By Theorem~\ref{thm:convergence} the latent-kernel SBM is contiguous to an
ordinary SBM with parameters \(a',b'\).  When the stated inequality
holds, the SBM law is mutually contiguous with
\(G\!\bigl(n,\tfrac{a'+b'}{2}\tfrac{\log n}{n}\bigr)\)
(e.g.\ \cite{elchananmossel_2014_reconstruction}),
which carries no community information, forcing overlap \(o(1)\).\hfill\(\triangle\)

\paragraph{Proof of Lemma~\ref{lem:above-ks}.}
Above the KS line, the leading eigenvector of the non-backtracking
matrix correlates with the true labels
\cite{bordenave_2015_nonbacktracking}; belief propagation converges to a
similar fixed point.  Either algorithm runs in \(O(n\log n)\) time and
achieves non-zero overlap.\hfill\(\triangle\)

\begin{proof}[Proof of Theorem~\ref{thm:weak-recovery}]
Lemma~\ref{lem:ks-line} shows detection is impossible below the
threshold, while Lemma~\ref{lem:above-ks} furnishes an explicit
algorithm above it, establishing the claimed phase transition.
\end{proof}
\subsection{Proof of Theorem~\ref{thm:geode-conv}}
\begin{proof}
\label{proof:geode-conv}
\textbf{One-step expectation.}
With $\mathcal F_t=\sigma(W^{(0)},\dots,W^{(t)})$,
\[
  \mathbb{E}\!\bigl[W^{(t+1)}\mid\mathcal F_t\bigr]
  =\bigl(I-\lambda_C^{(t)}C-\lambda_G^{(t)}G\bigr)W^{(t)}
   +\lambda_C^{(t)}CW^{\star}-\lambda_G^{(t)}GG^{\star}.
\]
Set $\Delta^{(t)}:=W^{(t)}-W^{\star}$ and subtract $W^{\star}$:
\[
  \mathbb{E}\!\bigl[\Delta^{(t+1)}\mid\mathcal F_t\bigr]
  =(I-\lambda_C^{(t)}C-\lambda_G^{(t)}G)\,\Delta^{(t)}
  +(\lambda_C^{(t)}-\lambda_G^{(t)})\,GG^{\star}.
\]

\textbf{Orthogonality.}
Because $C$ and $G$ are orthogonal projectors, the two summands above
are Frobenius-orthogonal; hence
\begin{align*}
  \mathbb{E}\!\bigl[\|\Delta^{(t+1)}\|_{F}^{2}\mid\mathcal F_t\bigr]
  &=
    (1-\lambda_C^{(t)})^{2}\|C\Delta^{(t)}\|_{F}^{2}
   +(1-\lambda_G^{(t)})^{2}\|G\Delta^{(t)}\|_{F}^{2}
   +(\lambda_C^{(t)}-\lambda_G^{(t)})^{2}\|G^{\star}\|_{F}^{2}.
\end{align*}

\textbf{Contraction bound.}
Since $0<\lambda_C^{(t)},\lambda_G^{(t)}\le1$,
\(
  (1-\lambda_G^{(t)})^{2}\le1
\)
and
\(
  (1-\lambda_C^{(t)})^{2}\le 1-\lambda_C^{(t)}.
\)
Using
$\|C\Delta^{(t)}\|_{F}^{2}+\|G\Delta^{(t)}\|_{F}^{2}
  =\|\Delta^{(t)}\|_{F}^{2}$
and the schedule $\lambda_G^{(t)}\le\gamma\lambda_C^{(t)}$,
\[
  \mathbb{E}\!\bigl[\|\Delta^{(t+1)}\|_{F}^{2}\mid\mathcal F_t\bigr]
  \;\le\;
  \bigl(1-\lambda_C^{(t)}\bigr)\|\Delta^{(t)}\|_{F}^{2}
  +2\,\bigl(\lambda_C^{(t)}\bigr)^{2}\bigl(\|W^{\star}\|_{F}^{2}
                                          +\gamma^{2}\|G^{\star}\|_{F}^{2}\bigr).
  \tag{$\ast$}
\]

\textbf{Robbins–Siegmund argument.}
The second term on the right of ($\ast$) is summable because
$\sum_t(\lambda_C^{(t)})^{2}<\infty$.
Moreover $\sum_t\lambda_C^{(t)}=\infty$.  Hence
$\{\,\|\Delta^{(t)}\|_{F}^{2}\,\}$ is a non-negative super-martingale
with summable additive drift; Robbins–Siegmund’s theorem gives
\(
  \|\Delta^{(t)}\|_{F}^{2}\xrightarrow{\text{a.s.}}0,
\)
i.e.\ $W^{(t)}\to W^{\star}$ almost surely.
\end{proof}
\subsection{GeoDe Exact Community Recovery}
\begin{corollary}[Exact community recovery]
\label{cor:geode-recovery}
Assume, in addition to the hypotheses of Theorem~\ref{thm:geode-conv},
that the number of communities $K$ is fixed and the SBM eigen-gap obeys
\[
  \lambda_{\min}(W^{\star})-\lambda_{K+1}(W^{\star})
     \;\ge\; c\,\sqrt{\tfrac{\log n}{n}}
\]
for some constant $c>0$.
Define the stopping time
\[
  t^{\ast}:=\min\Bigl\{t: \|W^{(t)}-W^{\star}\|_{2}
                           \le c\sqrt{\tfrac{\log n}{n}}\Bigr\}.
\]
Then, with probability \(1-o(1)\), the partition obtained from the
$K$ leading eigenvectors of $W^{(t^{\ast})}$ equals the true community
assignment.
\end{corollary}

\begin{proof}
Apply Theorem~\ref{thm:geode-conv} to obtain
$W^{(t)}\!\to W^{\star}$ almost surely.  
The operator-norm threshold in the definition of $t^{\ast}$ then
triggers Davis–Kahan’s sine-$\Theta$ bound together with the stated
eigen-gap, which forces the mis-clustering error to vanish and yields
exact recovery with probability \(1-o(1)\).
\end{proof}
