\section{Additional Tools}

\subsection{Concentration bounds} We provide some basic concentration inequalities that will be used in our analyses. 

\begin{lemma}[\cite{BR94}]\label{lem:hash}
Let $\lambda \geq 4$ be an even integer. Let $X$ be the sum of $n$ $\lambda$-wise independent random variables which take values in $[0,1]$. Let $\mu = E[X] $ and $A > 0$. Then,
$$\Pr [|X - \mu| > A] \leq 8 \left( \frac{\lambda \mu + \lambda^2}{A^2}\right)^{\lambda / 2}.$$
\end{lemma}


\begin{theorem}[Multiplicative Chernoff Bound \cite{mitzenmacher2017probability}]\label{thm:mult_chernoff}
    Let $X = \sum_{i = 1}^n X_i$ where each $X_i$ is a Bernoulli variable which takes value $1$ with probability $p_i$ and value $0$
    with probability $1-p_i$. Let $\mu = \E[X] = \sum_{i = 1}^n p_i$. Then, 
    \begin{enumerate}
        \item Upper Tail: $\Pr[X \geq (1+\eta) \cdot \mu] \leq \exp\left(-\frac{\eta^2\mu}{2 + \eta}\right)$ for all $\eta > 0$;
        \item Lower Tail: $\Pr[X \leq (1-\eta) \cdot \mu] \leq \exp\left(-\frac{\eta^2\mu}{3}\right)$ for all $0 < \eta < 1$.
    \end{enumerate}
\end{theorem}

\begin{lemma}[Chernoff Bound of Gaussian Random Variable]\label{lem:chernoff}  For $X \sim \N(0, \sigma^2)$, $\Pr(|X| > t) \leq 2\exp (-t^2 / 2\sigma^2) $.
\end{lemma}

\subsection{Information theory basics}
\label{sec:info}
We provide some basic information theory definitions and facts that are used in Section \ref{sec:lb}. In this paper, we use $\log$ to refer to the base $2$ logarithm.

\begin{definition}
The \emph{entropy} of a random variable $X$, denoted by $H(X)$, is defined as $H(X) = \sum_x \Pr[X = x] \log(1 / \Pr[X = x])$. 
\end{definition}

\begin{definition}
The \emph{conditional entropy} of random variable $X$ conditioned on random variable $Y$ is defined as $H(X|Y) = \mathbb{E}_y[H(X|Y = y)] = \sum_y \Pr[Y=y] \cdot H(X|Y=y)$. 
\end{definition}
\begin{definition}
\label{def:muinfo}
The \emph{mutual information} between two random variables $X$ and $Y$ is defined as $I(X;Y) = H(X) - H(X|Y) = H(Y) - H(Y|X)$. 
\end{definition}


\begin{definition}
The \emph{conditional mutual information} between $X$ and $Y$ given $Z$ is defined as $I(X;Y|Z) =  \mathbb{E}_z[I(X; Y|Z = z)]$
\end{definition}

\begin{fact}
\label{fact:infofact}
Let $X,Y,Z$ be three random variables.
\begin{enumerate}
\item $H(X|Y) \geq H(X|Y,Z)$.
\item $H(X) \leq \log | \text{supp}(X) |$.
\item $I(X;Y|Z) \leq H(X|Z)$.
\item Data processing inequality: for a deterministic function $f(X)$, $I(X;Y|Z) \geq I(f(X);Y|Z)$.
\item $I(X;Y|Z) \geq 0$.
\end{enumerate}
\end{fact}


\section{Additional details on \textsf{KSET}}\label{app:kset}
We describe the \textsf{TESTSINGLETON} data structure (Algorithm~\ref{alg:ts}) which is a building block of the \textsf{KSET} data structure in more detail.

\begin{algorithm}[!ht]
\caption{TEST-SINGLETON data structure }
\label{alg:ts}
\begin{algorithmic}[1]
\REQUIRE{Input stream $x_1, x_2, \ldots, x_T$}
\STATE{Initialize $m \rightarrow 0, U \rightarrow 0, V \rightarrow 0$}
\STATE{\textbf{TSUPDATE$(x_t)$:}} 
\IF{$x_t$ is an insertion of item $i$}
\STATE{$m \leftarrow m + 1, U \rightarrow U + i , V \rightarrow V + i^2$}
\ELSIF{$x_t$ is a deletion}
\STATE{$m \leftarrow m - 1, U \rightarrow U - i , V \rightarrow V - i^2$}
\ENDIF
\STATE{\textbf{TSCARD():}}
\IF{$m = 0$}
\STATE{Return EMPTY}
\ELSIF{$U^2  = m \cdot V$}
\STATE{Return (SINGLETON, $U/m$, $m$)}
\ELSE
\STATE{Return COLLISION}
\ENDIF
\end{algorithmic}
\end{algorithm}

The \textsf{TESTSINGLETON} data structure supports the following operations:
\begin{enumerate}
    \item An update operation, \textsf{TSUPDATE}$(x_t)$, which updates  three counters --- $m_{TS}$, $U$, and $V$ (all initialized to zero) preserving the following invariants throughout the stream:
    \begin{align*}
        m_{TS}=\sum_{a \in \cU} f_a,\; \; U=\sum_{a \in \cU} f_a\cdot a,\;\; V=\sum_{a \in \cU} f_a\cdot a^2.
    \end{align*}
    More precisely, for an non-empty update $x_t$ corresponding to data item $a$, \textsf{TSUPDATE}$(x_t)$ performs the following update:
    \begin{align*}
        m_{TS}&:= m_{TS}+1,\; \; U=U+a,\; \; V=V+a^2 \; \; \\
        &\textrm{(for an addition)}\\
        m_{TS}&:= m_{TS}-1,\; \; U=U-a,\; \; V=V-a^2 \; \; \\
        &\textrm{(for a deletion)}.
    \end{align*}
    \item A check operation, \textsf{TSCARD}$()$, which determines whether the \textsf{TESTSINGLETON} data structure: (1) is empty, (2) contains a single element, or (3) has more than a single element. The function returns, in each case respectively: (1) EMPTY (this happens if $m_{TS}=0$); (2) the triplet SINGLETON, the element, and its frequency (this happens if $U^2=m_{TS}\cdot V)$; or (3) COLLISION (if the last two checks fail). It is easy to see that the unique item returned (in the SINGLETON case) has identity $\frac{U}{m_{TS}}$ and has frequency $m_{TS}$.
\end{enumerate}


\section{Omitted Proofs from Section \ref{sec:analysis-cd}}\label{app.proofs}

For ease of analysis, we define the streams produced after applying the hash function and the blocklisting procedure (in the case when $ob=false$) as follows. These streams will be used as intermediate steps in the analysis of \textsf{CountDistinct} to separately reason about the hashing and blocklisting procedures, and their impact on sensitivity of the resulting streams.


\begin{definition}\label{def:hash-stream}
    Define $\cS_{i,g}$ as the substream of $x$ after applying hash function $g$. That is, let $a$ be the item contained in the update $x_t$. Then $\cS_{i,g}[t]=x_t$ if $g(a)=i$ and $\cS_{i,g}[t]=\bot$ otherwise.  
\end{definition}


\begin{definition}\label{def:bl-stream}
    Define $\cS_{i,B}$ as the stream of updates produced from $\cS_{i,g}$
     after checking whether the item corresponding to the update $x_t$ is in the blocklist $\cB$ before time $t$ or not. That is, if the item corresponding to $x_t$ is in $\cB$ before time $t$, then $\cS_{i,B}[t]=\bot$, otherwise $\cS_{i,B}[t]=\cS_{i,g}[t]$. 
\end{definition}

\subsection{Proof of Lemma \ref{lem:new_privacy} and Helper Lemma}\label{app.newprivacyproof}

\ksetexactmatch*

\begin{proof}
We start with the case when $ob=false$, which is the more involved case. 
Consider the randomness of \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$. Observe that because of the fixed randomness of both hashing and blocklisting, the resulting streams $\cS_{i,B}$ (see \cref{def:bl-stream}) that are respectively used to update the \textsf{KSET} (in the case of \textsf{COUNTING-KSET}$_i$) and the \textsf{DICT} data structure (in the case of \textsf{COUNTING-DICT}$_i$) are identical. 


Next, define the randomness of \textsf{COUNTING-KSET}$_i$ as $\cR_{KC_i} = \cR_{KS_i}\times \cR_{BM_i}$ where $\cR_{KS_i}$ denotes the randomness from the \textsf{KSET} (\cref{alg:kset}) and $\cR_{BM_i}$ denotes the randomness from \textsf{BinaryMechanism-CD} (\cref{alg:bm}).
On the other hand, the only randomness in \textsf{COUNTING-DICT}$_i$ is due to the randomness of \textsf{BinaryMechanism-CD}, i.e., $\cR_{EC_i} = \cR_{BM_i}$. We emphasize that because the randomness from adding items to the blocklist has been fixed across \textsf{CountDistinct} and \textsf{CountDistinct'}, the blocklist $\cB$ passed to both \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$ are identical. 

We now want to argue that the outputs of \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$ are the same except with probability $\beta$. Let the \textsf{BinaryMechanism-CD} instance in \textsf{COUNTING-KSET}$_i$ be denoted as \textsf{BinaryMechanism-CD}$_{KC_i}$ and the \textsf{BinaryMechanism-CD} instance in \textsf{COUNTING-DICT}$_i$ as \textsf{BinaryMechanism-CD}$_{EC_i}$, and fix the randomness used in \textsf{BinaryMechanism-CD}$_{KC_i}$ and \textsf{BinaryMechanism-CD}$_{EC_i}$. 

We claim that there are two bad events for which the outputs of \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$ may differ. 

\begin{itemize}
  \item \textbf{E}$_1$: There exists a timestep where the true count $\leq k$ and 
    the \textsf{KSET} outputs NIL. 
   \item \textbf{E}$_2$: There exists a timestep where the true count is $> k$ and the noisy count of \textsf{COUNTING-DICT}$_i \leq k$.   
\end{itemize}

By setting $k \geq \tau + O\left( \frac{\text{polylog}  (T/\beta) \sqrt{W} }{\sqrt{\rho}} \right)$, we argue that both events happen with probability at most $\beta$. 

For the event \textbf{E}$_1$, the probability of the \textsf{KSET} outputting NIL happens with probability at most $\beta/2TL$ for one timestep. This is because, in Line~\ref{line:kset-count-init} of \textsf{COUNTING-KSET}$_i$, we set $k$ as the capacity of the \textsf{KSET} and $\beta/2TL$ as the failure probability. So by \cref{it:kset-s} in \cref{lem:k-set-acc} and union bound over all timesteps, this event happens with probability at most $\beta/2L$. 

For the event \textbf{E}$_2$, \cref{lem:e2-occur} (below) bounds the probability of $\textbf{E}_2$ as $\beta/2L$ over all timesteps for our choice of $k$.

Now, conditioned on bad events \textbf{E}$_1$ and \textbf{E}$_2$ \emph{not} occurring over all timesteps, we argue that the outputs of \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$ are identical. Let $t_1$ be the \emph{first} timestep that the true count is $>k$. Let $t_2 > t_1$ be the next timestep that the true count is $\leq k$. We next consider the outputs of the two algorithms by cases across timesteps.
\begin{itemize}
    \item \textbf{Case 1: $1 \leq t < t_1$.} Conditioned on event \textbf{E}$_1$ not occurring, the \textsf{KSET} does not output NIL during this time epoch, which means that the inputs to \textsf{BinaryMechanism-CD}$_{KC_i}$ and \textsf{BinaryMechanism-CD}$_{EC_i}$ are identical, since both \textsf{BinaryMechanism-CD}$_{KC_i}$ and \textsf{BinaryMechanism-CD}$_{EC_i}$ will be updated with only the update from the previous timestep. In this case, the resulting noisy outputs will be the same under the fixed randomness, and the output of \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$ after the thresholding step (comparison to $\tau$) is identical. 

\item \textbf{Case 2: $t_1 \leq  t < t_2 $.} 
For timesteps in this epoch, both \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$ will output TOO-HIGH. Since the true count is $>k$ for all $t_{1} \leq t < t_{2} $, and conditioned on \textbf{E}$_2$ not occurring, the output of \textsf{COUNTING-DICT}$_i$ must be TOO-HIGH. Also by \cref{it:kset-full} in \cref{lem:k-set-acc}, the \textsf{KSET} outputs NIL for this time period with probability $1$, which means that the output of \textsf{COUNTING-KSET}$_i$ is also TOO-HIGH. 

\item \textbf{Case 3: $t = t_2$.} 
Next we argue about the output of \textsf{COUNTING-DICT}$_i$ and \textsf{COUNTING-KSET}$_i$ at timestep $t_2$ when the true count $\leq k$.  Conditioning on event \textbf{E}$_1$ not occurring, the \textsf{KSET} does not output NIL at timestep $t_2$ because the true count $\leq k$. Moreover, observe that \textsf{BinaryMechanism-CD}$_{KC_i}$ is not updated over $t_1< t <t_2$ and is only updated at timestep $t_2$ because the \textsf{KSET} does not output NIL. Also, by construction of \textsf{COUNTING-KSET}$_i$, we claim that \textsf{BinaryMechanism-CD}$_{KC_i}$ is fed a sequence of inputs ($+1,-1,0$) at timestep $t_{2}$ that result in the same sum and the same length as in \textsf{BinaryMechanism-CD}$_{EC_i}$ over $t_{2} - t_{1}$ timesteps. This is because by definition, $\textsf{diff}$ is the difference in the number of distinct elements between times $t_1-1$ and $t_2$, and $\vert \textsf{diff} \vert \leq t_{\textsf{diff}}$, as there can only be $\leq t_{\textsf{diff}}$ many distinct elements added (or removed) over $t_2-t_1$.  Since the length and sum of the sequence of inputs to both \textsf{BinaryMechanism-CD}$_{KC_i}$ and \textsf{BinaryMechanism-CD}$_{EC_i}$ at timestep $t_{2}$ is the same, the outputs of both \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$ are the same at timestep $t_{2}$ under the fixed randomness. 
\end{itemize}

   This argument can be extended over all timesteps by iteratively considering the \emph{next} timestep when the true count is $>k$ and the following timestep when the true count is $\leq k$. Thus when $ob=true$, except with probability $\beta/L$ corresponding to the events \textbf{E}$_1$ and \textbf{E}$_2$ occurring, \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$ will produce identical outputs at each timestep. That is, the distributions of \textsf{COUNTING-KSET}$_i$ and \textsf{COUNTING-DICT}$_i$, denoted $K$ and $E$ respectively, will agree on all outcomes except a subset of probability mass $\beta/L$, which implies that that $d_{TV}(K,E)\leq \beta/L$. 

   For the case when $ob=true$, the blocklisting step is not needed. Then the fixed randomness between \textsf{CountDistinct} and \textsf{CountDistinct}' means that the randomness of the hash functions of both algorithms will be the same, so the resulting stream $\cS_{i,g}$ (see \cref{def:hash-stream}) that is used to update the \textsf{KSET} (in the case of \textsf{COUNTING-KSET}$_i$) and the \textsf{DICT} data structure (in the case of \textsf{COUNTING-DICT}$_i$) is identical. The rest of the argument follows symmetrically to the case when $ob=false$. 
\end{proof}

\subsubsection{Helper Lemma}

\begin{lemma}\label{lem:e2-occur}
Let \textbf{E}$_{BM}$ be the event that there exists a timestep where the noisy count of \textsf{BinaryMechanism-CD}$_{EC_i}$ is greater than $k$ when the true count is less than $\tau$, or the noisy count of \textsf{BinaryMechanism-CD}$_{EC_i}$ is less than $\tau$ when the true count is greater than $k$. The probability of \textbf{E}$_{BM}$ is at most $\beta/2L$ over all timesteps when $k \geq \tau + 2\sqrt{2} \frac{(\log T + 1)^{3/2}\sqrt{W \log(4T\lceil \log(T) \rceil/\beta)}}{\sqrt{\rho}} $. 
\end{lemma}
\begin{proof}
For notational convenience, let $\Delta = k - \tau$. 
From Algorithm~\ref{alg:bm}, we know that the noise that we apply to the true count is a summation of at most $m \leq \log T + 1$ Gaussian random variables, each sampled from $\N(0, 4W(\log T + 1) L / \rho)$. (Recall that the input privacy parameter to the binary mechanism is $\rho/L$). Thus the overall noise added is $N(0, 4mW(\log T + 1) L / \rho)$. 
Now we want to bound the probability that $|\N(0, 4mW(\log T + 1) L / \rho)| > \Delta$, which is an upper bound on the probability of $\textbf{E}_{BM}$ occurring at a single timestep. 

Applying a Chernoff bound (Lemma~\ref{lem:chernoff}) yields:
\begin{align*}
    & \Pr(|\N(0, 4mW(\log T + 1) L / \rho) | > \Delta) \leq  2\exp (-\frac{\Delta^2 \rho}{8mW(\log T+1) L} )
\end{align*}
We wish to bound the above term on the right by $\beta/2TL$, so that then by a union bound, the probability of $\textbf{E}_{BM}$ over all timesteps is bounded by $\beta/2L$. This requires:
\begin{align*}
- \frac{\Delta^2 \rho} {8mWL(\log T+ 1)} &\leq \log (\beta/4TL)\\
\Longleftrightarrow \quad \quad  \Delta  &\geq 2\sqrt{2} \frac{\sqrt{mWL(\log T+1) \log(4TL/\beta)}}{\sqrt{\rho}}
\end{align*}
Recall that our goal is to set the value of $\Delta = k -\tau$ such that the above inequality always holds, and we want to set $\Delta$ to be the upper bound of the right hand side. 
Since $m \leq \log T + 1$  and $L = \lceil \log T \rceil \leq \log T + 1$, 
then, choosing $k \geq t + 2\sqrt{2} \frac{(\log T + 1)^{3/2}\sqrt{W \log(4T\lceil \log(T)\rceil/\beta)}}{\sqrt{\rho}} $ will ensure that $\Delta$ is a valid upper bound, and hence that the probability of $\textbf{E}_{BM}$ over all timesteps is bounded by $\beta / 2L$. 
\end{proof}

