    {\mathcal{P}_{s}^{\text{NL}}=\frac{1}{\Gamma(\alpha)}\Gamma\left(\alpha,\frac{\beta\mathcal{A}_{3}^{2}\left(N_{2}\mathcal{E}+\mathcal{E}_{con}\right)}{\mathcal{A}_{1}\mathcal{A}_{3}-\mathcal{A}_{3}\left(N_{2}\mathcal{E}+\mathcal{E}_{con}\right)-\mathcal{A}_{2}}\right),}\label{pofehNL}
