\vspace{-15pt}\subsection{RIS Resource Allocation}\vspace{-5pt}
As discussed earlier, to ensure that all the $N_{2}$ REs can beamform the signals, ${\mathcal{E}_{H}^{\zeta}}\geq \mathcal{E}_{C}$ is required. Thus, for an efficient RIS resource allocation, we aim to minimize the number of REs operating in {the} absorption mode, $N_{1}$, which leads to the maximization of $N_{2}$ and ${\mathcal{P}_{s}^{\zeta}}=\mathrm{P_{r}}\left({\mathcal{E}_{H}^{\zeta}}\geq \mathcal{E}_{C}\right)$. The corresponding optimization problem is formulated as
\vspace{-10pt}\begin{align}
    &\text{min}\ \  N_{1}=N-N_{2}\nonumber\\
     &\text{s.t.}\ \ {\mathcal{E}_{H}^{\zeta}}\geq \mathcal{E}_{C}, \ N_{1}\geq 1, \ N_{2}\geq 1
\end{align}

{Since the harvested energy increases as $N_1$ increases, it can be stated that ${\mathcal{P}_{s}^{\zeta}}$ increases monotonically with $N_1$. Consequently, if ${\mathcal{P}_{s}^{\zeta}} = 1$ holds for a particular $N_1$, it will also hold for any larger value of $N_1$. Conversely, if ${\mathcal{P}_{s}^{\zeta}} < 1$ for a given $N_1$, the condition will remain ${\mathcal{P}_{s}^{\zeta}} < 1$ for any smaller value of $N_1$. This monotonicity implies that it is a quasi-convex problem, as there exists a unique smallest $N_1$ that satisfies the condition \cite{convex}. Hence, the binary search is an appropriate method for solving this problem, as it reduces the search range by halving the interval in each iteration \cite{binsearch}. Additionally, this method significantly reduces the computational complexity compared to the exhaustive search method, which requires evaluating ${\mathcal{P}_{s}^{\zeta}}$ for all possible values of $N_1$ \cite{binsearch}. {Therefore, the binary search algorithm presented in Algorithm \ref{ALG1}, whose flow‐process diagram is illustrated in Fig. \ref{flowdiag}, provides an efficient and optimal solution to the aforementioned minimization problem.}
\vspace{-10pt}\begin{algorithm}
 \caption{Binary Search Algorithm for RIS RE Allocation}\label{ALG1}
 \begin{algorithmic}[1]
 \renewcommand{\algorithmicrequire}{\textbf{Input:}}
 \renewcommand{\algorithmicensure}{\textbf{Output:}}
 \REQUIRE $N$, $K$, $\eta$, ${\mathcal{A}_{1}}$, ${\mathcal{A}_{2}}$, ${\mathcal{A}_{3}}$, $P_{k}$, $d_{1}^{(k)}$, $a$, $\mathcal{E}$, $\mathcal{E}_{con}$
 \ENSURE  $ N_{1}^{*}$, $ N_{2}^{*}=N-N_{1}^{*}$
 \\ \textit{Initialization} :
  \STATE Set the lower-bound and upper-bound on the number of REs for EH as $N_{1,\text{L}}\leftarrow 1$ and $N_{1,\text{U}}\leftarrow (N-1)$
 \\ \textit{Search Process:}
  \WHILE {$N_{1,\text{L}}\leq N_{1,\text{U}}$}
  \STATE Calculate the midpoint, i.e., $N_{1}=\left\lfloor\frac{N_{1,\text{L}}+ N_{1,\text{U}}}{2}\right\rfloor$
  \STATE $N_{2}\leftarrow (N-N_{1})$
  \STATE Calculate ${\mathcal{P}_{s}^{\zeta}}$ using (\ref{pofeh}) {for LEH model and (\ref{pofehNL}) for NLEH model}
  \IF{${\mathcal{P}_{s}^{\zeta}}=\mathrm{P_{r}}\left({\mathcal{E}_{H}^{\zeta}}\geq \mathcal{E}_{C}\right)=1$}
  \STATE Update $N_{1,\text{U}}\leftarrow (N_1-\mathbf{1}(N_1=N_{1,\text{U}}))$, where $\mathbf{1}$ is the indicator function
  \ELSIF{${\mathcal{P}_{s}^{\zeta}}< 1$ \AND $N_{1} = N-1$}
  \STATE Break and return $N_{1}^{*} = N-1$ and $N_{2}^{*} = 1$
  \ELSE 
  \STATE Update $N_{1,\text{L}}\leftarrow (N_1+\mathbf{1}(N_1=N_{1,\text{L}}))$
  \ENDIF
  \ENDWHILE
 \RETURN $N_{1}^{*}$, which is the smallest value of $N_{1}$ that satisfies ${\mathcal{P}_{s}^{\zeta}}=\mathrm{P_{r}}\left({\mathcal{E}_{H}^{\zeta}}\geq \mathcal{E}_{C}\right)=1$ and leads to the maximum number of REs capable of beamforming, or $N_{1}^{*}=N-1$ and $N_{2}^{*}=1$ if no such $N_{1}$ exists.
 \end{algorithmic} 
 \end{algorithm}
