\vspace{-27pt}\subsection{Accurate Bit Error Rate (BER) Analysis}\label{SECII-C}
\vspace{-8pt}Taking into account the repetition coding technique, the BER of the system with $\mathcal{R}$ repetitions can be obtained by applying a simple majority vote decoding method {\cite{31130,4539783}}. In this method, the Rx decodes the bit as 1 if more 1s than 0s are received, {otherwise a bit of 0 is declared} \cite{31130,4539783}. Therefore, the BER of the system with $\mathcal{R}$ repetitions can be expressed as\cite[Eq.~(2)]{31130}
\vspace{-5pt}\begin{align}
    \widehat{\mathcal{P}}_{b}=\sum_{r=(\mathcal{R}+1)/2}^{\mathcal{R}}\frac{\mathcal{R}!}{r!(\mathcal{R}-r)!}\mathcal{P}_{b}^{r}\left(1-\mathcal{P}_{b}\right)^{\mathcal{R}-r},\label{ABERsys}
\end{align}
where $\mathcal{P}_{b}$ is the BER in the $r$-th repetition, and $\mathcal{R}$ is odd. 

To derive $\mathcal{P}_{b}$, the energies of the received signal over $M$ samples for both bit-0 and bit-1 in the $r$-th repetition are compared with a threshold, $\gamma_{th}$, which is expressed as\cite{10269022}
\vspace{-5pt}\begin{align}
    \mathcal{P}_{b}=\frac{1}{2}\mathrm{P_{r}}\left(\textstyle\sum_{m=1}^{M}\left|x_{m,r}\right|^{2}>\gamma_{th}|\text{bit-0}\right)+\frac{1}{2}\mathrm{P_{r}}\left(\textstyle\sum_{m=1}^{M}\left|x_{m,r}\right|^{2}\leq \gamma_{th}|\text{bit-1}\right).\label{Pbr}
\end{align}

Since $s_{m,r}$, $s_{k}$, and $w_{m,r}$ are zero-mean complex Gaussian RVs, the received signal given in (\ref{rec1}) is also a complex Gaussian RV but conditioned on the random number of REs, fading channels and RIS phase shifts, such that $x_{m,r}\sim\mathcal{CN}(0,\sigma_{x,0}^{2})$ for bit-0 and $x_{m,r}\sim\mathcal{CN}(0,\sigma_{x,1}^{2})$ for bit-1, where the conditional variances, $\sigma_{x,\chi}^{2} \ \chi\in\{0,1\}$, can be written as   
\vspace{-5pt}\begin{align}
   \sigma_{x,\chi}^{2}=
    \begin{cases}
     \sigma_{x,0}^{2}=\mathcal{D}\sigma_{0}^{2}+\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0},&  \text{for bit-0}\\ 
    \sigma_{x,1}^{2}=\mathcal{D}\sigma_{1}^{2}+\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0},&  \text{for bit-1},\label{convar}
\end{cases}
\end{align}\vspace{-15pt}
where 
\vspace{-10pt}\begin{align}
\mathcal{D}=\big|\mathcal{L}_{\text{d}}h_{\text{d}}+\mathcal{L}_{B}\textstyle\sum_{i=1}^{N_{B}}h_{i}g_{i}e^{j\theta_{i}}+\mathcal{L}_{B}\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}\hat{g}_{\ell}\big|^{2}.\label{D1}
\end{align}
\vspace{-15pt}\begin{align}
\mathcal{I}_{k}=\big|\mathcal{L}_{\text{D}}^{(k)}h_{\text{D}}^{(k)}+\mathcal{L}_{B}^{(k)}\textstyle\sum_{i=1}^{N_{B}}h_{i}^{(k)}g_{i}e^{j\theta_{i}}+\mathcal{L}_{B}^{(k)}\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{(k)}\hat{g}_{\ell}\big|^{2}.
\end{align}

\vspace{-5pt}Considering the conditionally complex Gaussian RV, $x_{m,r}$, it can be stated that $|x_{m,r}|^{2}$ follows a conditional exponential distribution, and thus $z=\sum_{m=1}^{M}\left|x_{m,r}\right|^{2}$ follows a conditional central Chi-squared distribution with $2M$ degrees of freedom\cite{ROSS}. Therefore, using the cumulative distribution function of the Chi-squared distribution given in \cite[Eq.~(2.3-24)]{THz42}, the conditional probabilities, $\mathcal{P}_{c|0}\triangleq \mathrm{P_{r}}\left(\sum_{m=1}^{M}\left|x_{m,r}\right|^{2}>\gamma_{th}|\text{bit-0}\right)$ and $\mathcal{P}_{c|1}\triangleq \mathrm{P_{r}}\left(\sum_{m=1}^{M}\left|x_{m,r}\right|^{2}\leq \gamma_{th}|\text{bit-1}\right)$ are respectively written as 
\vspace{-10pt}\begin{align}
    \mathcal{P}_{c|0}=\frac{1}{\Gamma(M)}\Gamma\left(M,\frac{\gamma_{th}}{\sigma_{x,0}^{2}}\right)=\frac{1}{\Gamma(M)}\Gamma\left(M,\frac{\gamma_{th}}{\mathcal{D}\sigma_{0}^{2}+\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}}\right).\label{cb0}
\end{align}
\vspace{-10pt}\begin{align}
    \mathcal{P}_{c|1}=1-\frac{1}{\Gamma(M)}\Gamma\left(M,\frac{\gamma_{th}}{\sigma_{x,1}^{2}}\right)=1-\frac{1}{\Gamma(M)}\Gamma\left(M,\frac{\gamma_{th}}{\mathcal{D}\sigma_{1}^{2}+\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}}\right).\label{cb1}
\end{align}

The unconditional probabilities, $\mathcal{P}_{0}=\mathbb{E}[\mathcal{P}_{c|0}]$ and $\mathcal{P}_{1}=\mathbb{E}[\mathcal{P}_{c|1}]$, are obtained by taking the expectations of (\ref{cb0}) and (\ref{cb1}) with respect to the conditional variances, $\sigma_{x,0}^{2}$ and $\sigma_{x,1}^{2}$. Since the RVs $\sigma_{x,0}^{2}$ and $\sigma_{x,1}^{2}$ depend on a large number of desired and interference fading channels, random phases, and the random number of REs, deriving accurate expressions for the unconditional probabilities via conventional methods requires at least $(K+1)$-fold numerical integration, which is mathematically {challenging} and burdensome\cite{10269022}. Alternatively, by leveraging an MGF-based method proposed in \cite[Lemma 1]{6425522}, the unconditional probabilities can be obtained as 
\begin{align}
    \mathcal{P}_{0}&=1-\frac{1}{\Gamma(M)}\int_{0}^{\infty}\mathcal{S}^{\frac{M}{2}-1}J_{M}\left(2\sqrt{\mathcal{S}}\right)\mathcal{M}_{\sigma_{x,0}^{2}}\left(\mathcal{S}\right)\text{d}\mathcal{S},\label{P0}
\end{align}
\begin{align}
    \mathcal{P}_{1}&=\frac{1}{\Gamma(M)}\int_{0}^{\infty}\mathcal{S}^{\frac{M}{2}-1}J_{M}\left(2\sqrt{\mathcal{S}}\right)\mathcal{M}_{\sigma_{x,1}^{2}}\left(\mathcal{S}\right)\text{d}\mathcal{S},\label{P1}
\end{align}
where $\mathcal{M}_{\sigma_{x,\chi}^{2}}\left(\mathcal{S}\right)=\mathbb{E}\left[e^{\frac{-\mathcal{S}}{\gamma_{th}}\sigma_{x,\chi}^{2}}\right]$ $\chi\in\{0,1\}$ represents the MGF, which can be expressed as
\begin{align}
    \mathcal{M}_{\sigma_{x,\chi}^{2}}\left(\mathcal{S}\right)&=\mathbb{E}\left[e^{-\frac{\mathcal{S}}{\gamma_{th}}\left(\mathcal{D}\sigma_{\chi}^{2}+\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)}\right]\nonumber\\
    &=e^{-\frac{\mathcal{S}N_{0}}{\gamma_{th}}}\mathbb{E}\left[e^{-\frac{\mathcal{S}}{\gamma_{th}}\mathcal{D}\sigma_{\chi}^{2}}\right]\mathbb{E}\left[e^{-\frac{\mathcal{S}}{\gamma_{th}}\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}}\right]\nonumber\\
    &=e^{-\frac{\mathcal{S}N_{0}}{\gamma_{th}}}\mathcal{M}_{D,\chi}\left(\mathcal{S}\right)\textstyle\prod_{k=1}^{K}\mathcal{M}_{\mathcal{I}_{k}}\left(\mathcal{S}\right),\label{MGFmain}
\end{align}
where $\mathcal{M}_{D,\chi}\left(\mathcal{S}\right)=\mathbb{E}\left[e^{-\frac{\mathcal{S}}{\gamma_{th}}\mathcal{D}\sigma_{\chi}^{2}}\right]$ and $\mathcal{M}_{\mathcal{I}_{k}}\left(\mathcal{S}\right)=\mathbb{E}\left[e^{-\frac{\mathcal{S}}{\gamma_{th}}P_{k}\mathcal{I}_{k}}\right]$ are the MGFs of $\mathcal{D}$ and $\mathcal{I}_{k}$.  

To achieve ideal beamforming for the desired signals, based on the availability of CSI at the RIS, the phase shifts applied by $N_{B}$ REs, $\theta_{i}$, should be {adjusted} to align with the phases of the fading channels, such that $\theta_{i}=\angle{h_{\text{D}}}-(\angle h_{i}+ \angle g_{i})$\cite{9440664}. However, in practice the RIS REs are equipped with discrete phase shifters which are only able to apply quantized phase shifts from the set of uniformly quantized phases, $\{0, 2\pi/Q,\dots,2\pi(Q-1)/Q\}$, where $Q=2^b$ is the quantization level and $b$ is the number of quantization bits\cite{10047976,10328394}. Therefore, the desired signals are reflected towards the Rx with phase shift quantization errors denoted as $\phi_{i}$, which are uniformly distributed in the interval of $[-\pi/Q,\pi/Q]$\cite{10047976,10328394}. In light of the above, $\mathcal{D}$ given in (\ref{D1}) can be rewritten as
\begin{align}
\mathcal{D}=\left|\mathcal{L}_{\text{d}}|h_{\text{d}}|+\mathcal{L}_{B}\textstyle\sum_{i=1}^{N_{B}}|h_{i}||g_{i}|e^{j\phi_{i}}+\mathcal{L}_{B}\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}\hat{g}_{\ell}\right|^{2}.\label{Dp}
\end{align}

Since $\mathcal{D}$ involves the sums of positive RVs, by virtue of \cite{10328394,10057425,10316584}, it can be accurately modelled by {the} gamma distribution, where its MGF is expressed as\cite[Eq.~(27)]{10328394}
\begin{align}
    \mathcal{M}_{D,\chi}\left(\mathcal{S}\right)=\left(1+\frac{\sigma_{\chi}^{2}\mathcal{S}\sigma_{\mathcal{D}}^{2}}{\gamma_{th}\mu_{\mathcal{D}} }\right)^{-\frac{\mu_{\mathcal{D}}^{2}}{\sigma_{\mathcal{D}}^{2}}},\label{MGFD}
\end{align}
where $\mu_{\mathcal{D}}$ and $\sigma_{\mathcal{D}}^{2}$ are the mean and variance of $\mathcal{D}$, {which can be respectively} expressed as
\begin{align}
\mu_{\mathcal{D}}=\mathbb{V}\left[\mathcal{D}_{\text{R}}\right]+\mathbb{V}\left[\mathcal{D}_{\text{I}}\right]+\mathbb{E}^{2}\left[\mathcal{D}_{\text{R}}\right],\label{MEAND}
\end{align}
\begin{align}
    \sigma_{\mathcal{D}}^{2}=2\mathbb{V}\left[\mathcal{D}_{\text{R}}\right](\mathbb{V}\left[\mathcal{D}_{\text{R}}\right]+2\mathbb{E}^{2}\left[\mathcal{D}_{\text{R}}\right])+2\mathbb{V}^{2}\left[\mathcal{D}_{\text{I}}\right],\label{VARD}
\end{align}
where
\vspace{-10pt}\begin{align}
\mathbb{E}\left[\mathcal{D}_{\text{R}}\right]=\frac{\mathcal{L}_{\text{d}}\sqrt{\pi}}{2}L_{\frac{1}{2}}\left(-\mu_{\text{d}}^{2}\right)+\frac{\mathcal{L}_{B}N_{2}{\mathcal{P}_{s}^{\zeta}}Q}{4}\sin\left(\frac{\pi}{Q}\right),
\end{align}
\begin{align}
\mathbb{V}\left[\mathcal{D}_{\text{R}}\right]=&\mathcal{L}_{\text{d}}^{2}\left[L_{1}\left(-\mu_{\text{d}}^{2}\right)-\frac{\pi}{4}L_{\frac{1}{2}}^{2}\left(-\mu_{\text{d}}^{2}\right)\right]+\mathcal{L}_{B}^{2}N_{2}{\mathcal{P}_{s}^{\zeta}}\left[\frac{1}{2}+\frac{Q}{4\pi}\sin\left(\frac{2\pi}{Q}\right)-{\mathcal{P}_{s}^{\zeta}}\frac{Q^{2}}{16}\sin^{2}\left(\frac{\pi}{Q}\right)\right]\nonumber\\
&+\frac{\mathcal{L}_{B}^{2}N_{2}(1-{\mathcal{P}_{s}^{\zeta}})}{4},
\end{align}
\begin{align}
\mathbb{V}\left[\mathcal{D}_{\text{I}}\right]=\mathcal{L}_{B}^{2}N_{2}{\mathcal{P}_{s}^{\zeta}}\left[\frac{1}{2}-\frac{Q}{4\pi}\sin\left(\frac{2\pi}{Q}\right)\right]+\frac{\mathcal{L}_{B}^{2}N_{2}(1-{\mathcal{P}_{s}^{\zeta}})}{4},
\end{align}
\begin{IEEEproof}
Please refer to Appendix A. 
\end{IEEEproof}

On the other hand, since the CSI for the interference channels through the $N_{B}$ REs is not available, the phase shifts for the interference signals are assumed to follow {the} uniform distribution as $\theta_{i}\sim U(0,2\pi)$, which leads to the random reflection of the interference signals\cite{9440664,10047976}. Let $\mathcal{I}_{k}\triangleq\left|\mathcal{F}_{k}\right|^{2}$ with $\mathcal{F}_{k}=\mathcal{L}_{\text{D}}^{(k)}h_{\text{D}}^{(k)}+\mathcal{L}_{B}^{(k)}\sum_{i=1}^{N_{B}}h_{i}^{(k)}g_{i}e^{j\theta_{i}}+\mathcal{L}_{B}^{(k)}\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{(k)}\hat{g}_{\ell}$, and thus for a practically large number of REs, $\mathcal{F}_{k}$ converges to a complex Gaussian RV as $\mathcal{F}_{k}\sim\mathcal{CN}\left(0,\sigma_{\mathcal{F}_{k}}^{2}\right)$, where by using \cite{9440664} and applying the steps similar to those in Appendix A, $\sigma_{\mathcal{F}_{k}}^{2}=\mathbb{V}\left[\mathcal{F}_{k}\right]$ is obtained as
\begin{align}
\sigma_{\mathcal{F}_{k}}^{2}&=\mathbb{V}\left[\mathcal{L}_{\text{D}}^{(k)}h_{\text{D}}^{(k)}\right]+\mathbb{V}\left[\mathcal{L}_{B}^{(k)}\textstyle\sum_{i=1}^{N_{B}}h_{i}^{(k)}g_{i}e^{j\theta_{i}}\right]+\mathbb{V}\left[\mathcal{L}_{B}^{(k)}\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{(k)}\hat{g}_{\ell}\right]=(\mathcal{L}_{\text{D}}^{(k)})^{2}+(\mathcal{L}_{B}^{(k)})^{2}N_{2}.\label{SIGFN}
\end{align}

Therefore, $\mathcal{I}_{k}\triangleq\left|\mathcal{F}_{k}\right|^{2}$ follows the exponential distribution, where its MGF is written as
\begin{align}
    \mathcal{M}_{\mathcal{I}_{k}}\left(\mathcal{S}\right)=\frac{1}{1+\frac{\mathcal{S}}{\gamma_{th}}P_{k}\sigma_{\mathcal{F}_{k}}^{2}}.\label{MGFI}
\end{align}

By substituting (\ref{MGFD}) and (\ref{MGFI}) into (\ref{MGFmain}), and then by substituting (\ref{MGFmain}) into (\ref{P0}) and (\ref{P1}), $\mathcal{P}_{0}$ and $\mathcal{P}_{1}$ are obtained. We then substitute them into (\ref{Pbr}) to find the BER in the $r$-th repetition as 
\begin{align}
     \mathcal{P}_{b}=&\frac{1}{2}+\frac{1}{2\Gamma(M)}\int_{0}^{\infty}\mathcal{S}^{\frac{M}{2}-1}J_{M}\left(2\sqrt{\mathcal{S}}\right)e^{-\frac{\mathcal{S}N_{0}}{\gamma_{th}}}\prod_{k=1}^{K}\left(1+\frac{\mathcal{S}}{\gamma_{th}}P_{k}\sigma_{\mathcal{F}_{k}}^{2}\right)^{-1}\nonumber\\
     &\times \left[\left(1+\frac{\sigma_{1}^{2}\mathcal{S}\sigma_{\mathcal{D}}^{2}}{\gamma_{th}\mu_{\mathcal{D}} }\right)^{-\frac{\mu_{\mathcal{D}}^{2}}{\sigma_{\mathcal{D}}^{2}}}-\left(1+\frac{\sigma_{0}^{2}\mathcal{S}\sigma_{\mathcal{D}}^{2}}{\gamma_{th}\mu_{\mathcal{D}} }\right)^{-\frac{\mu_{\mathcal{D}}^{2}}{\sigma_{\mathcal{D}}^{2}}}\right]\text{d}\mathcal{S}.\label{PbrF}
\end{align}

Finally, by substituting (\ref{PbrF}) into (\ref{ABERsys}), the BER of the system with $\mathcal{R}$ repetitions is obtained. Furthermore, by exploiting \cite[Eq. (25.4.45)]{abram} and applying some algebraic manipulations, (\ref{PbrF}) can be approximated as
\begin{align}
    \mathcal{P}_{b}\approx &\frac{1}{2}+\frac{1}{2\Gamma(M)}\left(\frac{\gamma_{th}}{N_{0}}\right)^{\frac{M}{2}}\sum_{l=1}^{L}\omega_{l}\Omega_{l}^{\frac{M}{2}-1}J_{M}\left(2\sqrt{\frac{\Omega_{l}\gamma_{th}}{N_{0}}}\right)\prod_{k=1}^{K}\left(1+\frac{\Omega_{l}P_{k}\sigma_{\mathcal{F}_{k}}^{2}}{N_{0}}\right)^{-1}\nonumber\\
    &\times \left[\left(1+\frac{\sigma_{1}^{2}\Omega_{l}\sigma_{\mathcal{D}}^{2}}{N_{0}\mu_{\mathcal{D}} }\right)^{-\frac{\mu_{\mathcal{D}}^{2}}{\sigma_{\mathcal{D}}^{2}}}-\left(1+\frac{\sigma_{0}^{2}\Omega_{l}\sigma_{\mathcal{D}}^{2}}{N_{0}\mu_{\mathcal{D}} }\right)^{-\frac{\mu_{\mathcal{D}}^{2}}{\sigma_{\mathcal{D}}^{2}}}\right],
\end{align}
where $\Omega_{l}$ and $\omega_{l}$ are respectively the sample points and weights factors of the Laguerre orthogonal polynomial, tabulated in \cite[TABLE (25.9)]{abram}.  
\vspace{-10pt}\subsection{Lower-Bound BER Analysis}
In order to obtain a further simplified expression for the BER, we derive lower-bound expressions for the unconditional probabilities given in (\ref{P0}) and (\ref{P1}). Thus, first using the Jensen's inequality for MGFs, $\mathbb{E}\left[e^{zx}\right]\geq e^{z\mathbb{E}[x]}$\cite{THz42}, the MGF given in (\ref{MGFmain}) can be lower-bounded as
\begin{align}
    \mathcal{M}_{\sigma_{x,\chi}^{2}}\left(\mathcal{S}\right) &\geq e^{-\frac{\mathcal{S}N_{0}}{\gamma_{th}}}e^{-\frac{\mathcal{S}}{\gamma_{th}}\sigma_{\chi}^{2}\mathbb{E}\left[\mathcal{D}\right]}e^{-\frac{\mathcal{S}}{\gamma_{th}}\sum_{k=1}^{K}P_{k}\mathbb{E}\left[\mathcal{I}_{k}\right]}\nonumber\\
    &\geq e^{-\frac{\mathcal{S}}{\gamma_{th}}\left(\sigma_{\chi}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}\right)},\label{upMGF}
\end{align}
where $\mu_{\mathcal{D}}$ and $\sigma_{\mathcal{F}_{k}}^{2}$ are given in (\ref{MEAND}) and (\ref{SIGFN}), respectively. 

By substituting (\ref{upMGF}) into (\ref{P0}), a lower-bound on the probability, $\mathcal{P}_{0}$, can be expressed as 
\begin{align}
    \mathcal{P}_{0}\geq & 1-\frac{1}{\Gamma(M)}\int_{0}^{\infty}\mathcal{S}^{\frac{M}{2}-1}J_{M}\left(2\sqrt{\mathcal{S}}\right) e^{-\frac{\mathcal{S}}{\gamma_{th}}\left(\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}\right)}\text{d}\mathcal{S}.\label{up1}
\end{align}

By setting $\mathcal{Z}\triangleq\frac{\mathcal{S}}{\gamma_{th}}\left(\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}\right)$, (\ref{up1}) is equivalently written as
\vspace{-10pt}\begin{align}
    &\mathcal{P}_{0}\geq  1-\frac{1}{\Gamma(M)}\left(\frac{\gamma_{th}}{\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}}\right)^{\frac{M}{2}} \nonumber\\
    &\times\int_{0}^{\infty} \mathcal{Z}^{\frac{M}{2}-1} J_{M}\left(2\sqrt{\frac{\gamma_{th}}{\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}}\mathcal{Z}}\right) \text{d}\mathcal{Z}.\label{intup}
\end{align}

By applying \cite[Eq. (8.353.2)]{bk} and \cite[Eq. (8.356.3)]{bk}, the integral of (\ref{intup}) {can be} evaluated, and after some algebraic manipulations, {the lower-bound on $\mathcal{P}_{0}$} is obtained as 
\begin{align}
    \mathcal{P}_{0}\geq \frac{1}{\Gamma(M)} \Gamma\left(M,\frac{\gamma_{th}}{\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}}\right).\label{upp0}
\end{align}

By following the same steps used for (\ref{upp0}), a lower-bound expression for $\mathcal{P}_{1}$ is obtained as
\begin{align}
    \mathcal{P}_{1}\geq 1- \frac{1}{\Gamma(M)} \Gamma\left(M,\frac{\gamma_{th}}{\sigma_{1}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}}\right).\label{upp1}
\end{align}

By substituting (\ref{upp0}) and (\ref{upp1}) into (\ref{Pbr}), a lower-bound on the BER in the $r$-th repetition is obtained as
\vspace{-10pt}\begin{align}
    \mathcal{P}_{b}\geq \frac{1}{2}+\frac{\Gamma\left(M,\frac{\gamma_{th}}{\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}}\right)}{2\Gamma(M)} -\frac{\Gamma\left(M,\frac{\gamma_{th}}{\sigma_{1}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}}\right)}{2\Gamma(M)}. \label{lowfind}
\end{align}

Finally, by substituting (\ref{lowfind}) into (\ref{ABERsys}), the lower-bound BER with $\mathcal{R}$ repetitions is obtained. 
\vspace{-5pt}\subsection{Optimal Threshold Selection}
 {As explained in Sec. II, in the proposed system, bit-0 and bit-1 are encoded at the Tx using low-value and high-value resistors, respectively, which generate thermal noise signals with distinct energy levels. The Rx detects the transmitted bit by comparing the energy of the received signal to a decision threshold. If the threshold is poorly chosen, it may result in incorrect bit detection—such as interpreting bit-0 as bit-1 and vice versa—thereby significantly degrading the detection accuracy and overall system performance. Thus, proper selection of the threshold value, $\gamma_{th}$, is crucial for ensuring reliable bit detection and accurately evaluating the system’s effectiveness.} To determine the optimal threshold which minimizes the BER, we rewrite the BER using (\ref{Pbr}), (\ref{cb0}), and (\ref{cb1}) as
\begin{align}
    {\mathcal{P}_{b}=\frac{1}{2}+\frac{1}{2\Gamma(M)} \Gamma\left(M,\frac{\gamma_{th}}{\sigma_{x,0}^2}\right) - \frac{1}{2\Gamma(M)} \Gamma\left(M,\frac{\gamma_{th}}{\sigma_{x,1}^2}\right).}\label{BERTHRESHH}
\end{align}

{From (\ref{BERTHRESHH}), considering the terms involving the upper incomplete gamma functions and the condition $\sigma_{x,0}^2 < \sigma_{x,1}^2$, it can be observed that for small values of $\gamma_{th}$, the BER decreases because the term $\Gamma\left(M, \frac{\gamma_{th}}{\sigma_{x,0}^2}\right)$ dominates and decays faster. However, for large values of $\gamma_{th}$, the BER increases as $\Gamma\left(M, \frac{\gamma_{th}}{\sigma_{x,1}^2}\right)$ decays more slowly due to $\sigma_{x,0}^2 < \sigma_{x,1}^2$. This transition ensures the existence of a single minimum\footnote{{This behavior of the BER in relation to the threshold values is also confirmed via numerical results presented in Sec. \ref{SECREsu}.}}. Therefore, it is established that $\mathcal{P}_b$ is a unimodal function of $\gamma_{th}$ \cite{convex}. Furthermore, based on the Fermat's theorem, any critical point of a differentiable function occurs where its first derivative is zero \cite{abram}.} Thus, to obtain the optimal threshold, we need to take the derivative of $\mathcal{P}_b$ with respect to $\gamma_{th}$, and set it to zero, i.e., $\frac{\partial \mathcal{P}_b}{\partial \gamma_{th}} = 0$.

As a result, using (\ref{BERTHRESHH}) and $\frac{\partial \Gamma\left(a,bx\right)}{\partial x}=-b(bx)^{a-1}e^{-bx}$\cite[Eq. (8.356.4)]{bk}, we have   
\begin{align}
    \frac{\partial \mathcal{P}_{b}}{\partial \gamma_{th}}&=\frac{\partial }{\partial \gamma_{th}}\left[\frac{1}{2\Gamma(M)}\Gamma\left(M,\frac{\gamma_{th}}{\sigma_{x,0}^{2}}\right)+\frac{1}{2}-\frac{1}{2\Gamma(M)}\Gamma\left(M,\frac{\gamma_{th}}{\sigma_{x,1}^{2}}\right)\right]\nonumber\\
    &=-\frac{1}{2\Gamma(M)\gamma_{th}}\left(\frac{\gamma_{th}}{\sigma_{x,0}^{2}}\right)^{M}e^{-\frac{\gamma_{th}}{\sigma_{x,0}^{2}}}+\frac{1}{2\Gamma(M)\gamma_{th}}\left(\frac{\gamma_{th}}{\sigma_{x,1}^{2}}\right)^{M}e^{-\frac{\gamma_{th}}{\sigma_{x,1}^{2}}}=0.\label{dPb1}
\end{align}

By applying some algebraic manipulations, (\ref{dPb1}) can be rewritten as
\begin{align}
    \ln\left[\left(\frac{1}{\sigma_{x,0}^{2}}\right)^{M}e^{-\frac{\gamma_{th}}{\sigma_{x,0}^{2}}}\right]&=\ln\left[\left(\frac{1}{\sigma_{x,1}^{2}}\right)^{M}e^{-\frac{\gamma_{th}}{\sigma_{x,1}^{2}}}\right]\nonumber\\
    -M\ln\sigma_{x,0}^{2}-\frac{\gamma_{th}}{\sigma_{x,0}^{2}}&=-M\ln\sigma_{x,1}^{2}-\frac{\gamma_{th}}{\sigma_{x,1}^{2}}\nonumber\\
    \gamma_{th}&=\frac{M\sigma_{x,0}^{2}\sigma_{x,1}^{2}}{\sigma_{x,1}^{2}-\sigma_{x,0}^{2}}\ln\left(\frac{\sigma_{x,1}^{2}}{\sigma_{x,0}^{2}}\right).\label{optn1}
\end{align}

Since (\ref{optn1}) involves $\sigma_{x,0}^{2}$ and $\sigma_{x,1}^{2}$ which are the {sums} of different RVs, and thus taking the expectation of (\ref{optn1}) for obtaining the average threshold, where the same RVs appear in both the numerator and denominator, is mathematically complex and cumbersome. Alternatively, using the lower-bound BER expression given in (\ref{lowfind}), and following the same steps used for (\ref{optn1}), an {approximated} expression for threshold selection can be obtained as 
\begin{align}
    \gamma_{th}\approx&\frac{M\left(\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}\right)\left(\mathcal{C}\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}\right)}{\sigma_{0}^{2}\mu_{\mathcal{D}}(\mathcal{C}-1)}\nonumber\\
    &\times\ln\left(\frac{\mathcal{C}\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}}{\sigma_{0}^{2}\mu_{\mathcal{D}}+\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}}\right).\label{opttherap}
\end{align}
\begin{Remark}\label{REM2}From (\ref{opttherap}), it can be stated that the threshold selection depends on the number of REs capable of beamforming and blindly reflecting the signals, transmit power, and numbers of samples and interferers. 
\end{Remark}




\vspace{-20pt}\subsection{Mutual Information (MI)}\vspace{-5pt}
To gain further insights, we assess the MI between $s_{m,r}$ and $x_{m,r}$, which is expressed as
\vspace{-5pt}\begin{align}
    I\left(s_{m,r};x_{m,r}\right)=H\left(x_{m,r}\right)-H\left(x_{m,r}|s_{m,r}\right),\label{MI1}
\end{align}
where $H\left(x_{m,r}\right)$ and $H\left(x_{m,r}|s_{m,r}\right)$ are the marginal and conditional entropies, respectively. 

Since $s_{m,r}$ can be either bit-0 or bit-1 with equal probabilities, the received signal given in (\ref{rec1}) is a zero-mean complex Gaussian signal for both bit-0 and bit-1 with variances of $\sigma_{x,0}^{2}$ and $\sigma_{x,1}^{2}$, respectively, as given in (\ref{convar}). Therefore, the marginal entropy, $H\left(x_{m,r}\right)$, can be expressed as the average of the two marginal entropies for bit-0 and bit-1 as\cite{wu2014signal} 
\begin{align}
    H\left(x_{m,r}\right)&=\frac{1}{2}\Big[\mathbb{E}\left[\ln\left(\pi e \sigma_{x,0}^{2}\right)\right]+\mathbb{E}\left[\ln\left(\pi e \sigma_{x,1}^{2}\right)\right]\Big]\nonumber\\
    &=\frac{1}{2}\mathbb{E}\left[\ln\left(\pi e \left(\mathcal{D}\sigma_{0}^{2}+\displaystyle\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\right)\right]\nonumber\\
    & \ \ \  +\frac{1}{2}\mathbb{E}\left[\ln\left(\pi e \left(\mathcal{D}\sigma_{1}^{2}+\displaystyle\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\right)\right].\label{marg1}
\end{align}

The expectations in (\ref{marg1}) are with respect to the desired and interference channel gains along with the random numbers of REs, i.e., $\mathcal{D}$ and $\mathcal{I}_{k}$, where deriving their exact expectations are mathematically complex and {challenging}. However, using \cite[Eq. (17)]{NIPS2006_532b7cbe} and \cite[Sec. III-C]{10047976}, they can be accurately approximated via the Gaussian approximation based on the second-order Taylor expansion, i.e., $\mathbb{E}\left[\ln X\right]\approx \ln\mathbb{E}\left[X\right]-\frac{\mathbb{V}\left[X\right]}{2\mathbb{E}^{2}\left[X\right]}$. Therefore, the marginal entropy can be approximated as
\begin{align}
     H\left(x_{m,r}\right)\approx &\frac{1}{2}\ln\left(\pi e \mathbb{E}\left[\sigma_{x,0}^{2}\right]\right)-\frac{\mathbb{V}\left[\sigma_{x,0}^{2}\right]}{4\mathbb{E}^{2}\left[\sigma_{x,0}^{2}\right]} + \frac{1}{2}\ln\left(\pi e \mathbb{E}\left[\sigma_{x,1}^{2}\right]\right)-\frac{\mathbb{V}\left[\sigma_{x,1}^{2}\right]}{4\mathbb{E}^{2}\left[\sigma_{x,1}^{2}\right]},\label{marg2}
\end{align}
where $\sigma_{x,\chi}^{2}$, $\chi\in\{0,1\}$ is given in (\ref{convar}). 

In order to obtain (\ref{marg2}), {closed-form expressions for} the mean and variance, i.e., $\mathbb{E}\left[\sigma_{x,\chi}^{2}\right]$ and $\mathbb{V}\left[\sigma_{x,\chi}^{2}\right]$, {are required}. Therefore, using (\ref{convar}), we get
\begin{align} \mathbb{E}\left[\sigma_{x,\chi}^{2}\right]=\sigma_{\chi}^{2}\mathbb{E}\left[\mathcal{D}\right]+\textstyle\sum_{k=1}^{K}P_{k}\mathbb{E}\left[\mathcal{I}_{k}\right]+N_{0}=\sigma_{\chi}^{2}\mu_{\mathcal{D}}+\textstyle\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}, \ \ \chi\in\{0,1\},
\end{align}
\begin{align}
\mathbb{V}\left[\sigma_{x,\chi}^{2}\right]=\mathbb{V}\left[\sigma_{\chi}^{2}\mathcal{D}\right]+\textstyle\sum_{k=1}^{K}\mathbb{V}\left[P_{k}\mathcal{I}_{k}\right]+\mathbb{V}\left[N_{0}\right]=\left(\sigma_{\chi}^{2}\right)^{2}\sigma_{\mathcal{D}}^{2}+\textstyle\sum_{k=1}^{K}P_{k}^{2}\left(\sigma_{\mathcal{F}_{k}}^{2}\right)^2, 
\end{align}
where $\mu_{\mathcal{D}}$, $\sigma_{\mathcal{D}}^{2}$ and $\sigma_{\mathcal{F}_{k}}^{2}$ are given in (\ref{MEAND}), (\ref{VARD}), and (\ref{SIGFN}), respectively. 

For computing the conditional entropy, the received signal is conditioned on $s_{m,r}$, and thus the uncertainty is due to the interference and noise components. As a result, similar to (\ref{marg2}), the conditional entropy can be expressed as 
\begin{align}
    H\left(x_{m,r}|s_{m,r}\right)&=\mathbb{E}\left[\ln\left[\pi e \left(\textstyle\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\right]\right]\nonumber\\
    &\approx \ln\left[\pi e \ \mathbb{E}\left[\left(\textstyle\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\right]\right]-\frac{\mathbb{V}\left[\pi e \left(\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\right]}{2\mathbb{E}^{2}\left[\pi e \left(\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\right]}\nonumber\\
     &\approx \ln\left[\pi e \left(\textstyle\sum_{k=1}^{K}P_{k}\sigma_{\mathcal{F}_{k}}^{2}+N_{0}\right)\right]-\frac{\sum_{k=1}^{K}P_{k}^{2}\left(\sigma_{\mathcal{F}_{k}}^{2}\right)^2}{2\left(\textstyle\sum_{k=1}^{K}P_{k}\sigma_{\mathcal{F}_{k}}^{2}+N_{0}\right)^{2}}.\label{condentF}
\end{align}

By substituting (\ref{marg2}) and (\ref{condentF}) into (\ref{MI1}), and after some algebraic manipulations, an {approximated} expression for the MI is obtained as 
\begin{align}
    I\left(s_{m,r};x_{m,r}\right)\approx & \frac{1}{2}\ln\left[\left(1+\frac{\sigma_{0}^{2}\mu_{\mathcal{D}}}{\mathcal{A}}\right)\left(1+\frac{\sigma_{1}^{2}\mu_{\mathcal{D}}}{\mathcal{A}}\right)\right]+\frac{\sum_{k=1}^{K}P_{k}^{2}\left(\sigma_{\mathcal{F}_{k}}^{2}\right)^2}{2\mathcal{A}^{2}}\nonumber\\
    &-\frac{\left(\sigma_{0}^{2}\right)^{2}\sigma_{\mathcal{D}}^{2}+\sum_{k=1}^{K}P_{k}^{2}\left(\sigma_{\mathcal{F}_{k}}^{2}\right)^2}{4\left(\sigma_{0}^{2}\mu_{\mathcal{D}}+\mathcal{A}\right)^{2}}-\frac{\left(\sigma_{1}^{2}\right)^{2}\sigma_{\mathcal{D}}^{2}+\sum_{k=1}^{K}P_{k}^{2}\left(\sigma_{\mathcal{F}_{k}}^{2}\right)^2}{4\left(\sigma_{1}^{2}\mu_{\mathcal{D}}+\mathcal{A}\right)^{2}},\label{MIAPROX}
\end{align}
where $\mathcal{A}=\sum_{k=1}^{K}P_{k}  \sigma_{\mathcal{F}_{k}}^{2}+N_{0}$.


Moreover, the MI over $M$ samples can be approximated as $I(S,X)\approx M I\left(s_{m,r};x_{m,r}\right)$, where the samples of the received signal are considered to be IID, as described in Section \ref{SECII}. 
\vspace{-5pt}\subsection{{Energy Efficiency (EE)}}\vspace{-5pt}
{In order to further evaluate the system performance, using (\ref{MIAPROX}), the EE of the system in terms of bits per joule (bit/J) can be written as \cite{10677372}}
\begin{align}
    {EE=\frac{I\left(s_{m,r};x_{m,r}\right)}{\ln2 \ P_{\text{Tot}}},}\label{EE1}
\end{align}
{where $I\left(s_{m,r};x_{m,r}\right)$ is the MI given in (\ref{MIAPROX}), and $P_{\text{Tot}}=P_{\text{Tx}}+P_{\text{RIS}}+P_{\text{Rx}}$ is the total power consumption, such that $P_{\text{Tx}}$, $P_{\text{RIS}}=N_{2}\mathcal{E}+\mathcal{E}_{con}$ as given in (\ref{con}), and $P_{\text{Rx}}$ are respectively the power consumptions at the Tx, RIS, and Rx\cite{10677372}.} 

{As discussed in Sec. \ref{SECII}, the Tx in the thermal noise modulation-based system does not require external energy sources; instead, it operates by switching between unbiased resistors through a digital logic controller, which consumes an extremely low amount of power, approximately 1 $\mu$W \cite{basar2024kirchhoff}. Moreover, the considered zero-energy RIS also does not require dedicated energy sources, as it harvests the required energy from existing RF interference signals. Thus, considering the power consumption of the Rx and the digital logic controller at the Tx, the total net power consumption becomes $P_{\text{Tot}}=P_{\text{Tx}}+P_{\text{Rx}}$. }
\subsection{Asymptotic Analysis}
As discussed in Section \ref{SECII}, the interference signals are exploited through EH at the RIS to provide the required power for the REs and beamforming. To gain deeper insights and investigate whether these signals are always beneficial, we analyze the asymptotic behavior of {the} system in the high-interference regime, i.e., $\{K,P_{k}\}\to \infty$. Thus, {using (\ref{ECSRmain}) and (\ref{ECNL1}),} the asymptotic ECSR {under both LEH and NLEH models,} ${\mathcal{P}_{s}^{\zeta}}^{\infty} = \lim_{K\to\infty}{\mathcal{P}_{s}^{\zeta}}$ {where $\zeta\in\{\text{L},\text{NL}\}$}, can be written as
\begin{align}
    {\mathcal{P}_{s}^{\zeta}}^{\infty}=\lim_{K\to\infty}\mathrm{P_{r}}\left(\textstyle\sum_{k=1}^{K} P_{k}(d_{1}^{(k)})^{-a}\left|\textstyle\sum_{n=1}^{N_{1}}\tilde{h}_{n}^{(k)}e^{j\tilde{\theta}_{n}}\right|^{2}\geq \mathcal{T}^{\zeta}\right)=1, \label{asyeh}
\end{align}
{where according to (\ref{ECSRmain}) and (\ref{ECNL1}), $\mathcal{T}^{\text{L}}=\frac{N_{2}\mathcal{E}+\mathcal{E}_{con}}{\eta}$ and $\mathcal{T}^{\text{NL}}=\frac{\mathcal{A}_{3}^{2}\left(N_{2}\mathcal{E}+\mathcal{E}_{con}\right)}{\mathcal{A}_{1}\mathcal{A}_{3}-\mathcal{A}_{3}\left(N_{2}\mathcal{E}+\mathcal{E}_{con}\right)-\mathcal{A}_{2}}$, respectively.} 

Furthermore, by exploiting (\ref{Pbr}), (\ref{cb0}) and (\ref{cb1}), the asymptotic BER, $\mathcal{P}_{b}^{\infty}= \lim_{K\to\infty}\mathcal{P}_{b}$, can be expressed as 
\begin{align}
    \mathcal{P}_{b}^{\infty}&=\frac{1}{2}+\lim_{K\to\infty} \frac{1}{2\Gamma(M)}\Gamma\left(M,\frac{\gamma_{th}}{\mathcal{D}\sigma_{0}^{2}+\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}}\right)\nonumber\\
    &\ \ \ -\lim_{K\to\infty} \frac{1}{2\Gamma(M)}\Gamma\left(M,\frac{\gamma_{th}}{\mathcal{D}\sigma_{1}^{2}+\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}}\right)\nonumber\\
    &=\frac{1}{2}+\frac{1}{2\Gamma(M)}\Gamma\left(M,0\right)-\frac{1}{2\Gamma(M)}\Gamma\left(M,0\right)=\frac{1}{2}.\label{ASBER}
\end{align}

Using (\ref{MI1}), (\ref{marg1}), (\ref{condentF}) and $\ln(1)=0$, the asymptotic MI, $I^{\infty}\left(s_{m,r};x_{m,r}\right)=\lim_{K\to\infty}I\left(s_{m,r};x_{m,r}\right)$ is obtained as
\begin{align}
    I^{\infty}\left(s_{m,r};x_{m,r}\right)&=\lim_{K\to\infty} \left[H\left(x_{m,r}\right)-H\left(x_{m,r}|s_{m,r}\right)\right]\nonumber\\
    &=\lim_{K\to\infty} \mathbb{E}\left[\frac{1}{2}\ln\left(\pi^{2} e^{2} \left(\mathcal{D}\sigma_{0}^{2}+\textstyle\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\left(\mathcal{D}\sigma_{1}^{2}+\textstyle\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\right)\right.\nonumber\\
    & \left. \ \ \ \ -\ln\left(\pi e \left(\textstyle\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}\right)\right)\right]\nonumber\\
    &=\frac{1}{2}\lim_{K\to\infty}\mathbb{E}\left[\ln\left(1+\frac{\mathcal{D}\sigma_{0}^{2}}{\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}}\right)+\ln\left(1+\frac{\mathcal{D}\sigma_{1}^{2}}{\sum_{k=1}^{K}P_{k}\mathcal{I}_{k}+N_{0}}\right)\right]=0.\label{ASMI}
\end{align}

{Similarly, using (\ref{EE1}) and (\ref{ASMI}), the asymptotic EE, $EE^{\infty} = \lim_{K\to\infty}EE$, is obtained as}
\begin{align}
    {EE^{\infty} = \lim_{K\to\infty}\frac{I\left(s_{m,r};x_{m,r}\right)}{\ln2 \ (P_{\text{Tx}}+P_{\text{Rx}})}=\frac{I^{\infty}\left(s_{m,r};x_{m,r}\right)}{\ln2 \ (P_{\text{Tx}}+P_{\text{Rx}})}=0.}\label{ASEE}
\end{align}

It is noteworthy that the asymptotic expressions remain valid when the interference power approaches infinity, i.e., $P_{k} \to \infty$.
\begin{Remark}\label{REM3}According to (\ref{ASBER}), (\ref{ASMI}), and (\ref{ASEE}), the communication performance for {the case with} a very large number of interferers and high interference power is severely limited at the Rx. 
\end{Remark}
\section{Results and Discussion}\label{SECREsu}
\vspace{-10pt}We present numerical and simulation results to validate the accuracy of the derived expressions and assess the system performance under various conditions, using the following parameters: $\{d,d_{1},d_{2}\}=\{8,3,6\}$ m, $\{d_{1}^{(1)},d_{1}^{(2)},d_{1}^{(3)},d_{1}^{(4)}\}=\{12,14,18,20\}$ m, $\{d_{\text{D}}^{(1)},d_{\text{D}}^{(2)},d_{\text{D}}^{(3)},d_{\text{D}}^{(4)}\}=\{18,20,22,25\}$ m, $a=2$, $\mu_{\text{d}}=1$, $\mathcal{C}=15$, $\eta=0.9$, $\{\mathcal{E},\mathcal{E}_{con}\}=\{1,50\}$ mW \cite{10348506,10677372}, $b=2$ bits, $N_{0}=-100$ dBm, and $\gamma_{th}$ is set as (\ref{opttherap}), unless otherwise stated. The fading channels and the RIS phase shifts in the simulation results are set as shown in TABLE \ref{TAB2}.

{Figs. \ref{FigECSR}, \ref{Fig3} and \ref{Fig4}} respectively show the {impacts} of REs allocation on the ECSR, BER, and MI under both ideal and quantized RIS phase shifts with $N=200$, $K=\{2,4\}$, $\sigma_{0}^{2}=-10$ dBm, $P_{k}=20$ dBm, $M=15$, and $\mathcal{R}=5$. The close match between the theoretical and simulation results confirms the accuracy of the expressions given in (\ref{pofeh}), (\ref{PbrF}), and (\ref{MIAPROX}). As shown in Fig. \ref{FigECSR}, for a given number of REs allocated to EH, an increase in the number of interferers increases the ECSR, thereby enhancing the amount of harvested energy required for beamforming. For example, for $N_{1}=125$, an ECSR of ${\mathcal{P}_{s}^{\zeta}}=0.57$ is achieved when $K=2$, and ${\mathcal{P}_{s}^{\zeta}}\approx 1$ when $K=4$, which {confirms} Remark \ref{rem1}. Furthermore, increasing $N_{1}$ raises the ECSR, reaching ${\mathcal{P}_{s}^{\zeta}}=1$ at approximately $N_{1}\geq 125$ for $K=4$, as more REs for EH enable sufficient energy harvesting. In contrast, allocating a large number of REs to signal reflection does not always guarantee the optimal BER and MI. For example, with $K=4$ and $N_2 =N-N_1= 125$, the BER and MI are about $10^{-1}$ and $0.7$ nats, respectively, as shown in Figs. \ref{Fig3} and \ref{Fig4}. This results from fewer REs allocated to EH ($N_1 = 75$), leading to an ECSR of roughly $0.17$—insufficient energy for beamforming at the RIS. Consequently, on average, only $\mathbb{E}[N_B] = {\mathcal{P}_s^\zeta} N_2 \approx 21$ REs support beamforming, while the remaining $\mathbb{E}[N_b] = (1 - {\mathcal{P}_s^\zeta}) N_2 \approx 104$ REs perform blind reflection.

It is observed that increasing $N_{1}$ improves the BER and MI until the ECSR reaches its maximum. Specifically, for $K=4$, at approximately $\{N_{1}, N_{2}\} = \{125, 75\}$—resulting in a maximized ECSR of 1—the system achieves the minimum BER and maximum MI. This outcome {confirms that the use of Algorithm \ref{ALG1} yields the optimal allocation of RIS resources for EH and communication}. However, increasing $N_1$ beyond 125 deteriorates both the BER and MI. Although this maximizes the ECSR—ensuring sufficient energy for RIS beamforming—it reduces the number of REs for reflection ($N_2$), thereby weakening the received signal due to improper resource allocation. Moreover, comparisons of the BER and MI achieved under ideal and quantized phases with $b=2$ bits show the {severe} impacts of quantization errors, which are common in practical RIS setups equipped with cost-effective discrete phase shifters\cite{10328394}.
