Let's first express the complex Gaussian channels, $\hat{h}_{\ell}$ and $\hat{g}_{\ell}$, in terms of their real and imaginary components as $\hat{h}_{\ell}=\hat{h}_{\ell}^{\text{R}}+j\hat{h}_{\ell}^{\text{I}}$ and $\hat{g}_{\ell}=\hat{g}_{\ell}^{\text{R}}+j\hat{g}_{\ell}^{\text{I}}$, where $\{\hat{h}_{\ell}^{\text{R}},\hat{h}_{\ell}^{\text{I}},\hat{g}_{\ell}^{\text{R}},\hat{g}_{\ell}^{\text{I}}\}\sim\mathcal{N}\left(0,1/2\right)$. Thus, $\mathcal{D}$ given in (\ref{Dp}) can be written as $\mathcal{D}\triangleq\mathcal{D}_{\text{R}}^{2}+\mathcal{D}_{\text{I}}^{2}$, where $\mathcal{D}_{\text{R}}$ and $\mathcal{D}_{\text{I}}$ are expressed as
\begin{align}
&\mathcal{D}_{\text{R}}=\mathcal{L}_{\text{d}}|h_{\text{d}}|+\mathcal{L}_{B}\textstyle\sum_{i=1}^{N_{B}}|h_{i}||g_{i}|\cos\phi_{i}+\mathcal{L}_{B}\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}.\\
&\mathcal{D}_{\text{I}}=\mathcal{L}_{B}\textstyle\sum_{i=1}^{N_{B}}|h_{i}||g_{i}|\sin\phi_{i}+\mathcal{L}_{B}\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}.
\end{align}

Therefore, by exploiting \cite{10328394} and \cite{10047976}, the mean and variance of $\mathcal{D}$ can be expressed as 
\begin{align}
&\mu_{\mathcal{D}}=\mathbb{E}\left[\mathcal{D}_{\text{R}}^{2}\right]+\mathbb{E}\left[\mathcal{D}_{\text{I}}^{2}\right]=\mathbb{V}\left[\mathcal{D}_{\text{R}}\right]+\mathbb{V}\left[\mathcal{D}_{\text{I}}\right]+\mathbb{E}^{2}\left[\mathcal{D}_{\text{R}}\right]+\mathbb{E}^{2}\left[\mathcal{D}_{\text{I}}\right].\\
&\sigma_{\mathcal{D}}^{2}=\mathbb{V}\left[\mathcal{D}_{\text{R}}^{2}\right]+\mathbb{V}\left[\mathcal{D}_{\text{I}}^{2}\right]=2\mathbb{V}\left[\mathcal{D}_{\text{R}}\right](\mathbb{V}\left[\mathcal{D}_{\text{R}}\right]+2\mathbb{E}^{2}\left[\mathcal{D}_{\text{R}}\right])+2\mathbb{V}\left[\mathcal{D}_{\text{I}}\right](\mathbb{V}\left[\mathcal{D}_{\text{I}}\right]+2\mathbb{E}^{2}\left[\mathcal{D}_{\text{I}}\right]).
\end{align}

To find $\mu_{\mathcal{D}}$ and $\sigma_{\mathcal{D}}^{2}$, the mean and variance of $\mathcal{D}_{\text{R}}$ and $\mathcal{D}_{\text{I}}$ are required, which are written as
\begin{align}
&\mathbb{E}\left[\mathcal{D}_{\text{R}}\right]=\mathcal{L}_{\text{d}}\mathbb{E}\left[|h_{\text{d}}|\right]+\mathcal{L}_{B}\mathbb{E}\left[\mathcal{G}_{1}\right]+\mathcal{L}_{B}\mathbb{E}\left[\mathcal{G}_{2}\right],\\
&\mathbb{V}\left[\mathcal{D}_{\text{R}}\right]=\mathcal{L}_{\text{d}}^{2}\mathbb{V}\left[|h_{\text{d}}|\right]+\mathcal{L}_{B}^{2}\mathbb{V}\left[\mathcal{G}_{1}\right]+\mathcal{L}_{B}^{2}\mathbb{V}\left[\mathcal{G}_{2}\right],
\end{align}
\begin{align}
    &\mathbb{E}\left[\mathcal{D}_{\text{I}}\right]=\mathcal{L}_{B}\mathbb{E}\left[\mathcal{G}_{3}\right]+\mathcal{L}_{B}\mathbb{E}\left[\mathcal{G}_{4}\right],\\
&\mathbb{V}\left[\mathcal{D}_{\text{I}}\right]=\mathcal{L}_{B}^{2}\mathbb{V}\left[\mathcal{G}_{3}\right]+\mathcal{L}_{B}^{2}\mathbb{V}\left[\mathcal{G}_{4}\right],
\end{align}
where $\mathcal{G}_{1}\triangleq\sum_{i=1}^{N_{B}}A_{i}$ with $A_{i}=|h_{i}||g_{i}|\cos\phi_{i}$, $\mathcal{G}_{2}\triangleq\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}$, $\mathcal{G}_{3}\triangleq\sum_{i=1}^{N_{B}}B_{i}$ with $B_{i}=|h_{i}||g_{i}|\sin\phi_{i}$, and $\mathcal{G}_{4}\triangleq\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}$.

Since $h_{\text{d}}\sim\mathcal{CN}\left(\mu_{\text{d}},1\right)$ is a non-zero mean complex Gaussian RV, $|h_{\text{d}}|$ is a Rician RV with $\mathbb{E}\left[|h_{\text{D}}|\right]=\frac{\sqrt{\pi}}{2}L_{\frac{1}{2}}\left(-\mu_{\text{d}}^{2}\right)$ and $\mathbb{V}\left[|h_{\text{D}}|\right]=L_{1}\left(-\mu_{\text{d}}^{2}\right)-\frac{\pi}{4}L_{\frac{1}{2}}^{2}\left(-\mu_{\text{d}}^{2}\right)$ \cite{10047976}. Moreover, as the numbers of REs capable of beamforming and blindly reflecting the signals, $N_{B}$ and $N_{b}$, are binomial RVs with $\mathbb{E}[N_{B}]=N_{2}{\mathcal{P}_{s}^{\zeta}}$, $\mathbb{E}[N_{b}]=N_{2}(1-{\mathcal{P}_{s}^{\zeta}})$, and $\mathbb{V}[N_{B}]=\mathbb{V}[N_{b}]=N_{2}{\mathcal{P}_{s}^{\zeta}}(1-{\mathcal{P}_{s}^{\zeta}})$, the RVs $\{\mathcal{G}_{1},\mathcal{G}_{2},\mathcal{G}_{3},\mathcal{G}_{4}\}$ are compound RVs\cite{ROSS}. Thus, using \cite[Ch. 3]{ROSS}, we can write that
\begin{align}
    &\mathbb{E}\left[\mathcal{G}_{1}\right]=\mathbb{E}\left[\textstyle\sum_{i=1}^{N_{B}}A_{i}\right]=\mathbb{E}[N_{B}]\mathbb{E}[A_{i}]=N_{2}{\mathcal{P}_{s}^{\zeta}}\mathbb{E}[A_{i}],\\
 & \mathbb{V}\left[\mathcal{G}_{1}\right]=\mathbb{V}\left[\textstyle\sum_{i=1}^{N_{B}}A_{i}\right]=\mathbb{E}[N_{B}]\mathbb{V}[A_{i}]+\mathbb{V}[N_{B}]\mathbb{E}^{2}[A_{i}]=N_{2}{\mathcal{P}_{s}^{\zeta}}\mathbb{V}[A_{i}]+N_{2}{\mathcal{P}_{s}^{\zeta}}(1-{\mathcal{P}_{s}^{\zeta}})\mathbb{E}^{2}[A_{i}],
\end{align}
\vspace{-10pt}\begin{align}
   & \mathbb{E}\left[\mathcal{G}_{2}\right]=\mathbb{E}\left[\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}\right]=\mathbb{E}[N_{b}]\mathbb{E}\left[\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}\right]=N_{2}(1-{\mathcal{P}_{s}^{\zeta}})\mathbb{E}\left[\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}\right]=0,\\
    &\mathbb{V}\left[\mathcal{G}_{2}\right]=\mathbb{V}\left[\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}\right]=\mathbb{E}[N_{b}]\mathbb{V}\left[\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}\right]+\mathbb{V}[N_{b}]\mathbb{E}^{2}\left[\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}\right]=\frac{N_{2}(1-{\mathcal{P}_{s}^{\zeta}})}{4},
\end{align}
\begin{align}
    &\mathbb{E}\left[\mathcal{G}_{3}\right]=\mathbb{E}\left[\textstyle\sum_{i=1}^{N_{B}}B_{i}\right]=N_{2}{\mathcal{P}_{s}^{\zeta}}\mathbb{E}[B_{i}],\\
    &\mathbb{V}\left[\mathcal{G}_{3}\right]=\mathbb{V}\left[\textstyle\sum_{i=1}^{N_{B}}B_{i}\right]=N_{2}{\mathcal{P}_{s}^{\zeta}}\mathbb{V}[B_{i}]+N_{2}{\mathcal{P}_{s}^{\zeta}}(1-{\mathcal{P}_{s}^{\zeta}})\mathbb{E}^{2}[B_{i}],\\
   & \mathbb{E}\left[\mathcal{G}_{4}\right]=\mathbb{E}\left[\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}\right]=N_{2}(1-{\mathcal{P}_{s}^{\zeta}})\mathbb{E}\left[\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}\right]=0,\\   &\mathbb{V}\left[\mathcal{G}_{4}\right]=\mathbb{V}\left[\textstyle\sum_{\ell=1}^{N_{b}}\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}\right]=\mathbb{E}[N_{b}]\mathbb{V}\left[\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}\right]+\mathbb{V}[N_{b}]\mathbb{E}^{2}\left[\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}\right]=\frac{N_{2}(1-{\mathcal{P}_{s}^{\zeta}})}{4},
\end{align}
where $\mathbb{E}\left[\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}\right]=\mathbb{E}\left[\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}\right]=0$, $\mathbb{V}\left[\hat{h}_{\ell}^{\text{R}}\hat{g}_{\ell}^{\text{R}}\right]=\mathbb{V}\left[\hat{h}_{\ell}^{\text{I}}\hat{g}_{\ell}^{\text{I}}\right]=1/4$, and the mean and variance of $A_{i}$ and $B_{i}$ are readily available in different studies of RISs, which are written as $\mathbb{E}\left[A_{i}\right]=Q\sin\left(\pi/Q\right)/4$, $\mathbb{E}\left[B_{i}\right]=0$, $\mathbb{V}\left[A_{i}\right]=1/2+Q\sin\left(2\pi/Q\right)/(4\pi)-Q^{2}\sin^{2}\left(\pi/Q\right)/16$ and $\mathbb{V}\left[B_{i}\right]=1/2-Q\sin\left(2\pi/Q\right)/(4\pi)$\cite{10328394,10047976}. 

Finally, by substituting the corresponding mean and variance terms, and after some algebraic manipulations, $\mu_{\mathcal{D}}$ and $\sigma_{\mathcal{D}}^{2}$ given in (\ref{MEAND}) and (\ref{VARD}) are obtained. $\hfill\blacksquare$ 
