\section{Methods}
\label{sec:methods} % 4 columns (~fig permutation, ~fig pipeline)
To break the data dependencies of the block-sequential algorithms presented in Section~\ref{sec:background-sequential-methods}, we introduce a permutation scheme extending the work of Petersen et al.~\cite{petersen_hybrid_2009}.
Applying this permutation to the input matrix allows us to reorder the block operations, exposing parallel sections in the forward and backward passes.
Overall, the algorithm we propose splits the input matrix $A$ into $P$ partitions and comprises three phases: (1) \emph{PPOBTAF} computes \emph{partial} block-Cholesky factorizations for all partitions in parallel.
(2) \emph{POBTARSSI} gathers the partial factorizations' blocks lying in the boundaries among the partitions to construct a smaller BTA matrix called \emph{reduced system} and labeled $A_r$. The method then computes the reduced system's selected inverse by sequentially applying the \emph{POBTAF} and \emph{POBTASI} methods. The selected inverse of the reduced-system, $X_r$, consists of the true inverse boundary blocks of each partition.
(3) \emph{PPOBTASI} uses the latter blocks to execute the backward pass of Algorithm~\ref{alg:pobtasi} for all partitions in parallel, which delivers selected entries of $A^{-1}$.

% The algorithm we propose comprises three phases and can be defined as a divide-and-conquer approach.
% The first and last phases are embarrassingly parallel, while the middle step consists of the assembly through communication and inversion of a reduced system with the $d\_pobtarssi$) routine.
% To break the complete sequential dependencies\footnote{During the Cholesky factorization, it is possible to compute the lower diagonal block $A_{i+1,i}$ and arrowhead block $A_{n,i}$ in parallel. However, this strategy does not present any advantage as the computations are memory-bound and streaming both blocks to the GPU for parallel processing does not provide any speed-up} of the block algorithms presented in Section~\ref{sec:background-sequential-methods} and expose parallelism in the block Cholesky-factorization and selected inversion procedures, new computational schemes must be introduced, namely permutation and re-ordering of the matrix.
% We present a permutation scheme, extending the work of Petersen et al.~\cite{petersen_hybrid_2009}, that enables embarrassingly parallel operations during the factorization and selected inversion of BTA matrices.

%   - Control flow and processes slicing (0.25)
\subsection{Partitioning and permutation schemes}
\label{sec:partitioning-pemutation}
We partition the BTA matrix into $P$ disjoint arrow shapes, each consisting (approximately) of $n_p = n / P$ block rows and columns.
% A process $p$ is assigned the slices $[p*n_{p}:(p+1)*n_{p}]$ of the main diagonal, lower diagonal, and arrowhead blocks.
The coordinates of the blocks belonging to a partition $p$ are $A_{i, i}$ (main block diagonal), $A_{i+1,i}$ (lower block diagonal), and $A_{n, i}$ (arrowhead) for $i \in \{pn_p .. (p+1)n_p-1\}$.
We distinguish between the first (top) partition $p_0$, which owns block $A_{0, 0}$, and the rest, \emph{middle} partitions.
All partitions share the arrow tip block $A_{n, n}$ and can then be re-interpreted as a BTA matrix with $n=n_p$.
% An example BTA matrix, with $n=11$, split into three partitions is shown in Fig.~\ref{fig:pipeline}.a).
An example BTA matrix, with $n=11$, split into three partitions is shown, alongside its permutation matrix, in Fig.~\ref{fig:permutation_pobta}.

%
% The first process operates on its partition using the sequential $pobtaf$ algorithm, while the other processes (referred to as \emph{middle processes}) first permute their local partition.

%   - Permutation (~fig permutation) (0.5)
% We distinguish between the first (top) partition $p_0$, which owns block $A_{0, 0}$, and the rest, \emph{middle} partitions.
% Our permutation scheme applies only to the latter.
% Figure~\ref{fig:permutation_pobta}.a) shows a middle partition with $n_p=11$, re-interpreted as an individual BTA matrix $A$.
% The corresponding permutation matrix $P$ is depicted in Fig.~\ref{fig:permutation_pobta}.b), while Fig.~\ref{fig:permutation_pobta}.c) presents the resulting permuted matrix $PAP^T$.
% Figure~\ref{fig:permutation_pobta} shows the permutation matrix applied to the partitioned BTA matrix.
% The corresponding permutation matrix $P$ is depicted in Fig.~\ref{fig:permutation_pobta}.b), while Fig.~\ref{fig:permutation_pobta}.c) presents the resulting permuted matrix $PAP^T$.
% The permutation applied to the middle partitions is presented in Fig.~\ref{fig:permutation_pobta}.
% It connects the middle partitions upward (to the previous partition) and downward (to the following partition) at the end of the decomposition.
The matrix $P$ can be defined as a \emph{shifting} permutation, re-organizing the blocks inside the sparsity structure.
In practice, applying this permutation matrix to a BTA partition shifts its blocks up and left along the diagonal.
The first diagonal block belonging to this partition is shifted around to the last position.
For example, in Fig.~\ref{fig:permutation_pobta}, the first diagonal block of partition 1 is $A_{3,3}$.
After applying the permutation, the first diagonal block is $A_{4,4}$, while $A_{3,3}$ is shifted around to the last position.
This permutation is necessary to factorize the middle partitions toward their two neighboring partitions, above and below, allowing for further completion of the partial factorization during the \emph{POBTARSSI} step.
The blocks connecting the partitions, represented in dark gray color in Fig.~\ref{fig:permutation_pobta}, remain untouched during the permutation.
These blocks are latter going to be used to connect the partitions together when assembling the reduced system at the end of the parallel factorization phase.
The middle partitions' permutation induces fill-in during the partial block-Cholesky factorization, annotated with red hatches in the permuted matrix in Fig.~\ref{fig:permutation_pobta}.
% The fill-in induced in the Cholesky factorization because of the permutation is shown in red hatches.
Due to this fill-in, the PPOBTAF and PPOBTASI methods execute more block operations for the middle partitions than for the first one.
Load balancing issues are further discussed in Section~\ref{sec:theoretical_analysis}.
We note that the permutation is never materialized but remains implicit, i.e., the blocks of $A$ and $L$ are not reordered in memory.

\begin{algorithm}[t]
\small
\caption{\emph{PPOBTAF:} Parallel block-Cholesky factorization of a BTA matrix.}
\label{alg:ppobtaf}
\begin{algorithmic}[1]
    \Require $A_{p_i}, i \in \{0, ..., P-1\}$: $P$ partitions of $A$.
    \Ensure $L_{p_i}, i \in \{0, ..., P-1\}$: $P$ partitions of $L$.
    \Ensure $B_{p_i}, i \in \{1, ..., P-1\}$: $P-1$ fill-in partitions.
    % \ForAll{$i=0; i < P; i{++}$}
    \ForAll{$i \in \{0, ..., P-1\}$}
        \If{$i == 0$}
            \State $(L_{p_0}, U_{p_0}) \gets \text{PARTIAL\_POBTAF}(A_{p_0})$
        \Else
            \State $(L_{p_i}, B_{p_i}, U_{p_i}) \gets\text{PERMUTED\_POBTAF}(A_{p_i})$
        \EndIf
    \EndFor
    \State $L_{n,n} \gets A_{n,n} + \sum_{i = 0}^{P-1} U_{p_i}$
\end{algorithmic}
\end{algorithm}
\begin{algorithm}[t]
\small
\caption{\emph{PERMUTED\_POBTAF:} Block-sequential partial block-Cholesky factorization of a middle BTA partition. Differences compared to POBTAF are highlighted in red.}
\label{alg:permuted_pobtaf}
\begin{algorithmic}[1]
    \Require $A$: Middle partition with $n_p$ main diagonal blocks.
    \Ensure $L$: Middle lower-triangular factor partition.
    \Ensure $B$: Permutation-induced fill-in.
    \Ensure $U_{tip}$: Partial arrow tip update.
    \State \textcolor{red}{$B_1 = A_{1,0}^{\dagger}$, $U_{tip} = 0$}
    \For{$i = 1; i < n_p-1; i{++}$}
        \State $L_{i, i} \gets \text{POTRF}(A_{i, i})$
        \State $L_{i+1, i} \gets \text{TRSM}(L_{i, i}, A_{i+1, i})$
        \State $L_{n_p, i} \gets \text{TRSM}(L_{i, i}, A_{n_p, i})$
        \State \textcolor{red}{$B_{i} \gets \text{TRSM}(L_{i, i}, B_{i})$}
        \State $A_{i+1, i+1} \gets A_{i+1, i+1} - L_{i+1, i}\times L_{i+1, i}^{\dagger}$
        \State $A_{n_p, i+1} \gets A_{n_p, i+1} - L_{n_p, i}\times L_{i+1, i}^{\dagger}$
        \State \textcolor{red}{$U_{tip} \gets U_{tip} - L_{n_p, i}\times L_{n_p, i}^{\dagger}$}
        \State \textcolor{red}{$A_{0, 0} \gets A_{0, 0} - B_{i}\times B_{i}^{\dagger}$}
        \State \textcolor{red}{$B_{i+1} \gets - B_{i}\times L_{i+1, i}^{\dagger}$}
        \State \textcolor{red}{$A_{n_p, 0} \gets A_{n_p, 0} - L_{n_p, i}\times B_{i}^{\dagger}$}
    \EndFor
    % \State \textcolor{red}{$A_{n_p,n_p} \gets A_{n_p,n_p} + \sum_{i = 0}^{p} U_{i}$}
\end{algorithmic}
\end{algorithm}

%   - Algorithm listing (~permuted Cholesky) (0.75)
% \subsection{Parallel partial block-Cholesky factorization of BTA matrices}
\subsection{Parallel partial BTA block-Cholesky factorization}
\label{sec:ppobtaf}

The first step in our parallel selected-inversion algorithm is to produce a partial block-Cholesky factorization of the initial BTA matrix.
To that end, we split the input into $P$ partitions using the scheme presented in Section~\ref{sec:partitioning-pemutation}, one top partition, and $P-1$ middle partitions.
The factorizations' computations are independent and, therefore, we can employ $P$ processes in parallel, as shown in Algorithm~\ref{alg:ppobtaf}.
We use different block-sequential algorithms for the top (\emph{PARTIAL\_POBTAF}) and middle partitions  (\emph{PERMUTED\_POBTAF}).
Both routines are variations of POBTAF, specifically lines 1--8.
The main difference is that, instead of updating the arrow tip block at each step, the update is accumulated in a buffer $U_{tip}$.
At the end of the decomposition, the buffers from all partitions are added together.
In addition to the normal operations arising in the partial factorization, the permuted factorization needs to compute extra blocks during the factorization.
After applying the permutation scheme, the lower (resp. upper) blocks connecting the first diagonal block of the partition to the next one are shifted at the extremity of the partition.
For example, in Fig.~\ref{fig:permutation_pobta} and after application of the permutation matrix, the block $A_{4,3}$ (resp. $A_{3,4}$) that was initially within the BTA pattern is shifted outside of it, leading to the fill-in hatched in red during the factorization phase.
These additional computations are performed in Algorithm~\ref{alg:permuted_pobtaf} and Algorithm~\ref{alg:_permuted_pobtasi} using the buffer $B_{i}$.
The differences compared to POBTAF are highlighted in red.
% At the end of the decomposition, all buffers from all partitions are added together; the resulting update is then applied to the tip of the arrow. The fill-in induced by the permutation results in the computation of extra $L$ factors, noted in Algorithm~\ref{alg:permuted_pobtaf} as $B$.
% The $permuted\_pobtaf$ algorithm performs the decomposition starting from the second block to the penultimate block of the partition.
% This allows for the later creation of a reduced system using the updated (but not factorized) first and last blocks of the middle partitions.
% In the following listing, the $trsm$ operations are right-sided (i.e., we solve the linear system from the right side).

\begin{algorithm}[t]
\small
\caption{\emph{PPOBTASI:} Parallel selected inversion of a BTA matrix, given its block-Cholesky factorization.}
\label{alg:ppobtasi}
\begin{algorithmic}[1]
    \Require $L_{p_i}, i \in \{0, ..., P-1\}$: $P$ partitions of $L$.
    \Require $B_{p_i}, i \in \{1, ..., P-1\}$: $P-1$ fill-in partitions.
    \Ensure $X_{p_i}, i \in \{0, ..., P-1\}$: $P$ partitions of $X$.
    % \ForAll{$i=0; i < P; i{++}$}
    \ForAll{$i \in \{0, ..., P-1\}$}
        \If{$i == 0$}
            \State $X_{p_0} \gets \text{PARTIAL\_POBTASI}(L_{p_0})$
        \Else
            \State $X_{p_i} \gets\text{PERMUTED\_POBTASI}(L_{p_i}, B_{p_i})$
        \EndIf
    \EndFor
\end{algorithmic}
\end{algorithm}
%   - Algorithm listing (~permuted SellInv) (0.75)
\begin{algorithm}[t]
\small
\caption{\emph{PERMUTED\_POBTASI:} Block-sequential selected inversion of a middle BTA partition, given its block-Cholesky decomposition. Differences compared to POBTASI are highlighted in red.}
\label{alg:_permuted_pobtasi}
\begin{algorithmic}[1]
    \Require $L$: Middle lower-triangular factor partition.
    \Require $B$: Permutation-induced fill-in.
    \Ensure $X$: Middle partition with $n_p$ main diagonal blocks.
    \For{$i = n_p-2; i > 0; i{--}$}
        \State $U_{i+1,i} \gets -X_{i+1,i+1}\times L_{i+1,i} - X_{n_p,i+1}^{\dagger}\times L_{n_p,i}$
        \State \textcolor{red}{$U_{i+1,i} \gets U_{i+1,i} - B_{i+1}^{\dagger}\times B_{i}$}
        \State $X_{i+1,i} \gets \text{TRSM}(L_{i,i}, U_{i+1,i})$
        \State \textcolor{red}{$V_{i} \gets -B_{i+1}\times L_{i+1,i} -X_{0,0}\times B_{i} - X_{n_p,0}^{\dagger}\times L_{n_p,i}$}
        \State \textcolor{red}{$B_{i} \gets \text{TRSM}(L_{i,i}, V_{i})$}
        \State $U_{n_p,i} \gets -X_{n_p,i+1}\times L_{i+1,i} -X_{n_p,n_p}\times L_{n_p,i}$
        \State \textcolor{red}{$U_{n_p,i} \gets U_{n_p,i} - X_{n,0}\times L_{0,i}$}
        \State $X_{n_p,i} \gets \text{TRSM}(L_{i,i}, U_{n_p,i})$
        \State $U_{i,i} \gets L_{i,i}^{-\dagger}\times -X_{i+1,i}^{\dagger}\times L_{i+1,i} -X_{n_p,i}^{\dagger}\times L_{n,i}$
        \State \textcolor{red}{$U_{i,i} \gets U_{i,i} - B_{i}^{\dagger}\times B_{i}$}
        \State $X_{i,i} \gets \text{TRSM}(L_{i,i}, U_{i,i})$
    \EndFor
\end{algorithmic}
\end{algorithm}

