\begin{algorithm}[hbt!]
\caption{Filtering via kernel density estimation}
\label{alg:kde}
\begin{algorithmic}
\STATE \textbf{Input:} A finite set of points $X\subset \mathbb{R}^d$
\STATE \textbf{Hyperparameters:} length scale $h$ in \eqref{eq:kde}, filtering threshold $\gamma\in (0,1)$
\STATE \textbf{Output:} A subset $\widetilde{X}$ of $X$ that contains points in ``high-density'' regions with threhold parameter $\gamma$
\vspace{.1in}
\STATE Compute the kernel density $\rho(x)$ in \eqref{eq:kde} for each $x\in X$
\STATE Define $\rho_* = \max\limits_{x\in X} \rho(x)$
\STATE Initialize $\widetilde{X}=\emptyset$
\FOR{$x$ in $X$}
    \IF{$\rho(x) > \gamma\rho_*$}
        \STATE $\widetilde{X}=\widetilde{X}\cup \{x\}$
        \hfill \COMMENT{add $x$ if density estimate at $x$ is sufficient high}
    \ENDIF
\ENDFOR
\RETURN Filtered data $\widetilde{X}$
\end{algorithmic}
\end{algorithm}



\begin{algorithm}[hbt!]
\caption{Filtering via $k$-nearest neighbors}
\label{alg:knn}
\begin{algorithmic}
\STATE \textbf{Input:} A finite set of points $X\subset \mathbb{R}^d$
\STATE \textbf{Hyperparameters:} number of nearest neighbors $k$ in $k$NN, filtering threshold $\gamma\in (0,1)$
\STATE \textbf{Output:} A subset $\widetilde{X}$ of $X$ that contains points in ``high-density'' regions based on the number of neighbors relative to a threshold parameter $\gamma$
\vspace{.1in}
\STATE Apply $k$-nearest neighbors algorithm to $X$ to obtain $k$ neighbors for each $x$, stored as $\mathcal{N}_x$
\FOR{$x$ in $X$}
    \STATE Compute the sum of squared distances to the neighbors: $\delta_x=\sum\limits_{z\in \mathcal{N}_x} \norm{x-z}^2$
\ENDFOR
\STATE Compute $\delta_*=\min\limits_{x\in X}\delta_x$
\FOR{$x$ in $X$}
    \IF{$\delta_x<\delta_*/\gamma$}
        \STATE $\widetilde{X}=\widetilde{X}\cup \{x\}$
        \hfill \COMMENT{add $x$ if the cluster size of $\mathcal{N}_x$ is sufficiently small}
    \ENDIF
\ENDFOR
\RETURN Filtered data $\widetilde{X}$
\end{algorithmic}
\end{algorithm}



\paragraph{Computational efficiency}
For a training dataset with $N$ points, evaluating the kernel density estimator \eqref{eq:kde} at \emph{one} point induces $O(N)$ computational complexity, thus leading to a total of $O(N^2)$ complexity for the evaluation at $N$ points.
Similarly, performing $k$-nearest neighbor search for $N$ points will also require $O(N^2)$ computational complexity.
Such a computational bottleneck is well-known \cite{nando2005fast,bishop2006book} and a variety of methods have been developed to reduce the complexity.
For example, tree-based algorithms \cite{gray2000nbody,gray2003nonparametric} and hierarchical matrix techniques \cite{fastgauss1991,yang2003IEEE,hack2015book,smash,HiDR} can be used to accelerate the non-local kernel computation in kernel density estimation.
For $k$NN, a large number of techniques and software packages have been developed to improve the computational efficiency, including tree based nearest neighbor search \cite{kdtree1984,gray2003nonparametric,kdtree2006}, approximate nearest neighbors \cite{knn1998optimal,knn2009app,knn2018app,annoy}, gradient descent based search \cite{NNdescent2011}, etc.
The computational complexity can usually be reduced to $O(N\ln N)$ or $O(N)$ using these techniques.
We remark that the focus of the manuscript is on singularity detection, and computational accelerations will be investigated in a future date.




\subsection{The full data-driven SSL algorithm for singularity detection}
\label{sub:SSLfull}
Using filtering (Section \ref{sub:filtering}) as the pretext task and MLE (Section \ref{sec:formulation}) as the downstream task, a self-supervised learning framework can be built for singularity detection with unlabeled mesh data.
The full self-supervised singularity detection algorithm is summarized in Algorithm \ref{alg:alg2}.
If the given data is Type II, then we merge all batches into to a single one that contains all points.
Note that for Type II data, Algorithm \ref{alg:alg1} applies different weights to different batches in order to mitigate input perturbation or label corruption. Compared to Algorithm \ref{alg:alg1}, the SSL approach in Algorithm \ref{alg:alg2} does not distinguish Type I and Type II data formats much since it processes a single set that contains all data points.
More importantly, Algorithm \ref{alg:alg2} uses filtering to directly remove ``noise'' in the data, which helps to address input perturbation or label corruption.
The benefit of using filtering as a pretext task is two-fold:
(1) it reduces ``noise'' in the raw data and helps to improve the accuracy of singularity detection;
(2) using a filtered subset $\widetilde{X}$ of the given data $X$ as training data reduces the computational cost when minimizing the loss function, since $\widetilde{X}$ has a smaller size than $X$.
Therefore, using the SSL framework with filtering improves both accuracy and efficiency for singularity detection compared to the baseline Algorithm \ref{alg:alg1}.


% \paragraph{\textbf{\emph{Remark}}}
\begin{remark}
\label{rm:AMR}
The performance of data-driven singularity detection depends on the quality of mesh data, which, if generated by adaptive mesh refinement, will rely on the a posteriori error estimator used for estimating the error and guiding the refinement (cf. \cite{ainsworthoden2000book,verf2013book}). Specifically, for PDEs with certain small-scale parameters, it is well-known that a \emph{non-robust} error estimator can possibly guide the mesh refinement towards regions where the function is smooth, generating excessive nodes \emph{away} from the singularity (cf. \cite{bernardi2000,localL2}). \emph{Robust} error estimators can avoid this issue and generate a good mesh refined towards the singularity \cite{bernardi2000,localL2,confusion}. Developing \emph{robust} a posteriori error estimators is crucial for resolving the solution singularity and the efficient numerical solution of challenging PDEs. Detailed study on this topic can be found in \cite{bernardi2000,verf1998reaction,verf2005confusion,ainsworth2011confusion,localL2,confusion}.
% In this case, high density regions indicated by the mesh data may not necessarily contain the singularity.

\end{remark}


\begin{algorithm}[hbt!]
\caption{Data-driven self-supervised singularity detection (\emph{with} filtering)}
\label{alg:alg2}
\begin{algorithmic}
\STATE \textbf{Input:} Type I data aggregate $X$ (nodes from a mesh) or Type II data batches $\XXi{0},\dots,\XXi{R}$ from $R$ steps of AMR
\STATE \textbf{Hyperparameters:} Basis functions $\phi_1,\phi_2,\dots$ in \eqref{eq:f}, filtering hyperparameters $\gamma$, $h$ or $k$
\STATE \textbf{Output:} A function $f$ that minimizes the loss $\widetilde{L}_1$ defined below
\IF{Input is Type II}
\STATE Define $X=\bigcup\limits_{i=1}^R \XXi{i}$
\ENDIF
\STATE Compute the filtered subset $\widetilde{X}$ by applying filtering to $X$ via Algorithm \ref{alg:kde} (with parameters $\gamma,h$) or Algorithm \ref{alg:knn} (with parameters $\gamma,k$)
\STATE Define the loss function 
$\widetilde{L}_1(\mathbf{c})=\sum\limits_{x\in \widetilde{X}} f(x)^2$
\text{with} $f$ \text{in} \eqref{eq:f}
\STATE Solve the constrained minimization 
$\mathbf{c}_*=\argmin\limits_{\norm{\mathbf{c}}=1} \widetilde{L}_1(\mathbf{c})$
in \eqref{eq:minL1} to obtain $\mathbf{c}_*$
\RETURN $f$ in the form \eqref{eq:f} with coefficients $\mathbf{c}_*$
\end{algorithmic}
\end{algorithm}






\section{Numerical experiments}
\label{sec:experiments}



In this section, we perform numerical experiments to investigate algorithms for singularity detection. 
In each experiment, the singularity set $\mathcal{S}$ is the set of polynomial roots in a two-dimensional rectangular domain $\Omega$ depending on the underlying problem. Polynomial ansatz is used in most experiments. For $(x,y)\in\mathbb{R}^2$, the general form of a polynomial with degree $n$ is given by
$$f(x,y) = \sum_{i=0}^n \sum_{j=0}^{n-i} c_{k}x^iy^j.$$
 The coefficient $c_{k}$ corresponding to the term $x^iy^j$ is indexed by:  
 \[
 k= i(n+2) -i(i+1)/2+j.
 \]
For example, when $n=2$, the polynomial expands as:
\begin{equation}
f(x,y) = c_0 + c_1y+ c_2y^2+c_3x+c_4xy+c_5x^2. \label{eq:polydegree2}
\end{equation}
Given the training data, the unknown polynomial coefficients will be calculated using the proposed singularity detection algorithm.
The choice of hyperparameters in each filtering method will be stated in the experiment. In particular, for KDE-based filtering, Silverman's rule \cite{silverman2018density} is used for the length scale parameter $h$ in all experiments, i.e.,
$h=\left[\frac{1}{4}N(d+2)\right]^{-\frac{1}{d+4}}$ for $N$ data points in $d$ dimensions.

% The given data may not generally align exactly with the singularity, leading to an inherent approximation error. However, if a vertex set does not sufficiently cover the singularity, the learned function can smooth over it and try to correctly identify the singularity shape.



Extensive experiments are conducted to investigate different aspects of the problem, and we give a brief overview as follows.
Example 1 applies the baseline Algorithm \ref{alg:alg1} to Type I and Type II data to demonstrate the possible pathological outcomes for singularity detection when using the raw data directly for training.
Example 2 illustrates the superior performance of the self-supervised singularity detection framework in Algorithm \ref{alg:alg2}, where filtering is used as a pretext task.
Example 3 considers singularity detection for various types of challenging singularities, including boundary layer, `X' shape, and concentric semicircles. Both KDE and $ k$NN-based filtering methods will be tested.
Example 4 presents singularity detection with Fourier basis functions to demonstrate the flexibility of the proposed framework.



\subsection{Example 1. Baseline Algorithm \ref{alg:alg1} (no filtering) for Type I and Type II data}
\label{exp:circle-type1-type2}

We first consider an example of the solution of the singularly-perturbed reaction-diffusion equation:
\begin{align}
-\varepsilon \Delta u + u &= g_1 \;\;\text{ in }\;\; \Omega\quad \text{with}\;\; \varepsilon=10^{-4}, \nonumber\\
u & = g_b \;\;\text{ on }\;\partial\Omega. 
\label{eq:reaction-difussion}
\end{align}
The exact solution is chosen as
$$u(x,y)= \tanh \left(\varepsilon^{-1/2} (x^2 + y ^2 - \frac{1}{4}))\right)-1.$$ 
% with the corresponding right-hand side and boundary condition.
This is a commonly used test problem in the adaptive mesh refinement and a posteriori error estimation literature (cf. \cite{caizhang2010,confusion}).
This solution captures a reaction-diffusion phenomenon with a localized steep transition influenced by the small parameter $\varepsilon$. The transition occurs at an interior singular layer (see Figure~\ref{fig:circle}) given by the equation below
\begin{equation}
    x^2+y^2=\frac{1}{4}.\label{eq:singularity-circle}
\end{equation}
For singularity detection, we choose $f$ to be a polynomial of degree two as in \eqref{eq:polydegree2}.



\paragraph{Datasets}
The dataset is generated by AMR using the robust hybrid estimator proposed in~\cite{confusion}. 
The initial mesh in AMR consists of $4\times 4$ congruent squares, each of which is partitioned into two triangles connecting bottom-left and top-right corners. After 44 refinement steps, we obtained a mesh containing $13664$ nodes in total. We denote this large array of nodes as $X_0$ and use much smaller subsets to construct the training data.
For Type I data format, four different training sets are used in this experiment:
\begin{itemize}
    \itemsep0in
    \item Figure \ref{fig:1a}: the first $200$ nodes in $X_0$;
    \item Figure \ref{fig:1b}: the first $300$ nodes in $X_0$;
    \item Figure \ref{fig:1c}: the subset of $X_0$ that contains the $200$th to the $300$th nodes;
    \item Figure \ref{fig:1d}: the first $2500$ nodes in $X_0$.
\end{itemize}
For Type II data format, we use the batches generated after $R=17$ AMR steps $\XXi{0},\XXi{1},\dots,\XXi{R}$, whose union contains $322$ nodes in total.
To study the performance of the baseline singularity detection in Algorithm \ref{alg:alg1}, three different choices of the variance parameter $\sigma_i^2$ for batch $\XXi{i}$ are considered.
\begin{equation}
\label{eq:weights}
\sigma_i^2 = 1, \quad \sigma_i^2 = \frac{1}{2} \cdot 2^{2(R-i)},\quad \sigma_i^2 = \frac{1}{2} \cdot 4^{2(R-i)}\quad (i=0,\dots,R).
\end{equation}
Note that in the second choice and the third choice, the weight $\frac{1}{2\sigma_i^2}$ in \eqref{eq:minL2} for the $i$-th batch increases exponentially with $i$.



