        \includegraphics[scale=\graphicsScale,page=2]{graphics/partitionWithSteinerPointsVSConformingWithHoles.pdf}&%
        \includegraphics[scale=\graphicsScale,page=4]{graphics/partitionWithSteinerPointsVSConformingWithHoles.pdf}&%
        \includegraphics[scale=\graphicsScale,page=2]{graphics/thinPolygonAndPixalation.pdf}&%
