    \includegraphics[scale=\graphicsScale,page=2]{graphics/MSOL_ex.pdf} &
    \includegraphics[scale=\graphicsScale,page=3]{graphics/MSOL_ex.pdf} &
    \includegraphics[scale=\graphicsScale,page=4]{graphics/MSOL_ex.pdf} \\
    (a) & (b) & (c) 
    \end{tabularx}
    \caption{%
    (a) A polygon $ P $ with its pixelation graph $G_P$. %
    (b) The radial graph $ R _ P $ contains the thin solid edges. %
    (c) One possible solution to the MSOL formula $ \formula $ for $ k=3$. %
    We only show parts of this solution: %
    Partition segments are dotted, bold, and red. Vertices in $ \Vver $ ($ \Vhor $) are bold hollow red circles (squares). Vertices in $ \pixelset_i^\hor$ are indicated by \raisebox{0.5pt}{\textcircled{\raisebox{-0.7pt}{$ i $}}}.
    }
