\section{Definitions}
We shortly review the notation for the scaling of functions:
\begin{itemize}
    \item Big-O notation $O(.)$: For a function $f(n)$, if there exists a constant $c$ and a specific input size $n_0$ such that $f(n) \leq c \cdot g(n)$ for all $n \geq n_0$, where $g(n)$ is a well-defined function, then we express it as $f(n) = O(g(n))$. This signifies the upper limit of how fast a function grows in respect to $g(n)$.
    \item Big-Omega notation $\Omega(.)$: For a function $f(n)$, if there exists a constant $c$ and a specific input size $n_0$ such that $f(n) \geq c \cdot g(n)$ for all $n \geq n_0$, where $g(n)$ is a well-defined function, then we express it as $f(n) = \Omega(g(n))$. This signifies the lower limit of how fast a function grows in respect to $g(n)$.
    \item Big-Theta notation $\Theta(.)$: For a function $f(n)$, if $f(n) = O(g(n))$ and if $f(n) = \Omega(g(n))$, where $g(n)$ is a well-defined function, then we express it as $f(n) = \Theta(g(n))$. This implies that the function grows with the same scaling as $g(n)$.
    \item Little-Omega notation $\omega(.)$: For a function $f(n)$, when for any constant $c>0$ there exist a specific input size $n_0$ such that $f(n) \geq c \cdot g(n)$ for all $n \geq n_0$, where $g(n)$ is a well-defined function, then we express it as $f(n) = \omega(g(n))$. This implies that the function grows strictly faster than $g(n)$.
    \item Little-o notation $o(.)$: For a function $f(n)$, when for any constant $c>0$ there exist a specific input size $n_0$ such that $f(n) \leq c \cdot g(n)$ for all $n \geq n_0$, where $g(n)$ is a well-defined function, then we express it as $f(n) = o(g(n))$. This signifies that the function grows strictly slower than $g(n)$.
    \item Negligible functions $\text{negl}(.)$:  Positive real-valued functions $\mu:\mathbb \mathbb{N} \to \mathbb R$ are negligible if and only if $\forall c \in \mathbb{N}$, $\exists n_0 \in \mathbb{N}$ such that $\forall n > n_0$, $\mu(n) < n^{-c}$. This means that the function decays faster than any inverse polynomial. Alternatively, one can write $o(1/\text{poly}(n))$ or $2^{-\omega(\log n)}$.

\end{itemize}

\section{Note on violation of monotonicity}\label{sec:monoton}
While $M_\alpha$ (and thus $\mathcal{W}_\alpha)$ for $\alpha\ge2$ is a magic monotone for pure states under Clifford operations that map pure states to pure states~\cite{leone2024stabilizer}, we note that $\mathcal{W}_\alpha$ for any $\alpha$ is not monotone under more general Clifford channels~\cite{haug2023stabilizer}.

Here, we note that a magic monotone such as log-free robustness of magic $\text{LR}(\rho)$ or the stabilizer fidelity $D_\text{F}(\rho)$ fulfil two conditions~\cite{veitch2014resource}: First, they must be zero if and only if the state is a mixture of stabilizer states $\rho_\text{C}$, i.e. $\text{LR}(\rho_\text{C})=0$. Second, they must be non-increasing under any Clifford channel $\Gamma_\text{C}$, i.e. $\text{LR}(\Gamma_\text{C}(\rho))\leq\text{LR}(\rho)$. Here, Clifford channels are any channel that can be implemented by Clifford unitaries, classical communication, classical randomness and measurements in the $z$-basis.


As an example, consider $\ket{\psi}=\cos(\pi/16)\ket{0}+\sin(\pi/16)\ket{1}$ and the mixed unital Clifford channel $\Gamma_\text{C}(\rho)=\frac{1}{2}\rho+\frac{1}{2}H_\text{d} \rho H_\text{d}$, where $H_\text{d}$ is the Hadamard gate. Here, we find that $\mathcal{W}_\alpha(\Gamma_\text{C}(\ket{\psi}))>\mathcal{W}_\alpha(\ket{\psi})$ for $1/2<\alpha<2.5$, i.e. $\mathcal{W}_\alpha$ violates monotonicity as it increases under $\Gamma_\text{C}$. Similar examples can be found for all $\alpha$. 

\section{Filtered magic witness} \label{sec:alt_witness}
We define the filtered magic witness as $\Tilde{\mathcal{W}}_\alpha$:
\begin{equation}\label{eq:filtered_witness}
    \Tilde{\mathcal{W}}_\alpha(\rho)= \frac{1}{1-\alpha}\ln \Tilde{A}_\alpha(\rho) + \frac{1-2\alpha}{1-\alpha}\ln \Tilde{A}_1(\rho)\,,
\end{equation}
where
\begin{equation}
\Tilde{A}_\alpha(\rho)=\frac{\sum_{P\in\Tilde{\mathcal{P}}_n} \vert\text{tr}(\rho P)\vert^{2\alpha}} {2^n - 1} \equiv \frac{2^nA_\alpha-1}{2^n-1} \,,
\end{equation}
where $\Tilde{\mathcal{P}}_n = \mathcal{P}_n/ \{ I\}$ and $A_1=\text{tr}(\rho^2)$. Note that $\Tilde{\mathcal{W}}_\alpha$ is not well-defined for the maximally mixed state $\rho=I/2^n$. The von Neumann limit $\alpha \to 1$ is given by
\begin{equation}
\Tilde{\mathcal{W}}_1(\rho)=-\sum_{P\in\Tilde{\mathcal{P}}_n} 
\frac{\text{tr}(\rho P)^2}{2^n\text{tr}(\rho^2)-1} \ln(\text{tr}(\rho P)^2)-2\ln \Tilde{A}_1(\rho)
\end{equation}
For pure states $\rho = \ket{\psi} \bra{\psi}$, $\Tilde{\mathcal{W}}_\alpha$ becomes the filtered SRE~\cite{turkeshi2023pauli}
\begin{equation} \label{eq:filtered_sre}
 \Tilde{\mathcal{W}}_\alpha(\ket{\psi})\equiv \Tilde{M}_\alpha(\ket{\psi})  =\frac{1}{1-\alpha}\ln(\frac{\sum_{P\in\Tilde{\mathcal{P}}_n} \bra{\psi}P\ket{\psi}^{2\alpha}} {2^n - 1})\,.
\end{equation}
Similarly to $\mathcal{W}_\alpha$, $\Tilde{\mathcal{W}}_\alpha$ is a witness of magic for mixed states for any $\alpha\geq1/2$: if $\Tilde{\mathcal{W}}_\alpha > 0$, $\rho$ is a nonstabilizer state. The proof goes analogously to $\mathcal{W}_\alpha$, by noting that 
\begin{equation}
    \Tilde{\mathcal{W}}_{1/2}(\rho) = 2 \ln \Tilde{\mathcal{D}}(\rho)\,, 
\end{equation}
where we define $\Tilde{\mathcal{D}}(\rho)$ as
\begin{equation}
\Tilde{\mathcal{D}}(\rho)=
\frac{\sum_{P\in\Tilde{\mathcal{P}}_n} \lvert \text{tr}(\rho P) \rvert} {2^n - 1} \equiv \frac{2^n \mathcal{D}(\rho)-1}{2^n-1} \,.
\end{equation}
Like the stabilizer norm, $\Tilde{\mathcal{D}}(\rho)$ is a witness of mixed-state magic as $\ln \Tilde{\mathcal{D}}(\rho) >0 $ guarantees that $\rho$ is a nonstabilizer state~\cite{howard2017robustness}. Note that the set of nonstabilizer states that can be detected by $\Tilde{\mathcal{D}}(\rho)$ and $\mathcal{D}(\rho)$ is the same since $\Tilde{\mathcal{D}}(\rho)>1$ if and only if $\mathcal{D}(\rho)>1$. Nevertheless, $\Tilde{\mathcal{D}}(\rho)$ provides a tighter lower bound to $\text{LR}(\rho)$ since $\Tilde{\mathcal{D}}(\rho) > \mathcal{D}(\rho)$ whenever $\Tilde{\mathcal{D}}(\rho)>1$.

We can then show by the hierarchy of R\'enyi entropies over the probability distribution $\Tilde{p}_\rho(P)=\text{tr}(\rho P)^2/(2^n\text{tr}(\rho^2)-1)$ for $P \neq I$ that
\begin{equation}
    2\ln \Tilde{\mathcal{D}}(\rho) \geq  \Tilde{\mathcal{W}}_\alpha(\rho) \quad (\alpha \geq 1/2)\,.
\end{equation}
It follows that the alternative magic witness also provides a lower bound on $\text{LR}(\rho)$ by
\begin{equation}
    2\text{LR}(\rho) \geq 2 \ln\Tilde{\mathcal{D}}(\rho)\geq \Tilde{\mathcal{W}}_\alpha(\rho) \quad (\alpha \geq 1/2)\,.
\end{equation}
Note that $\mathcal{W}_\alpha$ and $\Tilde{\mathcal{W}}_\alpha$ have the same asymptotic behavior for large $n$.

To illustrate the distinct behavior of $\mathcal{W}_\alpha$ and $\Tilde{\mathcal{W}}_\alpha$, we consider the single-qubit $T$ state $\ket{T} = (\ket{0} + e^{i \pi/4} \ket{1})/\sqrt{2}$ subjected to depolarizing noise $\rho_\mathrm{dp}
 = (1-p)\ket{T}\bra{T} + p I/2^n$ 
 with a probability $p$. This effectively rescales the expectation values of all Pauli strings $P \in \mathcal{P}/ \{ I\}$ by $(1-p)$. Note that, for single-qubit states, $\mathcal{D}(\rho)>1$ (and $\Tilde{\mathcal{D}}(\rho)>1$) is a necessary and sufficient condition of magic~\cite{rall2019simulation}. By direct calculation, we obtain
 \begin{equation}
     \mathcal{W}_\alpha = \frac{1}{1-\alpha}\ln (\frac{1+(1-p)^{2\alpha} 2^{1-\alpha}}{2}) + \frac{1-2\alpha}{1-\alpha}\ln(\frac{p^2-2p+2}{2})
 \end{equation}
 and
 \begin{equation}
     \Tilde{\mathcal{W}}_\alpha = \ln(2(1-p)^2).
 \end{equation}
 In particular, we find that the transition to a stabilizer state occurs at $p_c=1-1/\sqrt{2}$, where both $\mathcal{W}_{1/2}$ and $\Tilde{\mathcal{W}}_{1/2}$ change sign.
 Moreover, notice that $\Tilde{\mathcal{W}}_\alpha$ is independent of the R\'enyi index $\alpha$. This is a consequence of the fact that the distribution $\Tilde{p}_\rho(P)$ is flat for the $T$ state. This also implies that $\Tilde{\mathcal{W}}_\alpha$ obtains the same transition as $\Tilde{\mathcal{W}}_{1/2}$, thus successfully witnessing the magic at $p>p_c$. In contrast, $\mathcal{W}_\alpha$ for $\alpha>1/2$ has different transitions from $\mathcal{W}_{1/2}$. For example, we find that $\mathcal{W}_2$ changes sign at $p_{c,2}= 0.1565... < p_c$. Thus, $\mathcal{W}_2$ fails to detect the magic at $p_c > p \geq p_{c,2}$.



\section{Relationship of stabilizer fidelity and log-free robustness of magic}\label{sec:boundLR}
In this section, we show that the stabilizer fidelity is lower bounded by the log-free robustness of magic:
\begin{lemma}
The stabilizer fidelity of mixed states $D_\text{F}$ lower bounds the log-free robustness of magic $\text{LR}$
\begin{equation}
    D_\text{F}(\rho)\leq \text{LR}(\rho)\,.
\end{equation}
\end{lemma}
\begin{proof}
First, we note that $\alpha-z$ R\'enyi entropies can be written as~\cite{rubboli2024mixed}
\begin{equation}
    D_{\alpha,z}(\rho)=\min_{\sigma\in\text{STAB}}\frac{1}{\alpha-1}\ln(\text{tr}[(\rho^{\frac{\alpha}{2z}} \sigma^{\frac{1-\alpha}{z}} \rho^{\frac{\alpha}{2z}})^{z}])\,.
\end{equation}
In particular, we have the stabilizer fidelity
\begin{equation}
    D_\text{F}(\rho)=D_{1/2,1/2}(\rho)
\end{equation}
and the generalized robustness of magic
\begin{equation}
     \Lambda^+(\rho)=\lim_{\alpha\rightarrow \infty} D_{\alpha,\alpha-1}(\rho)\,.
\end{equation}
First, from Ref.~\cite{lin2015investigating} it follows that $D_\text{F}(\rho)\leq \Lambda^+(\rho)$. This is due to the fact that $D_{\alpha,\alpha}$ increases monotonically with $\alpha$ as well as decreases with increasing $z$ when $\alpha>1$.
Then, Ref.~\cite{seddon2021quantifying}  (Lemma 11) showed that $\Lambda^+(\rho)\leq \text{LR}(\rho)$.
\end{proof}


\section{Efficient measurement of witness}\label{sec:measwitness}
Here, we show how to efficiently measure our witness $\mathcal{W}_\alpha$ for odd integer $\alpha>1$. Note that the scheme to efficiently measure $A_\alpha$ was originally provided in Ref.~\cite{haug2023efficient}.

First, we note that $A_\alpha$ can be re-written into the expectation value of a multi-copy observable via the replica trick~\cite{haug2022quantifying}
\begin{align}\label{eq:contraction2}
	 A_\alpha(\rho)=2^{-n}\sum_{P \in \mathcal{P}_n} \text{tr}(\rho P)^{2\alpha}=\text{tr}(\rho^{\otimes 2\alpha}\zeta_{\alpha}^{\otimes n})\,,
\end{align}
where $\zeta_{\alpha}=\frac{1}{2}\sum_{k=0}^3 (\sigma^k)^{\otimes 2\alpha}$.
One can show that for integer odd $\alpha$, $\zeta_{\alpha}$ has eigenvalues $\{+1,-1\}$, while for even $\alpha$ it is a projector with eigenvalues $\{0,2\}$. 
One can identify $A_1(\rho)=\text{tr}(\rho^2)$ with the purity.

To measure $A_\alpha$, let us first recall the Bell transformation as shown in Fig.~\ref{fig:Bell}
acting on two qubits
\begin{equation}
U_\text{Bell}=(H\otimes I_1) \text{CNOT}\,,
\end{equation}
where $H=\frac{1}{\sqrt{2}}(\sigma^x+\sigma^z)$ is the Hadamard gate, and the CNOT gate $\text{CNOT}=\exp(i\frac{\pi}{4}(I_1-\sigma^z)\otimes(I_1-\sigma^x))$. 

\begin{figure}[htbp]
	\centering	
	\subfigimg[width=0.24\textwidth]{}{BellMeasurement.pdf}
	\caption{Circuit for Bell transformation on two copies of $n$-qubit state $\rho$, where for each qubit pair one applies a CNOT and Hadamard gate (i.e. $n$ CNOT and Hadamard gates in total). This is followed by measurements in the computational basis.
	}
	\label{fig:Bell}
\end{figure}
It turns out $\zeta_{\alpha}$ is diagonalized  by $U_\text{Bell}$
\begin{align*}
&A_\alpha=\text{tr}(\rho^{\otimes 2\alpha}({U_\text{Bell}^{\otimes \alpha}}^\dagger \frac{1}{2}( (I_1\otimes I_1)^{\otimes \alpha}+(\sigma^z\otimes I_1)^{\otimes \alpha}\numberthis\label{eq:meas}\\&
+(I_1\otimes \sigma^z)^{\otimes \alpha}+(-1)^{\alpha}(\sigma^z\otimes \sigma^z)^{\otimes \alpha})U_\text{Bell}^{\otimes \alpha})^{\otimes n})\,.
\end{align*}
Notably, while $A_\alpha$ is written in terms of $2\alpha$ copies of $\rho$, it suffices to actually only prepare $2$ copies of $\rho$ at the same time.
Using this result, Ref.~\cite{haug2023efficient} constructed Algorithm~\ref{alg:SEmeas}, which is efficient for odd integer $\alpha>1$.
Basically, one prepares two copies of $\rho$, applies Bell transformation, measures in computational basis, repeats this $O(\alpha)$ times, and  performs some classical post-processing in $O(\alpha n)$ time.
Note that the purity, which is needed for $\mathcal{W}_\alpha$, is given by $A_1(\rho)=\text{tr}(\rho^2)$, and can be computed with the same algorithm and complexity.

The total efficiency is as follows:
\begin{theorem}[Efficient witness of magic]\label{thm:witness_sup}
For a given (mixed) $n$-qubit state $\rho$ and odd $\alpha$, there exist an efficient algorithm to measure $A_\alpha(\rho)$ to additive precision $\epsilon$ with failure probability $\delta$ using $O(\alpha\epsilon^{-2}\log(2/\delta))$ copies of $\rho$, $O(1)$ circuit depth, and $O(\alpha n\log(2/\delta))$ classical post-processing time. 
\end{theorem}
\begin{proof}
This has been previously shown using Hoeffding's inequality~\cite{haug2023efficient}, which we reproduce for completeness:
Given estimator $\hat{A}_\alpha$ from Algorithm~\ref{alg:SEmeas}, mean value $A_\alpha$, additive error $\epsilon$, failure probability $\delta$, range of outcomes $\Delta\lambda$ and number $L$ of repetitions of the algorithm, Hoeffding's inequality is given by
\begin{equation}\label{eq:Hoeffding2}
    \delta\equiv\text{Pr}(\vert \hat{A}_\alpha - A_\alpha\vert\ge \epsilon)\le 2\exp\left(-\frac{2\epsilon^2 L}{\Delta\lambda^2}\right)\,.
\end{equation}
Now, we have $\Delta\lambda=2$ as the possible outcomes are $\pm1$. Then, by inverting, we get
\begin{equation}
    L \leq 2\epsilon^{-2}\log(2/\delta)\,.
\end{equation}
As each run of the algorithm requires $2\alpha$ copies of $\rho$, we need in total $O(\alpha \epsilon^{-2}\log(2/\delta))$ copies. The post-processing is linear in $n$, thus we have $O(\alpha n\epsilon^{-2}\log(2/\delta))$ post-processing time. Finally, Bell transformations require only constant circuit depth, with $n$ CNOT gates and Hadamard gates in parallel.


\end{proof}






\begin{algorithm}[h]
 \SetAlgoLined
 \LinesNumbered
  \SetKwInOut{Input}{Input}
  \SetKwInOut{Output}{Output}
   \Input{ $n$-qubit state $\rho$; integer $\alpha$; $L$ repetitions;%
   %
   }
    \Output{$A_\alpha(\rho)$
    }

$A_\alpha= 0$

 \SetKwRepeat{Do}{do}{while}
    \For{$k=1,\dots,L$}{

    \For{$j=1,\dots,\alpha$}{
        Prepare $\eta=U_\text{Bell}^{\otimes n}\rho^{\otimes 2} {U_\text{Bell}^{\otimes n}}^\dagger$

        Sample in computational basis $\boldsymbol{r}^{(j)}\sim  \bra{r}\eta\ket{r}$
    }
    $b= 1$

        \For{$\ell=1,\dots,n$}{

            $\nu_1=\bigoplus_{j=1}^\alpha r^{(j)}_{2\ell-1}$;             $\nu_2=\bigoplus_{j=1}^\alpha r^{(j)}_{2\ell}$

             \uIf{$\alpha$ $\mathrm{is\,\,odd}$}{
               $b= b\cdot (-2\nu_1 \cdot\nu_2+1)$
              }
              \Else{
                $b= b\cdot 2(\nu_1-1) \cdot(\nu_2-1)$
              }
        }

    $A_\alpha= A_\alpha+b/L$
    }
 \caption{Measure $A_\alpha$ using Bell measurements.}
 \label{alg:SEmeas}
\end{algorithm}




\section{Efficient testing of magic for mixed states}\label{sec:testing}
Here, we give the detailed on proof on testing magic for mixed states with entropy $S_2=O(\log n)$. 

\begin{theorem}[Efficient testing of magic]\label{thm:testing_sup}
Let $\rho$ be an $n$-qubit state with $S_2(\rho)=O(\log n)$ where it is promised that
\begin{align*}
%
%
%
\mathrm{either}\quad (a)& \,\,\mathrm{LR}(\rho)=O(\log n) \,\,\mathrm{and}\,\,D_\mathrm{F}(\rho)=O(\log n) \,,\\
\mathrm{or}\quad (b)& \,\, \mathrm{LR}(\rho)=\omega(\log n)\,\,\mathrm{and}\,\, D_\mathrm{F}(\rho)=\omega(\log n)\,.
\end{align*} 
%
%
%
%
%
%
Then, there exist an efficient quantum algorithm to distinguish case ($a$) and ($b$) using $\mathrm{poly}(n)$ copies of $\rho$ with high probability. 
%
%
%
%
%
%
%
%
%
\end{theorem}
\begin{proof}
First, let us consider case ($a$), where we have $\text{LR}(\rho)=O(\log n)$. We recall that $\mathcal{W}_3(\rho)\leq 2\text{LR}(\rho)$. From this, it immediately follows that $\mathcal{W}_3(\rho)=O (\log n)$. As we demand that $S_2(\rho)=O(\log n)$, we have $-\frac{1}{2}\ln A_3(\rho)=O(\log n)$.

Next, let us consider case ($b$): Here, we have that $D_\text{F}(\rho)=\omega(\log n)$. 
We now give a lower bound on $-\frac{1}{2}\ln A_3(\rho)$ via $D_\text{F}$. In particular, we have
\begin{equation}
    D_\text{F}(\rho)=\min_{\sigma\in \text{STAB}}-\ln \mathcal{F}(\rho,\sigma) \leq \min_{\ket{\phi}\in \text{STAB}_\text{pure}}-\ln \bra{\phi}\rho\ket{\phi}\,.
\end{equation}
Here, we relaxed the minimization over the set of mixed stabilizer states to the minimization of pure stabilizer states only.
Then, Ref.~\cite{iyer2024tolerant} (Theorem 5.14) showed that if $A_3\geq \gamma$ with some $\gamma$, then $\max_{\ket{\phi}} \bra{\phi}\rho\ket{\phi}\geq \Omega(\gamma^{1089})$. Here, the power can be significantly improved in future works.
This implies that $\max_{\ket{\phi}} \bra{\phi}\rho\ket{\phi}\geq \Omega(A_3^{1089})$, and thus
\begin{equation}
D_\text{F}(\rho)\leq \min_{\ket{\phi}\in \text{STAB}_{\text{pure}}}-\ln \bra{\phi}\rho\ket{\phi} \leq \Omega(-\log A_3(\rho))\,.
\end{equation}
Due to $D_\text{F}(\rho)=\omega(\log n)$ by assumption, we have $-\frac{1}{2}\ln A_3(\rho)=\omega(\log n)$.

Now, it remains to show that one can efficiently distinguish $-\ln A_3=O(\log n)$ from $-\ln A_3=\omega(\log n)$. There exist an efficient algorithm to estimate $A_3$ to $\epsilon$ additive precision using $O(\epsilon^{-2})$ copies~\cite{haug2023efficient}, as we summarized in \SM{}~\ref{sec:measwitness}.
We now use Hoeffding's inequality 
\begin{equation}\label{eq:Hoeffding}
    \text{Pr}(\vert \hat{A}_3 - A_3\vert\ge \epsilon)\equiv\delta\le 2\exp\left(-\frac{2\epsilon^2 L}{\Delta\lambda^2}\right)\,,
\end{equation}
where $\hat{A}_3$ is the estimator for $A_3$ using $L$ measurements, $\delta$ is the failure probability, i.e. that the estimator $\hat{A}_3$ gives an error larger than $\epsilon$, and $\Delta\lambda$ the range of possible measurement outcomes. For the algorithm to estimate $A_3$~\cite{haug2023efficient}, the possible measurement outcomes are $\pm1$, and thus $\Delta\lambda=2$.  

Now, we need to distinguish the low-magic case $-\ln A_3^{\text{low}}=O(\log n)$ (e.g. $A_3=n^{-c}$ with constant $c>0$) from the high magic case $-\ln A_3^{\text{high}}=\omega(\log n)$ (e.g. $A_3^{\text{high}}=2^{-\ln^2(n)}$) while allowing only a small failure probability $\delta$.
Let us choose the decision boundary as $\epsilon_0=\frac{1}{2}n^{-c}$, i.e. when we measure $\hat{A}_3(\rho)>\epsilon_0$ then we say the state has low magic, else if we measure $\hat{A}_3(\rho)<\epsilon_0$ we say that the state has high magic. Further, let us choose the number of measurements as $L=n^{2c+1}=\text{poly}(n)$.

Then, the probability to wrongly classify a low-magic state as high magic is given by
\begin{gather}
    \delta^{\text{low}}\equiv\text{Pr}(\hat{A}_3^{\text{low}}\leq A_3^{\text{low}}-\epsilon ) =\text{Pr}(\hat{A}_3^{\text{low}}\leq \epsilon_0 )\\
    =2\exp\left(-\frac{(A_3^{\text{low}}-\epsilon_0)^2 L}{2}\right)=2\exp\left(-\frac{(n^{-c}-\frac{1}{2}n^{-c})^2 n^{2c+1}}{2}\right)=2\exp\left(-\frac{n}{8}\right)=O(2^{-n})\,.
\end{gather}
Next, the probability to wrongly classify a high-magic state as low-magic is given by
\begin{gather}
    \delta^{\text{high}}\equiv\text{Pr}(\hat{A}_3^{\text{high}}\geq A_3^{\text{high}}+\epsilon ) =\text{Pr}(\hat{A}_3^{\text{high}}\geq \epsilon_0 )\\
    =2\exp\left(-\frac{(A_3^{\text{high}}-\epsilon_0)^2 L}{2}\right)=2\exp\left(-\frac{(2^{-\ln^2(n)}-\frac{1}{2}n^{-c})^2 n^{2c+1}}{2}\right)=O(2^{-n})\,.
\end{gather}
Thus, we can distinguish low and high magic states with exponentially low failure rate using a polynomial number of measurements.
%
%
%
\end{proof}


\section{Certifying noisy magic resource states}\label{sec:cliffUnital}
Now, we show that using our methods we can efficiently certify magic resource states under noise. In particular, we want to certify whether a given noisy state contains a low or high number of T-states $\ket{T}=(\ket{0}+e^{-i\pi/4}\ket{1})/\sqrt{2}$. T-states are used to generate magic T-gates for universal fault-tolerant quantum computers~\cite{bravyi2005universal}. 

Such certification task of T-states are relevant for fault-tolerant quantum computing.  To run universal algorithms, one requires many copies of single-qubit T-states which can be used to generate T-gates. 
For example, let us assume that we are given a magic resource state from an untrusted source.  They claim that the given state is a tensor product of many single-qubit T-states. 
However, the T-states were affected by noise, where the noise model is not known. As full tomography is prohibitively expensive, one would like to have a simple check of the contained magic states.  In particular, can one verify whether the untrusted source indeed provided many T-states, or actually just mostly provided non-magical states?



In particular, we consider $n$-qubit states with $t$ T-states where a noise channel $\Lambda_\text{C}(\rho)$ is applied to
\begin{equation}
    \rho_t= \Lambda_\text{C}(\ket{T}^{\otimes t} \ket{0}^{\otimes(n-t)}\bra{T}^{\otimes t}\otimes \bra{0}^{\otimes(n-t)})
\end{equation}
with T-state $\ket{T}=\frac{1}{\sqrt{2}}(\ket{0}+e^{-i\pi/4}\ket{1})$ and stabilizer state $\ket{0}$.
As noise channel, we consider mixed unital Clifford channels, which are given by
\begin{equation}
    \Lambda_\text{C}(\rho)=\sum_{i} p_i U_\text{C}^{(i)} \rho {U_\text{C}^{(i)}}^\dagger
\end{equation}
where $\sum_i p_i=1$, $p_i\geq0$, and $U_\text{C}^{(i)}$ are Clifford unitaries, i.e. unitaries that can be generated from CNOT gates, S-gates and Hadamard gates only. For example, as special case, $\Lambda_\text{C}(\rho)$ contains Pauli channels. Note that mixed unital Clifford channels are Clifford channels, and thus cannot increase magic.



Now, we ask whether one can distinguish states with different $t$. Here, we assume low entropy $S_2(\rho_t)=-\ln\text{tr}(\rho_t^2)=O(\log n)$. This is necessary as the magic of states with high entropy cannot be tested in general~\cite{bansal2024pseudorandomdensitymatrices}.

Now, using our test we can efficiently distinguish $\rho_t$ between small and large $t$ when $S_2(\rho_t)=O(\log n)$ for any mixed unital Clifford channel:

\begin{proposition}[Testing noisy magic states]
There is an efficient quantum algorithm to certify whether given noisy $n$-qubit quantum state $\rho_t=\Lambda_\text{C}((\ket{T}\bra{T})^{\otimes t}\otimes (\ket{0} \bra{0})^{\otimes(n-t)})$ contains
either $(a)$ $t=O(\log n)$ or $(b)$ $t=\omega(\log n)$ T-states $\ket{T}=\frac{1}{\sqrt{2}}(\ket{0}+e^{-i\pi/4}\ket{1})$ when it is subject to arbitrary $n$-qubit mixed unital Clifford channels $\Lambda_\text{C}(\rho)$ and $S_2(\rho_t)=O(\log n)$. 
%
%
%
%
%
%
\end{proposition}
\begin{proof}
We can efficiently distinguish $(a)$ and $(b)$ using our tester by measuring $A_3(\rho_t)$. 

For $(a)$ with $t=O(\log n)$, we have $\text{LR}=O(\log n)$. This follows from the fact that $\ket{\psi_t}=\ket{T}^{t}\otimes \ket{0}^{n-t}\bra{T}^{t}\otimes \bra{0}^{n-t}$ can be prepared from $t$ T-gates, and thus has $\text{LR}(\ket{\psi_t})=O(t)=O(\log n)$ due to sub-additivity~\cite{howard2017robustness}. As $\text{LR}$ is a magic monotone, it can only decrease under Clifford channels $\text{LR}(\Lambda_\text{C}(\ket{\psi_t}))\leq \text{LR}(\ket{\psi_t})$. Finally, we have 
\begin{equation}
    \mathcal{W}_3=-\frac{1}{2}\ln A_3-\frac{5}{2}S_2\leq 2 \text{LR}
\end{equation}
and  $S_2(\rho_t)=O(\log n)$ which implies $-\frac{1}{2}\ln A_3=O(\log n)$. 

Next, we consider case $(b)$ with large number of T-states where $t=\omega(\log n)$. 
For $\ket{\psi_t}$, we get $-\frac{1}{2}\ln A_3(\ket{\psi_t})=\frac{1}{2}t\ln\frac{8}{5}=\omega(\log n)$ from explicit calculation~\cite{haug2023stabilizer} when $t=\omega(\log n)$. 


Now, under mixed unital Clifford channel $\Lambda_\text{C}(\rho)$, we find that $-\frac{1}{2}\ln A_3(\Lambda_\text{C}(\ket{\psi_t}))$ can only increase: %
%
%
%
\begin{lemma}\label{lem:unitalcliff}
Applying arbitrary mixed unital Clifford channel  $\Lambda_\text{C}(\rho)$ onto state $\rho$ monotonously increases the $\alpha$-moment of Pauli spectrum for any integer $\alpha>1$, i.e.  
\begin{equation}
    -\ln A_\alpha(\Lambda_\text{C}(\rho))\geq -\ln A_\alpha(\rho)\,.
\end{equation}
\end{lemma} 
\begin{proof}

To show this, we have
\begin{gather}
    A_\alpha(\Lambda_\text{C}(\rho))=
    2^{-n}\sum_{P\in\mathcal{P}_n} \text{tr}(\Lambda_\text{C}(\rho) P)^{2\alpha}=
    2^{-n}\sum_{P\in\mathcal{P}_n} \text{tr}(\sum_i p_i \rho_i P)^{2\alpha}
    %
\end{gather}
where we introduced the Clifford transformed state $\rho_i=U_\text{C}^{(i)}\rho {U_\text{C}^{(i)}}^\dagger$. Next, we expand the power as
\begin{gather}
    A_\alpha(\Lambda_\text{C}(\rho))
    =2^{-n} \sum_{i_1,i_2,\dots,i_{2\alpha}} \sum_{P\in\mathcal{P}_n}\text{tr}(p_{i_1} \rho_{i_1} P)\text{tr}(p_{i_2} \rho_{i_2} P)\dots \text{tr}(p_{i_{2\alpha}} \rho_{i_{2\alpha}} P)\\
    \leq 2^{-n} \sum_{i_1,i_2,\dots,i_{2\alpha}} p_{i_1}p_{i_2}\dots p_{i_{2\alpha}}\sum_{P\in\mathcal{P}_n}\vert\text{tr}( \rho_{i_1} P)\vert\vert\text{tr}( \rho_{i_2} P)\vert\dots \vert\text{tr}( \rho_{i_{2\alpha}} P)\vert\,.
\end{gather}
We now bound this using from H\"olders inequality~\cite{chen2014brief}
\begin{equation}
    \sum_j a_{1,j}^{\lambda_1}a_{2,j}^{\lambda_2}\dots a_{K,j}^{\lambda_K} \leq (\sum_j a_{1,j})^{\lambda_1}(\sum_j a_{2,j})^{\lambda_2}\dots (\sum_j a_{K,j})^{\lambda_{K}}
\end{equation}
with $\sum_j \lambda_j=1$, $\lambda_j\geq0$ and $a_{k,j}\geq0$. 
Now, we identify $j=P$ $\lambda_P=1/(2\alpha)$, $K=2\alpha$, and $a_{i_s,P}=\vert\text{tr}(\rho_{i_s} P)\vert^{2\alpha}$ with $s=1,\dots,2\alpha$.
Then, we apply H\"olders inequality to get
\begin{gather}
 A_\alpha(\Lambda_\text{C}(\rho)) 
 \leq 2^{-n} \sum_{i_1,i_2,\dots,i_{2\alpha}} p_{i_1} p_{i_2}\dots p_{i_{2\alpha}}\sum_{P\in\mathcal{P}_n}\vert\text{tr}( \rho_{i_1} P)\vert\vert\text{tr}( \rho_{i_2} P)\vert\dots \vert\text{tr}( \rho_{i_{2\alpha}} P)\vert \\
 \leq  2^{-n} \sum_{i_1,i_2,\dots,i_{2\alpha}} p_{i_1}p_{i_2}\dots p_{i_{2\alpha}}(\sum_{P\in\mathcal{P}_n} \vert\text{tr}( \rho_{i_1} P)\vert^{2\alpha})^{\frac{1}{2\alpha}}(\sum_{P\in\mathcal{P}_n} \vert\text{tr}( \rho_{i_2} P)\vert^{2\alpha})^{\frac{1}{2\alpha}}\dots (\sum_{P\in\mathcal{P}_n} \vert\text{tr}( \rho_{i_{2\alpha}} P)\vert^{2\alpha})^{\frac{1}{2\alpha}}\\
= \sum_{i_1,i_2,\dots,i_{2\alpha}} p_{i_1} p_{i_2}\dots p_{i_{2\alpha}} A_\alpha(\rho_{i_1})^{\frac{1}{2\alpha}}
 A_\alpha(\rho_{i_2})^{\frac{1}{2\alpha}}\dots
 A_\alpha(\rho_{2\alpha})^{\frac{1}{2\alpha}}\,.
\end{gather}
Now, we note that $A_\alpha(\rho_i)=A_\alpha(\rho)$ as Clifford unitaries leave $A_\alpha(\rho_i)$ invariant. 
Thus, we finally get
\begin{equation}
    A_\alpha(\Lambda_\text{C}(\rho)) \leq \sum_{i_1,i_2,\dots,i_{2\alpha}} p_{i_1} p_{i_2} \dots p_{i_{2\alpha}}A_\alpha(\rho) = A_\alpha(\rho)\,.
\end{equation}
where we recall $\sum_{i_s} p_{i_s}=1$.
\end{proof}

Thus, according to Lemma~\ref{lem:unitalcliff}, $-\ln A_3$ can only increase under mixed unital Clifford channels, and we have for $t=\omega(\log n)$
\begin{equation}
 -\frac{1}{2}\ln A_3(\Lambda_\text{C}(\ket{\psi_t})) \geq -\ln A_\alpha(\ket{\psi_t})=\omega(\log n)\,.
\end{equation}
Now, using Thm.~\ref{thm:witness_sup}, we can efficiently distinguish $(a)$ with $-\ln A_3=O(\log n)$ and $(b)$ with $-\ln A_3=\omega(\log n)$, which can be shown via Hoeffding's inequality similar to the proof of \SM{}~\ref{sec:testing}.

\end{proof}


\section{Witnessing magic in typical states under depolarizing noise} \label{sec:witness_noise}

In this section, we study our magic witness $\mathcal{W}_\alpha$ for typical states subject to global
depolarizing noise $\rho_\mathrm{dp}
 = (1-p)\ket{\psi}\bra{\psi} + p I/2^n$ 
 with a probability $p$. The mixed-state SRE $M_\alpha=1/(1-\alpha)(\ln A_\alpha+S_2)$ for $n\gg1$ is given by~\cite{turkeshi2023pauli}
 \begin{equation}
   M_\alpha^\mathrm{typ} = \frac{1}{1-\alpha}\ln \left[ \frac{(\eta-1) (2b)^\alpha   \Gamma \left(\alpha+\frac{1}{2}\right) (1-p)^{2\alpha}}{\sqrt{\pi }d }+\frac{1}{d}\right] + \frac{1}{1-\alpha} S_2[\rho_\mathrm{dp}],
\end{equation}
where the R\'enyi-2 entropy of the depolarized state is given by $S_2[\rho_\mathrm{dp}]= -\ln\left[(1-p)^2 + p(2-p)/2^n \right]$, $\Gamma(x)$ is the gamma function, $b=(d/2+1)^{-1}$, $d=2^n$, and  ${\eta=d^2}$. For any fixed $p<1$ and $n \to \infty$, we find that the leading term of the mixed-state SRE $M_\alpha = D_\alpha n + c_\alpha$ is unchanged from that of the pure state. Namely, $D_\alpha = 1/(\alpha-1)$ for $\alpha \geq 2$ and $D_\alpha=1$ for $\alpha<2$, while the probability $p$ only affects the subleading constant $c_\alpha$. As a consequence, the witnesses $\mathcal{W}_\alpha$ are remarkably effective in detecting magic in typical states even in the presence of noise, where the state becomes a mixed state. 
At $p=1$, the state becomes the maximally mixed state $\rho_\mathrm{dp}(p=1) = I / 2^n$, which is a mixed stabilizer state. In this case, the witnesses take the value $-2n \ln 2$, independent of the R\'enyi index $\alpha$. The negative value is expected, since the state is a mixed stabilizer state, so that the witnesses would not classify the state as nonstabilizer state.


Let us be more concrete when $\mathcal{W}_\alpha>0$, i.e. detects magic.
In particular, we consider exponential noise $p=1-2^{-\beta n}$ and determine for which $\beta$ the witness $\mathcal{W}_\alpha$ can successfully detect magic. 
We now compute the explicit scaling of $\mathcal{W}_\alpha$ with $n\gg1$, where we ignore constants and subleading terms.
First, when considering the entropy term, we find that $S_2(\rho_\text{dp})\approx 2\beta n\ln 2$ for $\beta\leq1/2$. 
Then, we have
\begin{equation}
\mathcal{W}_\alpha(\rho_\text{dp})\approx\frac{1}{1-\alpha}\ln(2^{n(1-\alpha)}2^{-2\alpha\beta n} +2^{-n})+\frac{1}{1-\alpha}2\beta n\ln 2 -4\beta n\ln2\,.
\end{equation}
We now ask for what $\beta$ we witness magic $\mathcal{W}_\alpha>0$.
For $\alpha>1$, we can drop the $2^{n(1-\alpha)}2^{-2\alpha\beta n}$ term in the logarithm as it is larger than $2^{-n}$. Then, we find $\beta<(4\alpha-2)^{-1}$. 
For $\frac{1}{2}\leq\alpha<1$, we can instead drop the $2^{-n}$ in the first logarithm as it decays faster than the other term. Then, a straightforward calculation yields $\beta<\frac{1}{2}$. 


Next, we consider  the filtered witness $\Tilde{\mathcal{W}}_\alpha$ of~\eqref{eq:filtered_witness}, where we find
\begin{equation}    \Tilde{\mathcal{W}}_\alpha(\rho_{\text{dp}}) = \Tilde{M}_\alpha(\ket{\psi}) + 2\ln(1-p) = \Tilde{M}_\alpha(\ket{\psi}) - 2\beta n\ln2,
\end{equation}
where we recall that $\Tilde{M}_\alpha$ is the filtered SRE in~\eqref{eq:filtered_sre}. For Haar random states, $\Tilde{M}_\alpha=n \ln 2$ for any $\alpha$~\cite{turkeshi2023pauli}. Thus, we find $\Tilde{\mathcal{W}}_\alpha>1$ when $\beta<\frac{1}{2}$ for all $\alpha\geq1/2$. Remarkably, $\Tilde{\mathcal{W}}_\alpha$ for larger $\alpha$ can detect magic as well as $\Tilde{\mathcal{W}}_{1/2}$, while being efficiently measurable for odd integer $\alpha$~\cite{haug2023efficient}. Note that this is true for any state with flat Pauli spectrum subjected to depolarizing noise, since $\Tilde{M}_\alpha$ is independent of $\alpha$. Indeed, typical states were shown to have a flat Pauli spectrum in~\cite{tarabunga2025efficientmutualmagicmagic}.



