\paragraph{ARAP Error.}
To measure local distortion between original and deformed meshes, we compute a best-fit rotation matrix $\mathbf{R}$ for each face $\triangle = (i_0, i_1, i_2) \in F$. Let the vertex coordinates of the original and deformed face be $p_k$ and $\hat{p}_k$, respectively, for $k \in \{0,1,2\}$ (Eq.~\ref{eq:pk_def}). We first compute their centroids, $c$ and $\hat{c}$, as follows:

\begin{equation}
p_k,\; \hat{p}_k 
\quad \text{for} \quad k \in \{0,1,2\},
\label{eq:pk_def}
\end{equation}

\vskip -0.1in

\begin{equation}
c = \frac{p_0 + p_1 + p_2}{3},
\quad
\hat{c} = \frac{\hat{p}_0 + \hat{p}_1 + \hat{p}_2}{3},
\label{eq:centroids}
\end{equation}

Then, we form local point sets centered by these centroids:

\begin{equation}
P =
\begin{bmatrix}
p_0 - c \\
p_1 - c \\
p_2 - c
\end{bmatrix},
\quad
\hat{P} =
\begin{bmatrix}
\hat{p}_0 - \hat{c} \\
\hat{p}_1 - \hat{c} \\
\hat{p}_2 - \hat{c}
\end{bmatrix},
\label{eq:centered_points}
\end{equation}

Next, the optimal rotation $\mathbf{R}$ aligning $P$ to $\hat{P}$ is obtained via the SVD-based Kabsch algorithm. Using this rotation, the ARAP residual for each face $\triangle$ is calculated as:

\begin{equation}
\mathrm{Err}_{\triangle}
= \sum_{k=0}^{2}
\left\| \mathbf{R}(p_k - c) - (\hat{p}_k - \hat{c}) \right\|^2.
\label{eq:local_arap}
\end{equation}

We then compute the overall ARAP Error by summing residuals across all faces and normalize it by the total number of faces $|F|$ to obtain the Mean ARAP Error:

\begin{equation}
\mathrm{mARAP_{Error}}
= \frac{1}{|F|} \sum_{\triangle \in F} \mathrm{Err}_{\triangle}.
\label{eq:mean_arap_error}
\end{equation}

A lower $\mathrm{mARAP_{Error}}$ indicates better preservation of local rigidity in the deformation, enabling fair comparisons regardless of mesh size or face count.


\section{3D Mesh Generation Based on Depth Approach}
The depth-map-based 3D mesh generation discussed in Section~\ref{sec:3d_mesh_generation} is formalized as the algorithm shown in Algorithm~\ref{alg:algorithm}. We set the depth threshold (\(\tau_d\)) to 0.1 and defined the background threshold (\(\tau_b\)) as the mean depth value plus 0.3. This approach effectively removes background noise.

\begin{algorithm}[h]
    \caption{Depth Map and Mesh Generation}
    \label{alg:algorithm}
    \begin{algorithmic}
        \INPUT $\mathcal{D}$: Depth map (normalized to [0, 1]), $\tau_d$: Depth threshold, $\tau_b$: Background threshold
        \OUTPUT $\mathcal{M} = (\mathcal{V}, \mathcal{F})$, $\mathcal{M}$: Generated 3D mesh, $\mathcal{V}$: Set of vertex, $\mathcal{F}$: Set of facets \\
        \textbf{Step 1: Depth Map Extraction} \\
        \quad $\mathcal{D} \gets \text{Marigold}(\mathcal{I})$: \Comment{Extract depth map using Marigold} \\
        \textbf{Step 2: Vertex Mapping} \\
        \quad \textbf{For} each pixel $(x, y) \in \mathcal{D}$ \textbf{do} \\
        \quad \quad $z \gets \mathcal{D}(x, y)$: \Comment{Map depth value to $z$-coordinate} \\
        \quad \quad Add vertex $V(x, y, z)$ to $\mathcal{M}$ \\
        \textbf{Step 3: Facet Formation} \\
        \quad \textbf{For} each vertex $V(x, y, z) \in \mathcal{M}$ \textbf{do} \\
        \quad \quad if $|\mathcal{D}(x, y) - \mathcal{D}(\text{adjacent})| < \tau_d$ \\
        \quad \quad \quad Connect $V$ to adjacent vertices, add facet to $\mathcal{F}$ \\
        \textbf{Step 4: Artifact Reduction} \\
        \quad \textbf{For} each facet $(v_i, v_j, v_k) \in \mathcal{F}$ \textbf{do} \\
        \quad \quad if $|\mathcal{D}(v_i) - \mathcal{D}(v_j)| \geq \tau_d$ or $\mathcal{D}(v_i) < \tau_b$ \\
        \quad \quad \quad Remove $(v_i, v_j, v_k) \in \mathcal{M}$ \\
        \textbf{Return: } $\mathcal{M} = (\mathcal{V}, \mathcal{F})$: \Comment{Return the final 3D mesh} 
    \end{algorithmic}
\end{algorithm}

