\section{Notation}\label{appendix:notation}

We summarize the mathematical notation used throughout the manuscript in Table~\ref{tab:notation}.
\vspace{1cm}
\noindent

\begin{table}[H]
    \centering
    \resizebox{0.99\textwidth}{!}{%
    \begin{tabular}{r|l}
        Symbol & Description \\ \hline
        $H = (\mathcal{V}, \mathcal{E})$                                   & a hypergraph  \\
        $\mathcal{V}$                                                      & the set of nodes \\
        $\mathcal{V}_g = \{v\in \mathcal{V}:g_v=g\}$                       & the set of nodes in group $g$ \\
        $n = |\mathcal{V}|$                                                & the number of nodes \\
        $n_g = |\mathcal{V}_g|$                                            & the number of nodes in group $g$ \\
        $v \in \mathcal{V} $                                               & a node               \\
        $g,g_v \in\{0,1\}$                                                 & group membership (of a node $v$) \\
        $k_v$                                                              & the degree of node $v$ \\
        $\bar{k}$, $\bar{k}_g$                                             & the average degree (conditioned on a group)\\
        $\overline{k^2}$, $\overline{k^2}_g$                               & the second moment of the degree distribution (conditioned on a group)\\
        $p_g(k)$                                                           & the distribution of degrees $k$ within group $g$\\
        $\kappa_v$                                                         & the hidden variable of node $v$\\
        $\bar{\kappa}$, $\bar{\kappa}_g$                                   & the average of the hidden variables (conditioned on a group)\\
        $\rho_g(\kappa)$                                                   & the distribution of hidden variables within group $g$\\
        $\bar{k}$                                                          & the average degree\\
        $\mathcal{E}$                                                      & the set of hyperedges \\
        $e \in \mathcal{E}$                                                & a hyperedge \\
        $s, s_e = |e|$                                                     & the size (of a hyperedge $e$)\\
        $s_\mathrm{max} = \max \{s_e:e\in\mathcal{E}\}$                    & the size of the largest hyperedge \\
        $r, r_e = |\{v\in e: g_v=1\}|$                                     & type (of hyperedge $e$, i.e., the number of group $g=1$ nodes in it)\\
        $m = |\mathcal{E}|$                                                & the number of hyperedges \\
        $m_s$                                                              & the number of hyperedges of size $s$ \\
        $m_{s,r}$                                                          & the number of hyperedges of size $s$ and type $r$ \\
        $a_{s,r}^{(g)}$                                                    & the affinity score of nodes of type $g$ in hyperedges of size $s$ and type $r$ \\
        $b_{s,r}^{(g)}$                                                    & the baseline score of nodes of type $g$ in hyperedges of size $s$ and type $r$ \\
        $h, h_{s,r}^{(g)}$                                                 & the hyperedge homophily score (of nodes of type $g$ in hyperedges of size $s$ and type $r$)\\
        $x_v(t)\in\{0,1\}$                                                  & the state of node $v$ at time $t$\\
        $i(t)$                                                              & the total number of informed nodes at time $t$\\
        $i_g(t)$                                                            & the total number of informed nodes in group $g$ at time $t$\\
        $i_{e,g}(t)$                                                        & the number of informed nodes in group $g$ in hyperedge $e$ at time $t$\\
        $t\in[0,\infty)$                                                    & a point in time \\
        $t^{(g)}_{90}$                                                      & the time at which $90\%$ of nodes are informed\\
        $t_f$                                                               & the time at which a fraction $f$ of nodes are informed\\
