\subsection{Pseudo Code for SwarmAgentic}
\label{app: Pseudo Code for SwarmAgentic}

\begin{algorithm}[H]
  \centering
  \caption{Agentic System Search with Particle Swarm Optimization}
  \begin{algorithmic}[1]               % [1] = add line numbers (optional)

  \REQUIRE LLM temperatures $\{\text{temp}_i\}_{i=1}^n$, fitness function
           $J : x \!\to\! \mathbb{R}$;  % back-slash tightens spaces a bit
           % prompt-based agentic system generation function $G$;
           system initialization function $\text{LLM}_{\text{init\_team}}$;
           system code-generation function $\text{LLM}_{\text{write\_forward}}$;
           performance evaluation function $\text{LLM}_{\text{eval}}$;
           system flaw identification function $\text{LLM}_{\text{flaw}}$;
           velocity initialization function $\text{LLM}_{\text{init\_vel}}$;
           failure identification function  $\text{LLM}_{\text{identify\_fail}}$;
           learning from failure function $\text{LLM}_{\text{fail}}$;
           global best guidance function $\text{LLM}_{\text{glob}}$;
           personal best guidance function $\text{LLM}_{\text{pers}}$;
           velocity update function $\text{LLM}_{\text{vel}}$;
           position update function $\text{LLM}_{\text{pos}}$;

           swarm size $N$, max iteration $T$
  \STATE \textbf{Input:}  dataset for training $D$
  \STATE \textbf{Output:} global best checkpoint $g$

  \STATE \textit{// Initialize search}
  \FOR{$i \gets 1$ \TO $N$}
      \STATE \textit{// LLM\textsubscript{write\_forward} enables automatic code execution}
      \STATE \textbf{Initialize position:} $x_i^{(0)} \gets \text{LLM}_{\text{init\_team}}(\text{temp}_i)$
      \STATE \textbf{Initialize fitness:}  $j_i^{(0)} \gets J(x_i^{(0)},D)$
      \STATE \textbf{Identify Problem:} $p_{i}^{(0)} \gets \text{LLM}_{\text{eval}}(x_i^{(0)}, j_i^{(0)})$
      \STATE \textbf{Refection Summarization:} $f_{i}^{(1)} \gets \text{LLM}_{\text{flaw}}(x_i^{(0)}, p_{i}^{(0)})$
      \STATE \textbf{Initialize velocity:} $v_i^{(1)} \gets \text{LLM}_{\text{init\_vel}}(x_i^{(0)}, f_{i}^{(1)}))$
      \STATE \textbf{Initialize personal best:} $p_i^* \gets x_i^{(0)}$,\;
             $j_{p,i} \gets j_i^{(0)}$
      \STATE \textbf{Update Position:} $x_i^{(1)} \gets \text{LLM}_{\text{pos}}(x_i^{(0)}, v_i^{(1)})$\hfill 
  \ENDFOR
  \STATE \textbf{Initialize global best}: $g \gets \arg\max_{i} j_{p,i}^{(0)},\; f_g \gets \max_{i} j_{p,i}^{(0)}$

  \STATE \textit{// Start search}
  \FOR{$t\gets 1$ \TO $T$}
      \FORALL{$i = 1,\dots,N$ \textbf{(in parallel)}}
          \STATE \textbf{Execution:}
          \STATE \quad \textbf{Update Fitness:} $j_i^{(t)} \gets J(x_i^{(t)},D)$
          \STATE \quad\textbf{Identify Problem:} $p_{i}^{(t)} \gets \text{LLM}_{\text{eval}}(x_i^{(t)}, j_i^{(t)})$
          \STATE \quad\textbf{Refection Summarization:} $f_{i}^{(t+1)} \gets \text{LLM}_{\text{flaw}}(x_i^{(t)}, p_{i}^{(t)})$

          \textbf{Update Global Best:}\IF{$j_i^{(t+1)} > j_g$}
              \STATE $g \gets x_i^{(t+1)}$;\; $j_g \gets j_i^{(t+1)}$
          \ENDIF

          \textbf{Update Personal Best:}\IF{$j_i^{(t+1)} > j_p$}
              \STATE $p_i^* \gets x_i^{(t+1)}$;\; $j_{p,i} \gets j_i^{(t+1)}$
          \ENDIF
          \STATE \textbf{Update Velocity:}
          \STATE \quad \textit{// LLM\textsubscript{identify\_fail} identify the previous failed adjustments}
          \STATE \quad $c_f r_f  F(v_i^{(t)}) = \text{LLM}_{\text{fail}}(v_i^{(t)}, f_i^{(t)}, f_i^{(t+1)})$\hfill $\triangleright$ Eq. \eqref{eq:faliure}
          \STATE \quad $c_p r_p (p_i^* - x_i^{(t)}) = \text{LLM}_{\text{pers}}(x_i^{(t)}, p_i^*, f_i^{(t+1)})$\hfill $\triangleright$ Eq. \eqref{eq:personal_best}
          \STATE \quad $c_g r_g (g - x_i^{(t)}) = \text{LLM}_{\text{glob}}(x_i^{(t)}, g, f_i^{(t+1)})$\hfill $\triangleright$ Eq. \eqref{eq:global_best}
          \STATE \quad $v_i^{(t+1)} = \text{LLM}_{\text{vel}}(c_f r_f F(v_i^{(t)}), c_p r_p (p_i^* - x_i^{(t)}), c_g r_g (g - x_i^{(t)}))$\hfill $\triangleright$ Eq. \eqref{eq:update_vel}
          \STATE \textbf{Update Position:} $x_i^{(t+1)} = \text{LLM}_{\text{pos}}(x_i^{(t)}, v_i^{(t+1)})$\hfill $\triangleright$ Eq. \eqref{eq:position_update}


      \ENDFOR
  \ENDFOR

  \RETURN $g$
  \end{algorithmic}
  \label{alg:pso}
\end{algorithm}

\subsection{Prompt Repository}
\label{app: Prompt Repository}
We employ the following prompts to achieve the automated generation of agentic systems with PSO. Specifically, we use $\mathrm{LLM}_{\text{init\_team}}$ to initialize both the roles and the team for each particle at the start of the process, ensuring consistency in team composition and task allocation. $\mathrm{LLM}_{\text{write\_forward}}$ is then used to generate the corresponding code based on the initialized roles and the given workflow, enabling forward progression of each particle's function. To identify problems in the responses, we employ performance evaluation $\mathrm{LLM}_{\text{eval}}$, which analyzes the workflow and task execution to reveal underlying issues and explain their root causes in relation to the intended process. Once a problem is identified, flaw identification $\mathrm{LLM}_{\text{flaw}}$ is applied to trace it back to underlying issues in the role or team configuration. This step helps uncover structural or logical flaws that may hinder performance.

Next, we initialize the velocity of each particle $\mathrm{LLM}_{\text{init\_vel}}$, considering the current team composition and the identified design flaws. This initialization provides direction and momentum for adjustment in future iterations. We then examine the failed adjustments $\mathrm{LLM}_{\text{identify\_fail}}$ from the previous iteration using a specialized prompt designed to extract and document ineffective changes. The Learning from Failure prompt $\mathrm{LLM}_{\text{fail}}$ is used to suggest improved strategies, leveraging past failures to guide more effective future adjustments. To complement this, we use additional prompts to discover meaningful adjustments inspired by both the global best team $\mathrm{LLM}_{\text{glob}}$ and the personal best team $\mathrm{LLM}_{\text{pers}}$, promoting convergence towards optimal configurations. Velocity is updated $\mathrm{LLM}_{\text{vel}}$ by integrating suggestions from global best guidance, personal best guidance, and failure-driven learning. This multi-source adjustment balances exploration and exploitation. Finally, the team configuration is updated $\mathrm{LLM}_{\text{pos}}$ according to the plan generated during the velocity update phase, completing one full iteration of the optimization cycle and preparing for the next.

