\noindent\textbf{Compliance Scoring Mechanism.} 
Our compliance scoring tool enables experiment organizers to assign weights to various factors (see Table~\ref{table:parameters} for an example) and configure corresponding options, offering flexible, customized evaluation for diverse clinical settings. The overall compliance score (\(S_c\)) for each client is determined by assessing all the factors and is calculated as follows:

\begin{equation}
\label{eq1}
S_c = \frac{\sum_{i=1}^{n} \left( w_i \cdot s_i \right)}{\sum_{i=1}^{n} w_i}
\end{equation}
where \(n\) is the total number of compliance factors, \(w_i\) is the weight assigned to factor \(i\), and \(s_i\) is the selected option score for factor \(i\).
For instance, the \textit{anonymization practices} factor offers three options: \textit{ISO/TS 25237:2017 Fully Anonymized} (Score 1.0), \textit{Pseudonymized (Partial Anonymization)} (Score 0.7), and \textit{No Anonymization} (Score 0.5), with the tool defaulting to a $0.5$ threshold, adjustable by experiment owners, including setting it to $0$ if needed.


\begin{algorithm}
\caption{Adaptive Noise-Based Differential Privacy in Federated Learning}
\small % Reduce font size
\begin{algorithmic}[1] % Number every line
\State Initialize $\mathit{GLOBAL\_MODEL}$
\For{round $= 1$ to $\mathit{FED\_ROUNDS}$}
    \State \textbf{Client Training:}
    \For{each client $i$}
        \State $\mathit{CLIENT}_i \gets \textsc{Copy}(\mathit{GLOBAL\_MODEL})$
        \State $\mathit{CLIENT}_i \gets \textsc{Train}(\mathit{CLIENT}_i, \mathit{data}_i, \mathit{epochs}=1)$
    \EndFor
    \State Send $\{\mathit{CLIENT}_i\}$ to aggregator

    \State \textbf{DP Processing:}
    \For{each client $i$}
        \State $\mathit{DP}_i \gets \textsc{Copy}(\mathit{CLIENT}_i)$
        \State $\mathit{DP}_i \gets \textsc{DPTrain}(\mathit{DP}_i, \mathit{agg\_data}, \eta=\textsc{AdaptiveNoise}(c_i))$
    \EndFor

    \State \textbf{Aggregation:}
    \State $\mathit{GLOBAL\_MODEL} \gets \textsc{FedAvg}(\{\mathit{DP}_i\})$ \Comment{Fed Median/Prox/Yogi/Adam}

    \State \textbf{Broadcast} $\mathit{GLOBAL\_MODEL}$ to clients
\EndFor
\State \Return $\mathit{GLOBAL\_MODEL}$
\label{psuedo}
\end{algorithmic}
\end{algorithm}

