    \begin{tikzpicture}[node distance = .75cm, minimum size = .5cm, inner sep = .07cm, ultra thick]
        %\node[regular polygon, regular polygon sides=6, minimum width=2cm,draw,label=center:some text] (reg1) at (0,0){};
        \sheepHex{blue}{blue}{2}{(0,0)}
        \sheepHex{blueTop}{blue}{2}{(0, 1.75)}
