        \sheepHex{blueRight}{blue}{2}{(3, 0)}
        \emptyHex{EmptyC}{In}{(0, -1.75)}
        \emptyHex{inB}{Out 2}{(4.5, .875)}
        \blockHex{blockAA}{(-3, -1.75)}
        \blockHex{blockAB}{(-4.5, -.875)}
        \blockHex{blockC}{(-3, 1.75)}
        \blockHex{blockD}{(-1.5, 2.625)}
