\caption{Evaluation metrics for radiological image reconstruction}\label{tbl2}
\centering
\scriptsize 
\begin{tabular}{>{\centering\arraybackslash}m{4.5cm}|>{\centering\arraybackslash}m{5.5cm}|>{\centering\arraybackslash}m{6cm}}  
\hline
\hline
Name & Formula & Function \\  
\hline
