    \centering
    \subfigure[AraOS integration in the Cheshire SoC.] {
        \includegraphics[width=0.3\linewidth,trim=4 4 4 2,clip]{fig/araos_cheshire_arc.drawio}
        \label{fig:che_diag}
    }
    \subfigure[Matmul 32x32] {
        \includegraphics[width=0.2\linewidth]{fig/fmatmul32x32}
    }
    \subfigure[Matmul 64x64] {
        \includegraphics[width=0.2\linewidth]{fig/fmatmul64x64}
